A (constant free) unital non-symmetric categorical operad $\tP$ is a collection of categories $\{\tP_n\}_{n\geq 1}$ equipped with composition functors \eqref{equation:composition_maps}
which are strictly associative and unital.
\begin{equation}\label{equation:composition_maps}
    \tP_n\x \tP_{k_1} \x \cdots \x \tP_{k_n} \xrightarrow{\mu} \tP_{k_1+\cdots + k_n}
\end{equation} 
Operads in this text will be based order preserving surjections of finite (non-empty) ordinals. Let $\un{n}=[1<2<\cdots<n]$, $n\geq1$, and $f\colon \un{m}\to \un{n}$, be an order preserving surjective map. These~form a category $\Delta_s$. For $1\leq i\leq n$, identify the preimage~$f^{-1}(i)$ with a finite ordinal~$\un{m}_i$. 
For two composable maps 
$$\un{m}\xrightarrow{f} \un{k} \xrightarrow{g} \un{n}$$ 
and $i\in \un{n}$, there is an induced map between the preimages $(gf)^{-1}(i) \to g^{-1}(i)$, which is denoted by $f^i$. For $i\in \un{n}$ and $j\in \un{k}$ with $g(j)=i$ it holds $(f^i)^{-1}(j)=f^{-1}(j)$. When convenient, we will consider $\Delta_s$ as a 2-category with only identity 2-cells.

\begin{definition}\label{definition:ns-operad}
A non-symmetric categorical operad is a collection of categories $\{\tP_n\}_{n\geq 1}$, equipped with composition functors 
\begin{equation*}
       \begin{tikzcd}
\tP_{n}\x \tP_{k_1} \x \cdots \x \tP_{k_n} & P_{k},
	\arrow["\mu_f",from=1-1, to=1-2]
\end{tikzcd}\end{equation*}
indexed by the maps $f\colon \un{k} \to \un{n}$ of $\Delta_s$, which are associative and unital in the following sense.

\noindent
{\em (Associativity.)\/} Let $f\colon \un{m}\to\un{k}$ and $g\colon \un{k}\to\un{n}$ be two composable maps. For $i\in \un{n}$ and $j\in \un{k}$ with $g(j)=i$ we identify $g^{-1}(i)=\un{k}_i$, $gf^{-1}(i)=\un{m}_i$, and $(f^i)^{-1}(j)=f^{-1}(j)=\un{m}^i_j$. The~following diagram commutes.
\begin{equation*}\label{equation:associativity}
\begin{tikzcd}
\tP_{n} \x \prod_{i}(\tP_{k_i} \x \prod_{j}\tP_{m_j^i})  \arrow[rr,"\tP_n\x \prod_{i}\mu_{f^i}"] \arrow[d, "\mathrm{shuffle}"'] &&
\tP_{n} \x \prod_{i}\tP_{m_i} \arrow[dd,"\mu_{gf}"] \\
(\tP_n\x \prod_{i}\tP_{k_i} )\x \prod_{i,j}\tP_{m_j^i} \arrow[d,"\mu_g \x \prod_{i,j}\tP_{m_j^i}"'] \\
\tP_k \x \prod_{i,j}\tP_{m_j^i} \arrow[rr,"\mu_f"] &&
\tP_m
\end{tikzcd}
\end{equation*}
\noindent
{\em (Unitality.)\/} The operad is equipped with a unit  
\begin{equation*}
       \begin{tikzcd}
\1& \tP_{1},
	\arrow["\eta",from=1-1, to=1-2]
\end{tikzcd}\end{equation*}
where $\1$ is the terminal category.
For each $n \geq 1$, $\uu_{n}\colon \un{n} \to \un{n}$ is the identity map and $!_n\colon \un{n}\to \un{1}$ is the unique map to~$\un{1}$. The~following diagrams commute.
\begin{center}
\begin{tikzcd}
    \tP_n\x \texttt{1}^{\x n} \arrow[r,"\cong"]
    \arrow[d,"\tP_n\x \eta^{\x n}"'] &
    \tP_n
    \\
    \tP_n \x {\tP_1}^{\x n} \arrow[ru,"\mu_{\uu_n}"'] 
\end{tikzcd}
\begin{tikzcd}
    \texttt{1}\x\tP_n\arrow[r,"\cong"]
    \arrow[d,"\eta\x\tP_n"'] &
    \tP_n
    \\
    \tP_1\x \tP_n \arrow[ru,"\mu_{!_n}"'] 
\end{tikzcd}
\end{center}
\end{definition}
The operads considered in this text are always non-symmetric and constant free, i.e.~there is no $\tP_0$.  

The sequence $a_1,\ldots,a_k$ can be cut into $n$ blocks by the map $f$, which we write as
\begin{equation}\label{equation:sequence}
\{a_i\}_{1\leq i\leq k}=\big\{\{a_j^i\}_{1\leq j \leq k_i}\big\}_{1\leq i\leq n}.
\end{equation}
In terms of elements, the associativity is written as an equation
$$ \mu_f\big(\mu_g(c,b_1,\ldots,b_n), a_1,\ldots,a_k\big) = \mu_{gf}\big(c,\mu_{f^1}(b_1,a^1_1,\ldots,a^1_{k_1}),\ldots, \mu_{f^n}(b_n,a_1^n,\ldots,a^n_{k_n})\big),$$
and the unitality gives two equations
$$ \mu_{\uu_n}(a,e,\ldots,e)=a ,$$
    $$ \mu_{!_n}(e,a)=a.$$ 
\begin{example}
Any strict monoidal category $(\V,\otimes,\1)$ gives an operad with $\tP_1=\V$ and $\tP_{n\geq2}=\emptyset$.
\end{example}
