\begin{definition}[\textbf{Integration}]
For a categorical operad $\tP$, its operadic Grothendieck construction $\int \tP$ is a 2-category defined by the following data.

\begin{itemize}
    \item 0-cells of $\int \tP$ are pairs $[m,a]$, where $m\geq 1$ and $a\in \tP_m$,
    \item 1-cells of $\int \tP$, that is objects of $\int\tP\big([m,a],[k,b]\big)$, are tuples $[f;a_1,\ldots,a_k;\alpha]$, where 
    \begin{itemize}
        \item 
        $f\colon \un{m} \to \un{k}\in\Delta_s$
        \item $a_i\in \tP_{f^{-1}(i)},$ and 
        \item $\alpha\colon \mu_f(b,a_1,\ldots,a_k)\to a \in \tP_m$. 
    \end{itemize}
    \item A 2-cell $\delta$ of $\int \tP$, that is morphisms in $\int\tP\big([m,a],[k,b]\big),$ 

    $$[f;a'_1,\ldots,a'_k;\alpha'] \xRightarrow{\delta} [f;a''_1,\ldots,a''_k;\alpha''],$$ is a sequence of morphisms $\{\delta_i\colon a'_i\to a''_i \in \tP_{f^{-1}(i)}\}_{1\leq i\leq k}$, such that $$\alpha'' \circ \mu_f(\uu;\delta_1,\ldots,\delta_k)=\alpha'.$$
    There are no 2-cells between morphisms which differ in the first component.
\end{itemize}
\end{definition}
 \noindent The horizontal composition of 1-cells is given as follows. Let $$\un{m}\xrightarrow{f} \un{k} \xrightarrow{g} \un{n},$$ 
    $$\alpha\colon \mu_f(b,a_1,\ldots,a_k)\to a,$$
    $$\beta\colon \mu_g(c,b_1,\ldots,b_n)\to b.$$
       The composite $[g; b_1,\ldots b_n;\beta]\circ[f; a_1,\ldots,a_k;\alpha]$ is defined as
       $$    \big[gf; \mu_{f^1}(b_1,a^1_1,\ldots,a^1_{k_1}),\ldots, \mu_{f^n}(b_n,a_1^n,\ldots,a^n_{k_n}); \alpha \circ \mu_{f}(\beta,a_1,\ldots,a_k)\big]. $$
   The source of $\alpha \circ \mu_{f}(\beta,a_1,\ldots,a_k)$ has a correct form thanks to associativity of $\tP$. The~identity maps for horizontal composition come from the operad unit $e\in \tP_1$ (i.e.~the image of $\eta$), $$\uu_{[m,a]}=[\uu_m,e\ldots,e;\uu_a]\colon [m,a]\to[m,a].
$$

It is straightforward, to check that $\int \tP$ is indeed a 2-category. We will use the term \textit{integration} of an operad.
%The higher coherent data comes from the coherent data of the operad. 
\begin{example}\label{example:natural_numbers2}
Consider the poset $(\bN,\geq)$ of natural numbers as a category with $a\to b$ if $a\geq b$. The addition respects the order, so $N=(\bN,\geq,+)$ is a strict monoidal category, and hence a non-symmetric operad concentrated in arity 1. Its integration $\int \bN$ is the 2-category given as follows.
Objects of $\int\bN$ are natural numbers, the maps are $\int\bN(a,b)=\{p\in\bN, b+p \geq a\}$ and 2-cells are $p'\geq p''$. The horizontal composite of $p\colon a \to b$ and $q\colon b \to c$ is $(p+q)\colon a\to c$, since $p+q+c \geq p+b \geq a$. The following is an example of a 2-dimensional diagram in $\int\bN$.
% https://q.uiver.app/#
\[\begin{tikzcd}
	5 && 2 && 0
	\arrow[""{name=0, anchor=center, inner sep=0}, "3"{description}, curve={height=12pt}, from=1-1, to=1-3]
	\arrow[""{name=1, anchor=center, inner sep=0}, "4"{description}, curve={height=-12pt}, from=1-1, to=1-3]
	\arrow[""{name=2, anchor=center, inner sep=0}, "11"{description}, curve={height=-30pt},shift left=2, from=1-1, to=1-5]
	\arrow[""{name=3, anchor=center, inner sep=0}, "5"{description}, curve={height=30pt}, shift right=2, from=1-1, to=1-5]
	\arrow[""{name=4, anchor=center, inner sep=0}, "2"{description}, curve={height=12pt}, from=1-3, to=1-5]
	\arrow[""{name=5, anchor=center, inner sep=0}, "5"{description}, curve={height=-12pt}, from=1-3, to=1-5]
	\arrow["\leq"{marking, allow upside down}, draw=none, from=0, to=1]
	\arrow["\leq"{marking, allow upside down}, draw=none, from=4, to=5]
	\arrow["\leq"{marking, allow upside down}, draw=none, from=1-3, to=2]
	\arrow["{=}"{marking, allow upside down}, draw=none, from=1-3, to=3]
\end{tikzcd}\]
Notice, that for any $a\in \bN$, the poset $\int\bN(a,0)$ has a terminal object, namely the map $a\colon a \to 0$. In fact, for $a\geq b$, $\int\bN(a,b)$ has a terminal object $c=a-b$, and $\int\bN(b,a)=\emptyset$ if $b<a$.
Also, any morphism $p\colon a \to b$ (i.e. $b+p\geq a$) can be factored as 
$$
a \xrightarrow{0} b+p \xrightarrow{p} b.
$$
\end{example}

