Our next goal is to describe additional properties of the 2-category $\int\tP$ and the projection $$\pi\colon \int\tP\to\Delta_s.$$
\begin{definition}
    Let $\C$ be a 2-category and $x$ an object of $\C$. The lax slice 2-category $\C/x$~has the following structure.
    \begin{itemize}[leftmargin=*]
        \item Objects are maps $y\xrightarrow{\phi}x$ of $\C$ with codomain $x$.
        \item For objects $z\xrightarrow{\theta} x$ and $y\xrightarrow{\phi} x$, a map $\theta\to \phi$ of $\C/x$ is a pair $(\psi,\alpha)$, where $ z\xrightarrow{\psi} y$ is a map of $\C$ and $\phi\circ \psi\xRightarrow{\alpha} \theta $ is a 2-cell of $\C$.  The pair $(\phi,\alpha)$ is drawn as:
        % https://q.uiver.app/#q=WzAsMyxbMCwwLCJ4Il0sWzIsMCwieSJdLFsxLDEsInoiXSxbMCwxLCJmIl0sWzAsMiwiaCIsMl0sWzEsMiwiZyJdLFsxLDQsIlxcYWxwaGEiLDEseyJzaG9ydGVuIjp7InNvdXJjZSI6MzAsInRhcmdldCI6MjB9fV1d
\[\begin{tikzcd}
	z && y. \\
	& x
	\arrow[""{name=0, anchor=center, inner sep=0},"\psi", from=1-1, to=1-3]
	\arrow["\theta"', from=1-1, to=2-2]
	\arrow["\phi", from=1-3, to=2-2]
	\arrow["\alpha"{description},draw=none, from=0, to=2-2]
\end{tikzcd}\]

        \item A 2-cell $\gamma$ of $\C/x$,
        \[\begin{tikzcd}
	\theta & \phi
	\arrow[""{name=0, anchor=center, inner sep=0}, "{(\psi',\alpha')}", curve={height=-12pt}, from=1-1, to=1-2]
	\arrow[""{name=1, anchor=center, inner sep=0}, "{(\psi'',\alpha'')}"', curve={height=12pt}, from=1-1, to=1-2]
	\arrow["\gamma", shorten <=3pt, shorten >=3pt, Rightarrow, from=0, to=1]
\end{tikzcd}\]
       is a 2-cell $\psi'\xRightarrow{\gamma} \psi''$ of $\C$, such that $ \alpha''\circ (\uu_\phi \Box \gamma)=\alpha'$. The symbol $\Box$ denotes horizontal composition of 1-cells in $\C$.
    \end{itemize}

\end{definition}
More details can be found for instance in \cite[Definition~7.1]{JY}, but note the opposite orientation of the triangle interior. For any $x \in \C$, a lax functor $F\colon\C \to \D$ induces a lax functor $\C/x \to \D/Fx$. 
For a lax triangle $\alpha\colon \phi\circ \psi \Rightarrow \theta$ we shall use $d_2\alpha=\psi$, $d_1\alpha=\theta$, and $d_0\alpha=\phi$.
\begin{definition}
    An object $v$ in a 2-category $\C$ is lali-terminal, 
    if for every object~$x$ of $\C$, the category $\C(x,v)$ has a terminal object. We require that the terminal object of $\C(v,v)$ is the identity on $v$.
    An object $v$ is local lali-terminal if it is lali-terminal in its connected component.
\end{definition}
The prefix \textit{lali} stands for \textit{left adjoint left inverse}. This terminology appears in {\cite{Step}, however the condition on the terminal object of $\C(v,v)$ being identity is not required there.
\begin{definition}\label{definition:operadic_2_cat}
A non-symmetric operadic 2-category is a 2-category $\bO$ equipped with 
\begin{itemize}
\item a 2-functor $|-|\colon\bO\to \Delta_s$, called cardinality,  
\item 2-functors $\fib_x\colon \bO/x\to\bO^{|x|}$ from the lax slice, for every object $x$ of $\bO$, and 
\item chosen local lali-terminal objects $u_c$, in each connected component $c$ of $\bO$, which contains at least one object of non-zero cardinality. 
\end{itemize}
This data satisfies axioms analogous to those of classical operadic categories \cite{Batanin_Markl:duoidal}, and we state them below.
\end{definition}

 To present the axioms we first introduce necessary notation and terminology. The functors $\fib_x$ are called fiber functors. For $(\phi\colon y\to x) \in \bO/x$, $\fib_x(\phi)$ is a tuple of objects
 $$\fib_x^i(\phi), 1\leq i \leq \card{x},$$
 which we call the \textit{fibers} of $\phi$. We denote them simply by $\phi_i$. For a lax triangle $\alpha\colon (\phi\circ\psi)\Rightarrow  \theta$ in~$\bO$, the \textit{induced maps} between fibers $\fib_x^i(\alpha)\colon \fib_x^i(\theta)\to \fib_x^i(\phi)$ will be denoted by~$\alpha^i\colon \theta_i \to \phi_i$. For~any object $x$ of $\bO$ with $|x|\neq 0$, lying in a connected component $c$, we denote the terminal object of $\bO(x,u_c)$ by $\epsilon_x$. The object $u_c$ will be sometimes denoted by $u_x$.
 %The fact that objects $r_i \in \bO$ are fibers of a morphism $\phi\colon y\to x$ will be expressed by $$r_1,\ldots,r_k\triangleright y \xrightarrow{\phi} x.$$

 The promised, the axioms of Definition~\ref{definition:operadic_2_cat} are the following.
 \begin{enumerate}[label=(\roman*)]
    \item The fiber functors preserve cardinality, that is, the following diagram commutes for any object $x$ of $\bO$.
\[\begin{tikzcd}
	\bO/x & \bO^{\card{x}} \\
 \Delta_s/\card{x} & \Delta_s^{\card{x}}
	\arrow["\card{-}/x", from=1-1, to=2-1]
	\arrow["{\fib_{\card{x}}}"', from=2-1, to=2-2]
	\arrow["\fib_x", from=1-1, to=1-2]
	\arrow["\card{-}^{\card{x}}", from=1-2, to=2-2]
\end{tikzcd}\]
\item For every connected component $c$ of $\bO$, $|u_c|=\un{1}$, and $\fib_{u_c}$ is the domain functor.
\item For any object $x$ of $\bO$, fibers of the identity $\uu_x$ are the chosen local lali-terminal objects and we denote them by $u^1_x,\ldots,u^{k}_x$, where $|x|=\un{k}$.
\item For a map $\phi\colon x\to y$ of $\C$, denote the lax triangle $ \uu_y\circ \phi \xRightarrow{\uu_\phi}\phi$ by $\epsilon_\phi$, then
    $(\epsilon_\phi)^i=\epsilon_{(\phi_i)}.$
    \item\noindent\textsc{The fiber axiom.}
 For any $\phi\colon y \to x$, the following diagram commutes.
