\end{enumerate}

\begin{remark}
The fiber axiom of \cite{Batanin_Markl:duoidal} for operadic 1-categories was reformulated to the compact form (v) above in \cite{lack}. Note that we do not require the existence of local lali-terminal objects in every component, but only in those where the cardinality functor is not constantly zero. This is a mild generalization of the standard definition, which allows us to view ordinary (2-)categories as \textit{nullary} operadic (2-)categories, i.e.~those with constantly zero cardinality. In some form this was done already in \cite{lack} and \cite{blob} and it will be important for comparison of operadic fibrations and classical categorical fibrations, cf.~Proposition~\ref{proposition:classical_fibrations}.
\end{remark}
Since $\Delta_s$ is considered as a 2-category with only identity 2-cells, the cardinality functor sends any 2-cell of $\bO$ to an identity 2-cell.
\begin{example}
    Every non-symmetric operadic 1-category $\bO$ (classical operadic category of \cite{Batanin_Markl:duoidal} where the cardinality factors through $\Delta_s$) is a non-symmetric operadic-2-category, viewing $\bO$ as a 2-category with only identity 2-cells. In particular $\Delta_s$ is an example.
\end{example}
     \begin{definition}
An operadic functor between non-symmetric operadic 2-categories is a 2-functor which respects the fiber 2-functors, preserves cardinality and chosen local lali-terminal objects.
\end{definition}
\begin{definition}
    Let $p\colon \bP \to \bO$ be an operadic functor and let $\phi\colon s\to t$ in $\bP$ with fibers $\phi_1,\ldots,\phi_k$. We say that $\phi$ is operadic $p$-cartesian if for any morphism $\theta\colon r \to t$ with fibers $\theta_1\ldots \theta_k$, morphisms $\alpha_i\colon \theta_i \to \phi_i$ in $\bP$ and a lax triangle $\alpha$ in $\bO$, with $\alpha^i=p\alpha_i$, $d_1\alpha=p\theta$ and $d_0\alpha=p\phi$, there exists a unique lax triangle $\tilde{\alpha}$ in $\bP$ with $\tilde{\alpha}^i=\alpha_i$ and $p\tilde{\alpha}=\alpha$.
\end{definition}
