From now on, we will be interested only in operadic fibrations over $\Delta_s$. Since it is the terminal non-symmetric operadic 2-category, the only functors with target $\Delta_s$ are the cardinality functors. 
\begin{definition}\label{definition:splitting}
    A non-symmetric operadic 2-category $\bP$ is called fibered if its cardinality functor is an operadic fibration.
It is called split-fibered if it is equipped with a choice of lifts $\tilde{f}=\ell(f,b,a_1\cdots a_k)$, for any map $f\colon \un{m}\to \un{k}$ in $\Delta_s$ and objects $b,a_1,\ldots,a_k$ in $\bP$, with $|b|=k$, such that the following conditions hold for any $f\colon \un{m}\to \un{k}$, $g\colon \un{k} \to \un{n}$ and objects $c,b_i,a_j \in\bP$, $0\leq i\leq n, 0\leq j\leq k$.
\begin{itemize}
    \item $\ell(\uu_n,c,e\cdots e)=\uu_c,$
    \item $\ell(!_n,e,c)=\epsilon_c,$ and
    \item let $\overline{a}_j^i$ denote the sequence $a_1^i\cdots a_{k_i}^i$, then 
    \begin{equation*}
    \ell\big(g,\ell_1(f,c,b_1\cdots b_n),a_1\cdots a_k\big)=\ell\big(f\circ g,c,\ell_1(f_1,b_1,\overline{a}_j^1)\cdots \ell_1(f_n,b_n,\overline{a}_j^n)\big),
    \end{equation*}
    where $\ell_1$ denotes the domain of the lift.

\end{itemize}
\end{definition}
\begin{lemma}\label{lemma:triangle_in_Delta}
    The data of maps $g\colon \un{k}\to \un{n}$, $h\colon \un{m}\to \un{n}$, and maps  $f_i\colon h^{-1}(i)\to g^{-1}(i)$, for $0\leq i \leq n,$ determine a unique (strict) triangle $\alpha$ in $\Delta_s$ with $d_0\alpha=g$, $d_1\alpha=h$ and $\alpha^i=f_i$.
\end{lemma}
\pf
The triangle is $\alpha\colon g\circ f=h$ with $f=f_1+\cdots +f_n$, the ordinal sum of finite maps. 
\epf
%Does this mean that $\Delta_s$ satisfies blow-up?
\begin{theorem}\label{theorem:intP_is_split-fibered}
For any non-symmetric categorical operad $\tP$, the 2-category $\int \tP$ is a non-symmetric operadic 2-category which is split-fibered over $\Delta_s$.     
\end{theorem}
Before proving the theorem we describe the lax slice 2-category $(\int\tP)/[n,c]$, for some object $[n,c] \in \int\tP$.
Its objects are maps $[g;b_1,\ldots,b_n;\beta]\colon [k,b]\to[n,c]$. A 1-cell
$$[h; c_1,\ldots,c_n;\gamma]\rightarrow [g; b_1,\ldots,b_n;\beta]$$ is a lax triangle in $\int\tP$, i.e. a 2-cell $$[g; b_1,\ldots b_n;\beta]\circ 
    [f; a_1,\ldots,a_k;\alpha] \xRightarrow{\delta} [h; c_1,\ldots,c_n;\gamma],$$ with $h=g\circ f$, which amounts to a tuple of morphisms

    \begin{equation}\label{equation:deltas}
      \mu_{f^i}(b_i,a^i_1,\ldots,a^i_{k_i})\xrightarrow{\delta_i} c_i, 1\leq i\leq n,  
    \end{equation}
in $\tP_n$ (recalling the notation $a_j^i$ from \eqref{equation:sequence}), such that 
\begin{equation}\label{equation:2-cell_condition}
    \gamma\circ\mu_{h}(c,\delta_1,\ldots,\delta_n)=\alpha \circ \mu_{f}(\beta,a_1,\ldots,a_k).
\end{equation}
A 2-cell $\xi\colon \delta'\to \delta''$ in $\int\tP/[n,c]$ is a tuple of maps
\begin{equation}
    \label{equation:xis}
    \xi_j\colon a'_j\to a''_j, 1\leq j \leq k,
\end{equation}
such that
$$\alpha''\circ\mu_{f}(b,\xi_1,\ldots,\xi_k)=\alpha'$$
and
\begin{equation}
    \label{equation:delta_is}\delta_i''\circ\mu_{f^i}(b_i,\xi^i_1,\ldots,\xi^i_{k_i})=\delta_i', 1\leq i \leq n.
\end{equation}
\pf We begin by describing the operadic structure of $\int\tP$. The cardinality is the projection~$\pi$ on the first component. Let $[n,c]$ be an object of $\int\tP$. 
The fiber 2-functor
$$\fib_{[n,c]}\colon \big(\int\tP\big)/[n,c]\longrightarrow \big(\int\tP\big)^{\x n}$$
is defined as follows.

The fibers of a map $[g;b_1,\ldots,b_m;\beta]$ are the objects $[g^{-1}(i),b_i]$, we write 
$$\fib^i_{[n,c]}\big([g;b_1,\ldots,b_m;\beta]\big)=[g;b_1,\ldots,b_m;\beta]^i=[g^{-1}(i),b_i].$$
For a lax triangle 
$$[g; b_1,\ldots b_n;\beta]\circ 
    [f; a_1,\ldots,a_k;\alpha] \xRightarrow{\delta} [h; c_1,\ldots,c_n;\gamma],$$
    that is $\delta = (\delta_1,\ldots,\delta_n)$ as in \eqref{equation:deltas}, its fibers are maps $[f^i;a_1^i,\ldots,a_{k_i}^i;\delta_i]$ and we write 
\begin{equation}\label{equation:fiber_of_triangle}
    \fib^i_{[n,c]}(\delta)=\delta^i=[f^i;a_1^i,\ldots,a_{k_i}^i;\delta_i],
\end{equation}
which is indeed a map $[h^{-1}(i),c_i]\to[g^{-1}(i),b_i]$.
The fibers of a 2-cell $\xi\colon \delta'\to\delta''$, that is $\xi=(\xi_1, \ldots ,\xi_k)$ as in \eqref{equation:xis}, are 2-cells $$\fib^i_{[n,c]}(\xi)=\xi^i=(\xi^i_1,\ldots,\xi^i_{k_i}).$$
By the equations \eqref{equation:delta_is}, each $\xi^i$ is a 2-cell $\colon \delta_i'\Rightarrow \delta_i''$. It is straightforward to check that the fiber assignment is functorial.
The 2-category $\int\tP$ has only one connected component and the chosen lali-terminal object is the object $[1,e \in \tP_1]$ given by the unit $e$ of $\tP$. Indeed, for any $[n,c]$, there is a map 
\begin{equation}\label{equation:terminal_maps}
    [!_n,c,\uu_c]\colon [n,c] \to [1,e],
\end{equation}
with the unique map $!_n\colon n \to 1$ and $\mu_{!_n}(e,c)=c$. For any other map $[!_n,b,\alpha]\colon [n,c] \to [1,e],$ that is, $\alpha\colon \mu_{!_n}(e,b)=b\to c$, there is a unique 2-cell $\alpha\colon [!_n,b,\alpha]\Rightarrow[!_n,c,\uu_c]$. 
It is clear that the fiber functor preserves cardinality and the cardinality of $[1,e]$ is $\un{1}$. By definition, the fibers of horizontal identities $\uu_{[n,a]}$ are the objects $[1,e]$. This gives axioms (i)-(iii) of non-symmetric operadic 2-category. For the axiom (iv) we compute that for any $$[f; a_1,\ldots,a_k;\alpha]\colon [m,a]\to[k,b]$$ the fibers of the lax triangle $$\uu_{[f; a_1,\ldots,a_k;\alpha]}\colon [\uu_m; e,\ldots ,e;\uu_b]\circ 
    [f; a_1,\ldots,a_k;\alpha] \xRightarrow{} [f; a_1,\ldots,a_k;\alpha]$$
    are the maps $[!_{f^{-1}(i)};a_i,\uu_{a_i}],$ which are the terminal maps \eqref{equation:terminal_maps}. The fiber axiom (v) is monstrous, but straightforward to check. 

    Next we show that the projection is an operadic fibration. For a map $g\colon \un{k}\to \un{n}$ of $\Delta_s$ and objects $[n,c]$ and $[g^{-1}(i),b_i] \in \int\tP$, there is a lift 
    \begin{equation}\label{equation:lifts_in_intP}
        \ell\big(g,[n,c],[g^{-1}(1),b_1]\cdots[g^{-1}(n),b_n]\big):=[g;b_1,\ldots,b_n;\uu_{\mu_g(c;b_1\ldots,b_n)}],
    \end{equation}
    with source $[k,\mu_g(c,b_1\ldots,b_n)].$
   We prove it is operadic cartesian. Assume any map $$[h;c_1,\ldots,c_n;\gamma] \colon [m,a]\to[n,c],$$ and maps $$[f_i;a^i_{1}\ldots,a^i_{k_i};\alpha_i]\colon[(h)^{-1}(i);c_i]\to[g^{-1}(i);b_i], 0\leq i \leq n.$$ 
   By Lemma~\ref{lemma:triangle_in_Delta} the data of $h,g$ and $f_i$ determine a commutative triangle $\alpha\colon g\circ f=h$ in $\Delta_s$ with $\alpha^i=f_i=f^i$.
   This has a lift $\tilde{\alpha}=(\alpha_1,\ldots,\alpha_n)$ with $d_2\tilde{\alpha}=[f;a_1,\ldots,a_k;\gamma\circ\mu_{gf}(c,\alpha_i,\ldots,\alpha_n)]$ which is forced to be unique.
   Indeed, assume any filling lax triangle $\delta=(\delta_1,\ldots,\delta_n)$ with $d_2\delta=[\phi;\chi_1,\ldots,\chi_k;\omega]$, i.e.
   % https://q.uiver.app/#
\[\begin{tikzcd}
	{[g^{-1}(i),b_i]} & {[k,\mu_g(c,b_1,\ldots,b_n)]} &&&& {[n,c]}. \\
	{[h^{-1}(i),c_i]} & {[m,a]}
	\arrow["{\triangleright_i}"{marking, allow upside down}, draw=none, from=1-1, to=1-2]
	\arrow["{[g;b_1,\ldots,b_n;\uu{\mu_g(c,b_1,\ldots,b_n)}]}", from=1-2, to=1-6]
	\arrow["{[f_i;a^i_1,\ldots,a^i_{k_i};\alpha_i]}", from=2-1, to=1-1]
	\arrow["{\triangleright_i}"{marking, allow upside down, pos=0.23}, draw=none, from=2-1, to=2-2]
	\arrow["{[\phi;\chi_1,\ldots,\chi_k;\omega]}", from=2-2, to=1-2]
	\arrow[""{name=0, anchor=center, inner sep=0}, "{[h;c_1,\ldots,c_n;\gamma]}"', curve={height=12pt}, from=2-2, to=1-6]
	\arrow["\delta", shorten <=11pt, shorten >=11pt, Rightarrow, from=1-2, to=0]
\end{tikzcd}\]
   Since $\delta$ lifts the strict triangle  $g\circ f=h$, it must hold $\phi=f$.
   The fibers of $\delta$ have to match the prescribed fibers, hence $\chi_j=a_j$ and $\delta_i=\alpha_i$ by \eqref{equation:fiber_of_triangle}.
   Finally, the equation~\eqref{equation:2-cell_condition} with $\beta\equiv\uu_{\mu_g(c;b_1\ldots,b_n)}$ and $\alpha\equiv\omega$ gives $$\omega = \gamma\circ\mu_{gf}(c,\alpha_i,\ldots,\alpha_n) .$$

      The splitting conditions follow from associativity and unitality of the operad $\tP$. Compare the equations under Definition~\ref{definition:ns-operad} with the splitting conditions of Definition~\ref{definition:splitting}, provided~\eqref{equation:lifts_in_intP}.
\epf

Next we investigate the inverse to the integral $\int$. Let us introduce the following concept.

\begin{definition}
    Let $x,y$ be objects of a non-symmetric operadic 2-category with $|x|=|y|$. A morphism $\phi\colon y \to x$ is trivial if for any $\psi\colon z\to y$ and $1\leq i \leq |y|$,
    \begin{equation}\label{equation:trivial_map}
        \fib^i_x(\uu_{\phi\circ\psi})=\epsilon_{\fib^i_y(\psi)},
    \end{equation}
    where  $\uu_{\phi\circ\psi}$ is the triangle 
    \[\begin{tikzcd}
	z && y. \\
	& x
	\arrow[""{name=0, anchor=center, inner sep=0},"\psi", from=1-1, to=1-3]
	\arrow["\phi\circ\psi"', from=1-1, to=2-2]
	\arrow["\phi", from=1-3, to=2-2]
	\arrow["\uu_{\phi\circ\psi}"{description},draw=none, from=0, to=2-2]
\end{tikzcd}\]

\end{definition}
The condition $|x|=|y|$ implies $|\phi|=\uu_{|x|}$ and it follows from \eqref{equation:trivial_map} that the fibers of a trivial morphism $\phi\colon x\to y$ are the chosen local lali-terminal objects. For classical operadic categories, trivial morphisms of the above definition recover quasibijections. 
\begin{lemma}\label{lemma:fibers_match}
For a trivial morphism $\phi\colon y \to x$ and any $\psi\colon z\to y$, 
the fibers of $\phi\circ\psi$ are the same as fibers of $\psi$, i.e.~$\fib_x^i(\phi\circ\psi)=\fib^i_y(\psi)$, for $0\leq i \leq |y|$. 
\end{lemma}
\pf Since $\fib_x^i(\phi)$ is the codomain of $\fib_x^i(\uu_{\phi\circ\psi})=\epsilon_{\fib_y^i(\psi)}$, it is a chosen local lali-terminal object $u$. 
By axiom (ii), $\fib_u^1(\epsilon_{x})=x$ for any $x$, and by the fiber axiom (v), $$\fib_u^1(\fib_x^i(\uu_{\phi\circ\psi}))=\fib_y^i(\psi).$$ 
Thus 
$$
\fib_x^i(\phi\circ\psi)=\fib_u^1(\epsilon_{\fib_x^i(\phi\circ\psi)})=\fib_u^1(\fib_x^i(\uu_{\phi\circ\psi}))=\fib^i_y(\psi).
$$
\epf
\begin{lemma}    \label{lemma:category_of_trivial}
    Trivial morphisms form a subcategory.
\end{lemma}
\pf
By axiom (iv) of operadic 2-category, all identities are trivial. Let $\phi'\colon y\to x$ and $\phi''\colon x\to w$ be composable trivial morphisms, and $\phi\colon z\to y$ any morphism. Since $\fib_x^i(\phi'\circ\psi)=\fib^i_y(\psi)$ by Lemma~\ref{lemma:fibers_match}, we have $$\fib^i_w(\uu_{(\phi''\circ\phi')\circ\psi})=\fib^i_w(\uu_{\phi''\circ(\phi'\circ\psi)})=\epsilon_{\fib^i_x(\phi'\circ\psi)}=\epsilon_{\fib^i_y(\psi)},$$
hence $\phi''\circ \phi'$ is trivial.
\epf
\begin{theorem}\label{theorem:correspondence}
  There is a 1-1 correspondence between split-fibered operadic 2-categories and categorical non-symmetric operads.
\end{theorem}
\pf Let $\bP$ be split-fibered. Define a non-symmetric categorical operad $\tP$, where each $\tP_n$ is a subcategory of trivial morphisms (cf.~Lemma~\ref{lemma:category_of_trivial}) of $\bP$ above $n$.
The operad multiplication is defined using the operadic lifts as follows. Let $g\colon \un{k}\to\un{n}$, $c\in \tP_n$, and $b_i\in\tP_{g^{-1}(i)}$, for $1\leq i \leq n$. 
Then $$\mu_g(c,b_1,\ldots,b_n):=\ell_1(g,c,b_1\cdots b_n),$$ the domain of the lift $\ell(g,c,b_1\cdots b_n).$ 
Further, let $\phi\colon c'\to c'' \in \tP_n$ and $\psi_i\colon b'_i\to b''_i\in\tP_{g^{-1}(i)}$. 
Since~$\phi$ is trivial, the composite $$\phi\circ\ell(g,c',b'_1\cdots b''_n)\colon\mu_g(c',b'_1,\ldots,b'_n)\to c''$$ has also fibers $b'_i$, by Lemma~\ref{lemma:fibers_match}. 
With the prescribed maps $\psi_i$, the operadic cartesian property of the lift $\ell(g,c'',b''_1\cdots b''_n)$ produces a unique lax triangle 

\[\begin{tikzcd}
	\ell_1(g,c',b'_1\cdots b'_n) && \ell_1(g,c'',b''_1\cdots b''_n) \\
	& b''
	\arrow[""{name=0, anchor=center, inner sep=0},"d_2\tilde{\alpha}", from=1-1, to=1-3]
	\arrow["{\phi\circ\ell(g,c',b'_1\cdots b'_n)}"', from=1-1, to=2-2]
	\arrow["{\ell(g,c'',b''_1\cdots b''_n)}", from=1-3, to=2-2]
	\arrow["\tilde{\alpha}"{description},draw=none, from=0, to=2-2]
\end{tikzcd}\]
with $\tilde{\alpha}^i=\psi_i$,
which lifts the (strict) triangle $\uu_{\un{n}}\circ g = g$ in $\Delta_s$.
We define
$$
\mu_g(\phi,\psi_1\ldots,\psi_n):=d_2\tilde{\alpha}.
$$
Since the triangle
$$\uu_{\ell(g,c,b_1\cdots,b_n)}\colon\ell(g,c,b_1\cdots,b_n)\circ\uu_{\ell(g,c,b_1\cdots,b_n)}\Rightarrow \ell(g,c,b_1\cdots,b_n)$$ 
lifts the triangle $\uu_g\colon g\circ \uu_k = g$ with given endpoints $\uu_c,\uu_{b_1},\ldots,\uu_{b_n}$, and there is unique such, it holds $$\mu_g(\uu_c,\uu_{b_1},\ldots,\uu_{b_n})=\uu_{\ell(g,c,b_1\cdots,b_n)}.$$ By a similar argument, it holds 
$$\mu_g(\phi'',\psi''_1,\ldots,\psi''_n)\circ \mu_g(\phi',\psi'_1,\ldots,\psi'_n)=\mu_g(\phi''\circ\phi',\psi''_1\circ\psi'_1,\ldots,\psi''_n\circ\psi'_n),$$
hence $\mu_g$ is indeed a functor. The splitting conditions of Definition~\ref{definition:splitting} ensure associativity and unitality of the operad $\tP$. It is a straightforward computation to show that this construction is inverse to $\int$, as desired.
\epf
In this last part we focus on relating operadic fibrations to classical categorical fibrations. We first introduce the notion of operad for arbitrary operadic 2-category.

\begin{definition} Let $\bO$ be a non-symmetric operadic 2-category. A categorical $\bO$-operad $\tP$ is a collection of categories $\tP_x$, indexed by objects $x \in \bO$, equipped with functors $$\tP_y \x \tP_{\fib_x^1(\phi)}\x \cdots \x \tP_{\fib_x^{\card{x}}(\phi)} \xrightarrow{\mu_\phi} \tP_x,$$
for every map $\phi\colon x \to y$ in $\bO$
%(the following is redundant, P_\rho and commutativity can be obtained from P_{\phi\rho}, associativity and units), and functors $P_\rho\colon P_{\phi(f)}\to P_{\phi(q)}$ for every 2-cell $\rho\colon f\to g$ of $C$, such that the triangle
%\[\begin{tikzcd}
	%P_y \x P_{\phi(f)}& P_x\\
	%P_y \x P_{\phi(g)}& 
	%\arrow["{P_f}", from=1-1, to=1-2]
	%\arrow["{P_g}"', from=2-1, to=1-2]
	%\arrow["{P_y\x P_\rho}"', from=1-1, to=2-1]
	%\end{tikzcd}\]
 which satisfy the following associativity and unit laws.
\begin{itemize}
    \item For any lax triangle $\alpha$ in $\bO$,
    \[\begin{tikzcd}
	x && y,\\
	& z
	\arrow[""{name=0, anchor=center, inner sep=0},"{f}", from=1-1, to=1-3]
	\arrow["{h}"', from=1-1, to=2-2]
	\arrow["{g}", from=1-3, to=2-2]
	\arrow["\alpha"{description},draw=none, from=2-2, to=0]
	\end{tikzcd}\]
     with $|y|=l$ and $|z|=k$, and objects $a\in \tP_z, b_i\in \tP_{g_i}, 1\leq i \leq k, c_j \in \tP_{f_i}, 1\leq j\leq l,$
    $$ \mu_f\big(\mu_g(a,b_1,\ldots,b_k), c_1,\ldots,c_l\big) = \mu_h\big(a,\mu_{\alpha_1}(b_1,)(c^1_1,\ldots,c^1_{l_1}),\ldots, \mu_{\alpha_k}(b_k,c_1^k,\ldots,c^k_{l_k})\big),$$
    recalling the notation $c_j^i$ of \eqref{equation:sequence}. 
    It follows from the axioms of operadic 2-categories that for $j\in |y|$, $f_j=(\alpha_i)_{\epsilon j}$, where $i=|g|(j)$, and $\epsilon j \in |g_i|$ is the element corresponding to $j\in |y|$. Hence the associativity equation above is well defined.
    \item For any object $x\in \bO$ of non-zero cardinality, there are units $e_x \in \tP_{u_x}$ and $e^x_i \in \tP_{u^x_i}$, such that for any $a\in \tP_x$,
    $$ \mu_{\uu_x}(a,e^x_1,\ldots,e^x_k)=a ,$$
    $$ \mu_{\eta_x}(e_x,a)=a.$$
\end{itemize}
\end{definition}
Of course, $\bO$-operads can take values in any symmetric monoidal category~$\V$. 
\begin{example}
    Recall the non-symmetric operadic 2-category $\int\bN$ of Example~\ref{example:natural_numbers2}. For simplicity, we describe $\int\bN$-operads with values in $\Set$. 
    A set-valued $\int\bN$-operad is a collection of sets $\tP_n$, $n\geq 0$, together with maps 
    $$
\tP_m \x \tP_p \to \tP_n,
    $$ whenever $m+p\geq n$, subject to associativity and unitality conditions. In effect, the composition maps are generated by maps
    $$\tP_m \x \tP_p \to \tP_{m+p}$$
    for an $m,p\in\bN$ and maps $$\tP_m \to \tP_{m+1}.$$ This strongly resembles differential graded algebras. One could possibly obtain them by considering an enrichment.
\end{example}
The comparison to classical categorical fibrations and Grothendieck construction is provided by the following
\begin{proposition}\label{proposition:classical_fibrations}
Any 1-category $\C$ (viewed as a 2-category with only identity 2-cells) is a non-symmetric operadic 2-category with constantly zero cardinality functor. A categorical $\C$-operad $\tP$ is then an ordinary functor $\tP\colon \C^{\mathrm{op}} \to \Cat$. The integration recovers the classical Grothendieck construction on a categorical presheaf and operadic fibrations over $\C$ recover categorical fibration over $\C$.\qed
\end{proposition}
For completeness, we close this article by stating the splitting conditions for a general operadic fibration and a general conjectural correspondence.
\begin{definition}
An operadic fibration $p\colon \bP \to \bO$ is split if it is equipped with a choice of operadic $p$-cartesian lifts $\Tilde{g}=\ell(b,a_1\cdots a_k,g)$ for any map $g$ of $\bO$ and endpoints $b,a_1,\ldots, a_k \in \bP$, satisfying the following conditions. Denote the domain of $\ell(b,a_1\cdots a_k,g)$ by $\ell_1(b,a_1\cdots a_k,g)$.
   \begin{itemize}
       \item For every object $x \in \bP$, $\ell(u_x,x,u_{px}) = u_x$ and $\ell(x,u^x_1\cdots u^x_k,\uu_{px}) = \uu_x$. 
       \item For any lax triangle $\alpha$ in $\bO$,
    \[\begin{tikzcd}
	x && py,\\
	& pz
	\arrow[""{name=0, anchor=center, inner sep=0},"{f}", from=1-1, to=1-3]
	\arrow["{h}"', from=1-1, to=2-2]
	\arrow["{g}", from=1-3, to=2-2]
	\arrow["\alpha"{description},draw=none, from=2-2, to=0]
	\end{tikzcd}\]
     with $|y|=l$ and $|z|=k$, and objects $a, b_i, c_j \in \bP, 1\leq i \leq k, 1\leq j\leq l,$
    $$ \ell\big(\ell_1(z,b_1\cdots b_k,g),c_1 \cdots c_l,f\big) = \ell\big(z,\ell_1(b_1,c_1^1\cdots c^1_{l_1},\alpha_1)\cdots\ell_1(b_k,c_k^1\cdots c^k_{l_k},\alpha_k),h\big),$$
    where $\{c_j^i\}$ are the blocks of the sequence $\{c_j\}$ determined by the map $f$.
   \end{itemize}
\end{definition}
\begin{conjecture}
    There is a 1-1 correspondence of split operadic fibrations over $\bO$ and categorical $\bO$-operads.
\end{conjecture}
