\section*{Introduction}

\begin{Emp'}
{\bf The finite-dimensional case.} (a) Let $G$ be a connected reductive group over an algebraically closed field $k$, and let $T\subseteq B$ and $W$ be a maximal torus, a Borel subgroup and the Weyl group of $G$, respectively. Consider the diagram
\[
[G/G]\overset{\ov{\frak{p}}^{\on{fin}}}{\lla} [B/B]\overset{\pr}{\lra} T,
\]
where $[G/G]$ and $[B/B]$ denote quotient stacks corresponding to the adjoint actions, morphism $\ov{\frak{p}}^{\on{fin}}$ (called the {\em Grothendieck--Springer resolution}) is induced by the inclusion $B\hra G$, and morphism $\pr$ is induced by the projection $B\to B/R_u(B)\simeq T$.

\smallskip

(b) To every local system $\cL$ on $T$, we associate the {\em Grothendieck--Springer sheaf}
\[
\C{S}_{\cL}^{\on{fin}}:=(\ov{\frak{p}}^{\on{fin}})_!\pr^*(\cL)[\dim G]\in\C{D}([G/G]).
\]
Since $[B/B]$ is a smooth stack, while $\ov{\frak{p}}^{\on{fin}}$ is a small morphism, the sheaf  $\C{S}_{\cL}^{\on{fin}}$ is perverse and is the intermediate extension of its restriction to the regular semisimple locus $[G^{\rs}/G]$.

\smallskip

(c) Moreover, if $\cL$ is $W$-equivariant, then $\C{S}_{\cL}^{\on{fin}}$ is equipped with a $W$-action. In this case, for every representation $\tau\in\on{Rep}_{\qlbar}(W)$ one can form its $\tau$-isotypical component
\[
\C{S}_{\cL,\tau}^{\on{fin}}:=\tau\otimes_{\qlbar[W]} \C{S}_{\cL}^{\on{fin}}\in\C{D}([G/G]),
\]
which is again a perverse sheaf, and is the intermediate extension of its restriction to $[G^{\rs}/G]$. Furthermore, $\C{S}_{\cL,\tau}^{\on{fin}}$ is irreducible, if $\cL$ and $\tau$ are irreducible. 
\end{Emp'}

The goal of this work is to prove analogs of these results for loop groups, using constructions and results from \cite{BKV}.

\begin{Emp'}
{\bf The affine case.} (a) Let $\clp (G)$ and $\cL G$ be the arc group and the loop  group of $G$, respectively,
let $\ev:\clp(G)\rightarrow G$ be the projection (see Section~\re{looparc}), and let $I:=\ev^{-1}(B)\subseteq \clp(G)$ be the Iwahori subgroup scheme.
 %Namely, $\clp (G)$ is a group scheme over $k$, whose group of $k$-points is $G(k[[t]])$, and $\cL G$ is a group ind-scheme, whose group of $k$-points is $G(k((t)))$. We denote by $\ev:\clp(G)\rightarrow G$ the projection, corresponding to the morphism $G(k[[t]])\to G(k):t\mapsto 0$,
%and let $I:=\ev^{-1}(B)\subseteq \clp(G)$ be the Iwahori subgroup scheme (see Sections~\re{looparc}).

\smallskip

(b) Let $\fC\subseteq \cL\kg$ be the locus of ``bounded elements''. More precisely, we define $\fC\subseteq \cL\kg$ to be the preimage $\fC:=(\cL\chi)^{-1}(\clp(\fc))$, where $\fc:=\Spec k[G]^G$ is the Chevalley space of $\kg$, $\cL\chi:\cL G\to\cL\fc$ is the morphism between 
loop  spaces induced by the projection $\chi:G\to\fc$, and $\clp(\fc)\subseteq\cL\fc$ is the arc space of $\fc$.  Consider the diagram
\[
[\fC/\cL G]\overset{\ov{\frak{p}}}{\lla} [I/I]\overset{\pr}{\lra} T,
\]
where $[\fC/\cL G]$ and $[I/I]$ denote quotient stacks corresponding to the adjoint actions, morphism $\ov{\frak{p}}$ (called the {\em affine Grothendieck--Springer resolution}) is induced by the inclusion $I\hra \fC\subseteq \cL G$, and morphism $\pr:[I/I]\to T$ is induced by the projection $I\overset{\ev}{\lra} B\overset{\pr}{\to} T$.

\smallskip

(c) Let $\ell$ be a prime number different from the characteristic of $k$. Every $\infty$-stack $\cX$ over $k$ gives rise to a stable $\infty$-category $\C{D}(\C{X})$ of $\ell$-adic sheaves on $\C{X}$, and every morphism $f:\cX\to\cY$ of $\infty$-stacks gives rise to a pullback functor $f^!:\cD(\cY)\to \cD(\cX)$ (see Section~\re{sheaves}). In particular, to every $\infty$-stack $\cX$ one can associate a dualizing sheaf $\om_{\cX}\in\cD(\cX)$, defined to be the $!$-pullback of $\qlbar\in\cD(\pt)$.

\smallskip

(d) As in the Lie algebra case, the projection $\ov{\frak{p}}$ is ind-fp-proper, where ``fp'' stands for {\em finitely-presented} (see Section~\re{fibr}(b)), therefore the pullback $\ov{\frak{p}}^!:\cD([\fC/\cL G])\to \cD([I/I])$ has a left adjoint $\ov{\frak{p}}_!$ (see \cite[Proposition~5.3.7]{BKV}). For every local system $\cL$ on $T$, we set
\[
\C{S}_{\cL}:=\ov{\frak{p}}_!\pr^!(\om_T\otimes\cL)\in \cD([\fC/\cL G]),
\]
and call it the {\em affine Grothendieck--Springer sheaf}.

\smallskip

(e) We denote by $\fC_{\bullet}\subseteq\fC$ the open ind-subscheme such that $\fC_{\bullet}(k)=\fC(k)\cap G^{\rs}(k((t)))$, set $I_{\bullet}:=I\cap \fC_{\bullet}$, and let $\ov{\frak{p}}_{\bullet}:[I_{\bullet}/I]\to[\fC_{\bullet}/\cL G]$ and $\C{S}_{\cL,\bullet}\in \cD([\fC_{\bullet}/\cL G])$ be the restrictions of $\ov{\frak{p}}$ and let $\C{S}_{\cL}$, respectively.
\end{Emp'}


\begin{Emp'} \label{E:mainresults}
{\bf Main results.} (a) Assume that the derived group $G^{\der}$ of $G$ is simply connected and that the order of $W$ is prime to the characteristic of $k$. In this case, we show that the stable $\infty$-category $\cD([\fC_{\bullet}/\cL G])$ is equipped with
a natural perverse $t$-structure.

\smallskip

(b) Assume further that the characteristic of $k$ is either zero  or greater than $2h$, where $h$ is the Coxeter number of $G$.\footnote{In \cite{BKV} we forgot to impose this condition (see footnote after the formulation of Theorem~\ref{flat1} below).} In this case we show that for every local system $\cL$ on $T$, the sheaf $\C{S}_{\cL,\bullet}$ is perverse, and is the intermediate extension of its restriction to the locus
$[\fC_{\leq 0}/\cL G]$ of bounded elements with regular semisimple reduction. Moreover, we show that  if the local system $\C{L}$ is $W$-equivariant, then $\C{S}_{\cL,\bullet}$ is equipped with a natural action of the extended affine Weyl group $\wt{W}$ of $G$.
In this case, for every representation $\tau\in\on{Rep}_{\qlbar}(\wt{W})$, one can form the $\tau$-isotypical component
\[
\C{S}_{\cL,\bullet,\tau}:=\tau\otimes^L_{\qlbar[\wt{W}]} \C{S}_{\cL,\bullet}\in\C{D}([\fC_{\bullet}/\cL G]).
\]

\smallskip

(c) Furthermore, we show that $\C{S}_{\cL,\bullet}$ is {\em $\wt{W}$-constructible}, that is, the quotient stack $[\fC_{\bullet}/\cL G]$ has a {\em constructible stratification} such that $!$-restriction of  $\C{S}_{\cL,\bullet}$ to each stratum is a local system, whose fibers are perfect complexes of $\qlbar[\wt{W}]$-modules. Therefore, for every finite-dimensional  representation $\tau\in\on{Rep}_{\qlbar}(\wt{W})$, the $\tau$-isotypical component $\C{S}_{\cL,\bullet,\tau}$ is constructible.

\smallskip

(d) Finally, the main result of this work asserts that for every representation $\tau\in\on{Rep}_{\qlbar}(\wt{W})$, the $\tau$-isotypical component $\C{S}_{\cL,\bullet,\tau}$ is perverse.

\end{Emp'}

\begin{Emp'}
{\bf Remarks.} (a) Note that while the Lie algebra analogs of parts (a)-(c) were known before, the Lie algebra analog of part~(d) is new. 

\smallskip

(b) Unlike $\C{S}_{\cL,\bullet}$, perverse sheaf $\C{S}_{\cL,\bullet,\tau}$ is not always the intermediate extension of its restriction to
$[\fC_{\leq 0}/\cL G]$. Moreover, $\C{S}_{\cL,\bullet,\tau}$ is not always irreducible, when $\C{L}$ and $\tau$ are irreducible.
\end{Emp'}

\begin{Emp'}
{\bf Affine character sheaves.} (a) Perverse sheaves $\C{S}_{\cL,\tau}^{\on{fin}}$ provide examples of Lusztig's character sheaves, which play an important role in the representation theory of finite groups of Lie type.

\smallskip

(b) Likewise we expect that perverse sheaves $\C{S}_{\cL,\bullet,\tau}$ provide examples of {\em affine character sheaves}, whose general definition is currently unknown, but which are expected to play a similarly important role in the representation theory of $p$-adic groups.
\end{Emp'}




\begin{Emp'}
{\bf Outline of proofs.} (a) Since $G^{\der}$ is assumed to be simply connected, the Chevalley space $\fc$ is smooth. Then, mimicking the Lie algebra case, considered in \cite{BKV}, we show that the stack $[\fC_{\bullet}/\cL G]$ is {\em placidly stratified}, that is, has a constructible stratification $\{[\fC_{w,\br}/\cL G]_{\red}\}_{w,\br}$ such that each stratum is a {\em placid stack}. Therefore each  $\cD([\fC_{w,\br}/\cL G]_{\red})$ is equipped with a canonical ($!$-adapted) perverse $t$-structure, and the perverse structure of $\cD([\fC_{\bullet}/\cL G])$ is constructed by gluing.

\smallskip

(b) As in the Lie algebra case, to prove the assertion of Section~\re{mainresults}(b),
we show that the affine Grothendieck--Springer fibration  $\ov{\frak{p}}_{\bullet}:[I_{\bullet}/I]\to[\fC_{\bullet}/\cL G]$ is small.
Moreover, we deduce the smallness from codimension formula for Goresky--Kottwitz--MacPherson strata, dimension formula for affine Springer fibers
$\Fl_{\g}$ and flatness of projection $v_n:I_n\to \cL_n(\fc)$ between truncated arc spaces. Finally, we deduce the flatness of $v_n$ from the corresponding result for Lie algebras using Jordan decomposition and identifying the unipotent locus of the group with the nilpotent locus of
the Lie algebra. 

\smallskip

(c) To show the assertion of Section~\re{mainresults}(c), we prove the finiteness properties of the Grothendieck--Springer fibration $\ov{\frak{p}}_{\bullet}$, mimicking the Lie algebra case.

\smallskip

(d) Since $\C{S}_{\cL,\bullet}$ is perverse and the functor of $\tau$-coinvariants is right $t$-exact, to show the perversity of $\C{S}_{\cL,\bullet,\tau}$ it suffices to show that $\C{S}_{\cL,\bullet,\tau}\in {}^p\cD^{\geq 0}([\fC_{\bullet}/\cL G])$. Moreover, using Section~\re{mainresults}(c), we show that it suffices to prove that for every $\g\in\fC_{\bullet}(k)$, we have an inclusion
%
\begin{equation} \label{Eq:intr}
R\Gm_c(\Fl_{\g},\om_{\cL})_{\tau}\in D^{\geq -d_{\g}},
\end{equation}
%
where $\Fl_{\g}$ denotes the affine Springer fiber,  $R\Gm_c(\Fl_{\g},\om_{\cL})_{\tau}$ denotes the $\tau$-coinvariants of the cohomology with compact support of the pullback of $\om_T\otimes\cL$, and $d_{\g}$ is an explicit integer.

Finally, we deduce the inclusion \form{intr} from the group analog \cite[Theorem~2.3.4]{BV} of a theorem of Yun \cite{Yun} on the compatibility of actions.
\end{Emp'}

\begin{Emp'}
{\bf Remark.} Though we knew for a long time that the perversity of $\C{S}_{\cL,\bullet,\tau}$ follows from inclusion \form{intr} and that inclusion \form{intr} should follow from the theorem of Yun, we were able to complete the proof of inclusion \form{intr}
only recently. The missing step was Proposition~\ref{coh3}, and it was motivated by a nice trick explained to us by Zhiwei Yun.
\end{Emp'}

\begin{Emp'}
{\bf Relation to local Langlands conjectures and stability.} 
The local Langlands conjecture predicts that the set of isomorphism classes of smooth irreducible representations of $G(\fq((t)))$ has a natural partition into finite subsets $\Pi_{\la}$, called $L$-packets.

Moreover, it is expected that the linear span $\on{Span}\{\chi_{\pi}\}_{\pi\in\Pi_{\la}}$ of characters of $\pi\in\Pi_{\la}$ has another basis $\{\chi_{\la}^{\kappa}\}_{\kappa}$ such that each $\chi_{\la}^{\kappa}$ is ``$\C{E}_{\la,\kappa}$-stable''. Furthermore, it is expected that each $\chi_{\la}^{\kappa}$ is obtained from a perverse sheaf on $[\cL G/\cL G]$ by the ``sheaf-function correspondence''.

Using results of \cite{BV}, the perversity of $\cS_{\cL,\bullet,\tau}$ implies a version of the above conjecture for $L$-packets
of cuspidal Deligne--Lusztig representations, introduced in \cite{KV}.
\end{Emp'}

\begin{Emp'}
{\bf Plan of the paper.} The paper is organized as follows:

\smallskip

In the Section~1 we carry out geometric preliminaries:
First, in Section 1.1, we recall various notions from~\cite{BKV}, including placid $\infty$-stacks, placidly stratified $\infty$-stacks
and small morphisms. Next, in Section 1.2, we introduce $\Gm$-constructible and essentially constructible sheaves on $\infty$-stacks
and study their properties. We also introduce a subclass of placid $\infty$-stacks, which we call {\em admissible}.
Then, in Section 1.3, we recall a construction of perverse $t$-structures on placidly stratified $\infty$-stacks, introduced and studied
in \cite{BKV}, and give several criteria we need later. Finally, in Section 1.4, we show several simple properties of quasi-coherent sheaves, which play a central role in the proof of our main theorem.

\smallskip

In Section~2, we prove group analogs of some of the results of \cite{BKV}: First, in Section 2.1, we show flatness of the Chevalley map for
truncated arc spaces, deducing it from its analog for Lie algebras. Next, in Section 2.2, we introduce a GKM-stratification and
give a proof of a formula for the codimension of strata, which is much shorter than the original one. Finally, in Section~2.3, we study basic properties of the affine Grothendieck--Springer fibration, essentially mimicking the corresponding assertions for Lie algebras.

\smallskip

In Section~3, we introduce affine Grothendieck--Springer sheaves $\cS_{\cL,\bullet}$ and study their properties.
First, in Section 3.1, we show that each $\cS_{\cL,\bullet}$ is perverse, equipped with a natural $\wt{W}$-action and
that the induced action on homologies of affine Springer fibers coincides with the action constructed by Lusztig. Finally, in Section 3.2,
we show the main result of this work asserting that sheaves of $\tau$-coinvariants $\cS_{\cL,\bullet,\tau}$  are perverse.
For completeness, we also show the corresponding assertion for Lie algebras, whose proof is almost identical.

\end{Emp'}



