\section{Geometric preliminaries.}

\subsection{Placid stacks and small morphisms}

In this section we recall certain construction from~\cite{BKV}.
%To make the exposition simpler, most of our notions are more restrictive than those considered in~\cite{BKV}.

\begin{Emp}
{\bf Infinity-stacks.} Let $k$ be an algebraically closed field.

\smallskip

(a) Let $\Sch_k,\Aff_k$ and $\Alg_k$ be the categories of schemes, affine schemes and algebraic spaces over $k$, respectively, let $\Schft_k,\Affft_k$ and $\Algft_k$ be the subcategories of schemes, affine schemes and algebraic spaces of finite type over $k$, and let $\frak{S}$ be the $\infty$-category of spaces, which are often referred as $\infty$-groupoids.

\smallskip

(b) We denote by $\Prest_k$ the $\infty$-category of $\frak{S}$-valued presheaves on $\Aff_k$, that is,
of functors of $\infty$-categories $\Aff_k^{\op}\to\frak{S}$, usually called {\em $\infty$-prestacks} over $k$.
We denote by $\St_k\subseteq \Prest_k$ the full $\infty$-subcategory of sheaves in the
\'etale topology $\Aff_k^{\op}\to\frak{S}$, called {\em $\infty$-stacks}.

\smallskip

(c) We call a morphism $\cX\to\cY$ of $\infty$-stacks a {\em covering}, if it is a surjective map of sheaves. Explicitly, this means that for every
morphism $Y\to\C{Y}$ with $Y\in\Aff_k$ there exists an \'etale covering  $X\to Y$ of (affine) schemes such that the composition $X\to Y\to\C{Y}$ has a lift
$X\to\C{X}$.

\smallskip

(d) Generalizing classical construction for (affine) schemes, to every $\infty$-stack $\C{X}$ one can associate its reduction $\C{X}_{\red}$
(see~\cite[Section~1.4]{BKV}). %We say $\C{X}$ is {\em reduced}, if the canonical morphism $\C{X}_{\red}\to\C{X}$ is an isomorphism.
As in \cite[Section~1.5.1]{BKV}, we say that a morphism between $\infty$-stacks $f:\C{X}\to\C{Y}$ is a {\em topological equivalence}, if the induced morphism $\C{X}_{\red}\to\C{Y}_{\red}$ between reductions is an isomorphism.\footnote{It is more natural to require that the induced map $\C{X}_{\perf}\to\C{Y}_{\perf}$ is an isomorphism, but this more general notion is not needed for our purposes.}

\smallskip

(e) As in \cite[Section~2.4.1]{BKV}, for every $\infty$-stack $\C{X}$ and an $\infty$-substack $\C{Y}\subseteq\C{X}$, one can form the complementary $\infty$-substack $\C{X}\sm\C{Y}\subseteq\C{X}$.

\smallskip

(f) For an $\infty$-stack $\C{X}$ and a point $x\in\C{X}(k)$, we denote by $\iota_x$ the corresponding morphism $\pt:=\Spec k\to \cX$.

\end{Emp}

\begin{Emp} \label{E:classes}
{\bf Classes of morphisms.}

\smallskip

(a) Let $(P)$ be a class of morphisms $f:\C{X}\to Y$ with $\cX\in\St_k$ and $Y\in\Aff_k$, stable under base change. We say that a morphism between $\infty$-stacks {\em belongs to $(P)$}, if its pullback to any affine scheme belong to $(P)$.

\smallskip

(b) Using construction of part~(a), we can talk about representable morphisms (corresponding to the class of all morphisms $X\to Y$ with $X\in\Alg_k$),
representable (locally)-fp morphisms (where {\em fp} stands for {\em finitely-presented}), and fp-open/(locally) closed embeddings between $\infty$-stacks.

\smallskip

(c) We say that a morphism $f:\C{X}\to Y$ with $\cX\in\St_k$ and $Y\in\Aff_k$ is {\em ind-fp-proper}, if $X$ has a presentation as a filtered colimit $\C{X}\simeq\colim_{\al}X_{\al}$ such that $X_{\al}\in \Alg_k$ for all $\al$, each  $X_{\al}\to Y$ is fp-proper, and each transition map
$X_{\al}\to X_{\beta}$ is an fp-closed embedding. Moreover, using the construction of part~(a) we can talk about ind-fp-proper morphisms
between $\infty$-stacks.

\smallskip

(d) We say that an $\infty$-substack $\cY\subseteq\cX$ is {\em topologically fp-(locally) closed},
if for every morphism $X\to\cX$ with $X\in \Aff_k$ there exists an fp-(locally) closed subscheme $Y\subseteq X$ and an isomorphism
$Y_{\red}\simeq (\cY\times_{\cX} X)_{\red}$ over $X$.

