%\section{Dimension theory}

\begin{Emp} \label{E:dimfn}
{\bf Dimension function.}

\smallskip

(a) For  every $X\in\Schft_k$ and $x\in X$, we denote by $\dim_x(X)$ the maximum of dimensions of irreducible components of $X$, containing $x$.

\smallskip

(b) Following \cite[Lemmas~2.2.4--2.2.5]{BKV}, to every locally fp-representable morphism $f:\C{X}\to\C{Y}$ between placid $\infty$-stacks
one can associate a dimension function $\un{\dim}_f:[\C{X}]\to\B{Z}$. Namely, it is uniquely characterised by the following properties:

\smallskip

\quad\quad (i) if $\C{X},\C{Y}\in \Schft_k$, then we have $\un{\dim}_f(x)=\dim_x(\cX)-\dim_{f(x)}(\cY)$ for every $x\in[\cX]$;

\smallskip

\quad\quad (ii) For every Cartesian diagram of placid $\infty$-stacks
\[
\begin{CD}
\C{X}' @>f'>> \C{Y}'\\
@V h VV @VV g V\\
\C{X} @>f>> \C{Y}
\end{CD}
\]
such that $g$ and $h$ are smooth and every $x'\in[\cX']$, we have an equality $\un{\dim}_{f'}(x')=\un{\dim}_{f}(h(x))$;

\smallskip

\quad\quad (iii) for every \'etale schematic morphism $g:\cZ\to\cX$ between placid $\infty$-stacks and every $z\in[\cZ]$, we have an equality
$\un{\dim}_{f\circ g}(z)=\un{\dim}_{f}(g(z))$.
\end{Emp}

\begin{Emp} \label{E:eqdim}
{\bf Equidimensional morphisms} (compare \cite[Section~2.2.6]{BKV}).

\smallskip

(a) A locally fp-representable morphism $f:\cX\to\cY$ of placid $\infty$-stacks is called

\smallskip

\quad\quad $\bullet$ {\em weakly equidimensional} (of relative dimension $d$), if the dimension function $\un{\dim}_f:[\cX]\to\B{Z}$ from
Section~\re{dimfn} is locally constant (constant with value $d$);

\smallskip

\quad\quad $\bullet$ {\em equidimensional}, if it is weakly equidimensional and satisfies $\un{\dim}_f(x) =\dim_x f^{-1}(f(x))$ for
every $x\in[\cX]$;

\smallskip

\quad\quad $\bullet$  {\em uo-equidimensional}, if it weakly equidimensional and universally open (see Section~\re{topsp}(b)).

\smallskip

(b) By \cite[Corollary~2.3.6]{BKV}, a uo-equidimensional morphism is equidimensional.

\smallskip

(c) We say that an fp-locally closed $\infty$-substack $\cX\subseteq\cY$ of a placid $\infty$-stack $\cY$ is of {\em (pure) codimension $d$}
and write $\codim_{\cX}(\cY)=d$, if the inclusion $\cX\hra\cY$ is weakly equidimensional of relative dimension $-d$.
\end{Emp}


