\begin{Emp} \label{E:plstr}
{\bf Placidly stratified $\infty$-stacks.}

\smallskip

(a) We say that an $\infty$-stack $\cY$ is {\em $\cI$-stratified}, if it is equipped with a
bounded constructible stratification $\{\cY_{\al}\}_{\al\in\cI}$ (see Section~\re{consstr}).

\smallskip

(b) We say that an $\cI$-stratified $\infty$-stack $(\cY, \{\cY_{\al}\}_{\al\in\cI})$ is
{\em placidly stratified}, if every $\cY_{\al}$ is a placid $\infty$-stack (see Section~\re{glplsch}(d)). \end{Emp}

\begin{Emp} \label{E:small}
{\bf Small morphisms} (compare \cite[Section~2.4.9]{BKV}).

\smallskip

(a) Let $(\cY, \{\cY_{\al}\}_{\al\in\cI})$ be a placidly stratified $\infty$-stack, $\cU\subseteq\cY$ an fp-open $\{\cY_{\al}\}_{\al\in\cI}$-adapted $\infty$-substack, $f:\cX\to\cY$ a morphism of $\infty$-stacks, $\{\cX_{\al}\}_{\al}$ the induced bounded constructible stratification of $\cX$ (see Section~\re{consstr}(d)), and denote by $f_{\al}:\cX_{\al}\to\cY_{\al}$ the restriction
of $f$.

\smallskip

(b) In the situation of part~(a), assume that $\cX$ is placid. Then, by Section~\re{basic example}(c), each $\cX_{\al}\subseteq\cX$ is a placid
fp-locally closed $\infty$-substack.

\smallskip


(c) In the situation of part~(b), we say that $f$ is $\cU$-\textsl{small} if for every $\al\in\cI$ there exist integers  $b_{\al},\dt_{\al}\in\B{N}$ such that

\smallskip

\quad\quad (i) each $\cX_{\al}\subseteq\cX$ is of pure codimension $b_{\al}$;

\smallskip

\quad\quad (ii) each $f_{\al}$ is locally fp-representable and equidimensional of relative dimension $\delta_{\al}$;

\smallskip

\quad\quad (iii)	for every $\al\in\cI$, one has $\delta_{\al}\leq b_{\al}$, with a strict inequality for $\al\in\cI\sm\cI_{\cU}$.
\end{Emp}

