\begin{Lem} \label{L:La-cstr}
Let $f:X\to S$ a morphism of schemes, let $\Gm$ be a group acting on $X$ over $S$ such that $Y:=[X/\Gm]$ is an algebraic space, fp-proper over $S$. Then the pushforward $f_!:\cD(X)\to \cD(S)$ exists, and for every $K\in\cD(Y)$, the object $f_!(p^!K)\in\cD(S)$ has a natural lift to $\cD^{\Gm}(S)$. Moreover, this lift
belongs to $\cD_{\Gm,c}(S)$ if $K\in \cD_c(Y)$.
\end{Lem}

\begin{proof}
Morphism $f$ gives rise to a Cartesian diagram
\[
\begin{CD}
X @>f>> S\\
@VpVV @VVpV\\
Y=[X/\Gm] @>\ov{f}>> [S/\Gm],
\end{CD}
\]
where $\Gm$ acts on $S$ trivially. Moreover, morphisms $f$ and $\ov{f}$ decomposes as  $X\overset{p}{\to}Y\overset{g}{\to}S$ and
$Y\overset{g}{\to}S\overset{p}{\to}[S/\Gm]$, respectively, and morphism $g:Y\to S$ is fp-proper. By  \cite[Proposition~5.2.5]{BKV}, our assumption on $g$ implies that $g^!$ has a left adjoint $g_!$, from which the existence of $f_!$ and $\ov{f}_!$ follow.

\smallskip

Moreover, since $p$ is \'etale, we have an isomorphism
$f_!(p^!K)\simeq p^!(\ov{f}_!K)$, thus  $f_!(p^!K)\in\cD(S)$ has a natural lift $\ov{f}_!K\in\cD([S/\Gm])\simeq\cD^{\Gm}(S)$.
Finally, if $K\in \cD_c(Y)$, then $g_!K\in \cD_c(S)$, thus $\ov{f}_!K=p_!(g_!K)\in \cD_{\Gm,c}(S)$.
\end{proof}


\begin{Prop} \label{P:Gmcons}
Let $\cX$ be an admissible $\infty$-stack, let $\Gm$ be a group such that $\qlbar[\Gm]$ is Noetherian of finite cohomological dimension, and let   $K\in\cD^{\Gm}(\cX)$. Then we have $K\in\cD_{\Gm,c}(\cX)$ if and only if we have $\For(K)\in\cD_{\on{ess}-c}(\cX)$
and $\iota_x^!K\in\cD_{\Gm,c}(\pt)=\cD_{\perf}(\qlbar[\Gm])$ for every $x\in \cX(k)$.
\end{Prop}

\begin{proof}
By \rl{Gmconsstr}(b), we can assume that $\cX$ is an admissible affine scheme $X$.

\smallskip

Assume first $X$ is of finite type over $k$. If $K\in\cD_{\Gm,c}(X)$, then $\For(K)\in\cD_{\on{ess}-c}(X)$ by Section~\re{func}(b), and each $\iota_x^!K\in\cD_{\Gm,c}(\pt)$ because $\iota_x^!$ preserves $\Gm$-constructibility. Conversely, assume that $\ov{K}:=\For(K)\in\cD_{\on{ess}-c}(X)$ and $\iota_x^!K\in \cD_{\perf}(\qlbar[\Gm])$ for every $x\in X(k)$.

\smallskip

By \rl{Gmconsstr}(a), it suffices to show that there exists a finite constructible stratification $\{X_{\al}\}_{\al}$ of $X$ such that
$\eta_{\al}^!K\in \cD_{\Gm,c}(X_{\al})$ for all $\al$. Thus, by \rl{ess-c}, we can replace  $K$ by  $\eta_{\al}^!(K)$, thus assuming that $X$ is smooth connected, $\ov{K}\in \cD^b(X)$ and each $\cH^i(\ov{K})$ is a finite extension of the $L\otimes_{\qlbar}V$'s, where $L$ is an irreducible constructible local system on $X$ and $V$ is a $\qlbar$-vector space.

\smallskip

Since $\qlbar[\Gm]$ is Noetherian of finite cohomological dimension, we have $\iota_x^!K\in\cD_{\perf}(\qlbar[\Gm])$ if and only if 
$\bigoplus_i H^i(\iota_x^!K)$ is a finitely generated $\qlbar[\Gm]$-module. Since $K$ is a finite extension of its shifted cohomologies, and $\iota_x^![-2\dim X]\simeq \iota^*_x$ is exact, we can replace $K$ by $\bigoplus_i \C{H}^i(K)$, thus assuming that $\ov{K}=\For(K)$ is a finite extension of the $L\otimes_{\qlbar}V$'s, where $L$ is a simple (constructible) local system on $X$ and $V$ is a $\qlbar$-vector space.

\smallskip

In this case, $\ov{K}$ has a canonical finite increasing filtration $\{\ov{K}_{\leq i}\}_i$, defined by the property that $\ov{K}_{\leq i+1}/\ov{K}_{\leq i}$ is the largest semisimple local subsystem of $\For(K)/\For(K)_{\leq i}$. In particular, each  $\ov{K}_{\leq i}$ is $\Gm$-invariant, so filtration $\{\ov{K}_{\leq i}\}_i$ gives rise to a filtration $\{K_{\leq i}\}_i$ of $K$.

\smallskip

Replacing $K$ by its graded piece $\gr^i(K)$, we can assume that $\ov{K}$ is semisimple and has only many simple factors. In this case, $K$ decomposes as a finite direct sum $\bigoplus_{L}K_{L}$, where $L$ runs over the set of isomorphism classes of simple local systems $L$ on $X$, and  $K_{L}:=\Hom(L,\ov{K})\otimes_{\qlbar}L$. Now our assumption that each $H^i(\iota_x^!K)$ is a finitely generated $\qlbar[\Gm]$-module
implies that each $\Hom(L,\ov{K})$ is a finitely generated $\qlbar[\Gm]$-module. Thus $K_{L}\in\cD_{\Gm,c}(X)$ for all $L$, hence $K\in\cD_{\Gm,c}(X)$.

\smallskip

In the general case, choose an admissible presentation $X\simeq\lim_{\al}X_{\al}$. Then $\For(K)$ is a pullback of $\For(K)_{\al}\in\cD_{\on{ess}-c}(X_{\al})\subseteq \cD(X_{\al})$ for some $\al$ (by \rl{adm-essc}). Next, using the fact that the pullback $\pi_{\al}^!:\cD(X_{\al})\to\cD(X)$ is fully faithful, we conclude that the natural functor
\[
\cD^{\Gm}(X_{\al})\to\cD(X_{\al})\times_{\cD(X)}\cD^{\Gm}(X)
\]
is an equivalence.  Thus, $K$ is a pullback of a unique object $K_{\al}\in \cD^{\Gm}(X_{\al})$ such that
\[
\For(K_{\al})\simeq \For(K)_{\al}\in\cD_{\on{ess}-c}(X_{\al}).
\]

Since presentation $X\simeq\lim_{\al}X_{\al}$ is admissible, the projection $\pi_{\al}:X(k)\to X_{\al}(k)$ is surjective. Hence,
our assumption implies that $\iota_{x_{\al}}^!(K_{\al})\in\cD_{\Gm,c}(\pt)$ for every $x_{\al}\in X_{\al}(k)$. Then, we get $K_{\al}\in \cD_{\Gm,c}(X_{\al})$ (by the particular case shown above), hence $K=\pi_{\al}^!(K_{\al})\in\cD_{\Gm,c}(X)$.
\end{proof}

