\subsection{Perverse $t$-structures}

\begin{Emp} \label{E:tstrdc}
{\bf Perverse $t$-structures on $\cD_c(X)$.} Following \cite[Section~6.2.3]{BKV}, for every $X\in\Schft_k$ we equip the $\infty$-category $\cD_c(X)$ with a canonical ($!$-adapted) perverse $t$-structure $({}^p\cD_c^{\leq 0}(X),{}^p\cD_c^{\geq 0}(X))$:

\smallskip

(a) If $X$ is equidimensional, we equip $\cD_c(X)$ with the $t$-structure $({}^p\cD_c^{\leq 0}(X),{}^p\cD_c^{\geq 0}(X))$,
obtained from the classical (middle-dimensional) perverse $t$-structure by shifting it by $\dim X$ to the left.

\smallskip

(b) For a general $X$, consider finite constructible stratification $X_i:=\{x\in X~\vert~\dim_x(X)=i\}$ (see \cite[Section~2.1.1]{BKV}).
Then each $X_i$ is equidimensional of dimension $i$, and we denote the inclusion $X_i\hra X$ by $\eta_i$. We define $({}^p\cD_c^{\leq 0}(X),{}^p\cD^{\geq 0}(X))$ to be the $t$-structure on $\cD_c(X)$, obtained from the $t$-structures $({}^p\cD_c^{\leq 0}(X_i),{}^p\cD_c^{\geq 0}(X_i))$ from part~(a) by gluing. Explicitly, we define
${}^p\cD_c^{\leq 0}(X)$ (resp. ${}^p\cD_c^{\geq 0}(X)$) to be the collection of all $K\in \cD_c(X)$ such that
$\eta_i^*(K)\in {}^p\cD_c^{\leq 0}(X_i)$ (resp. $\eta_i^!(K)\in {}^p\cD_c^{\geq 0}(X_i)$) for all $i$.

\smallskip

(c) By \cite[Lemma~6.2.5(c)]{BKV}, for every smooth morphism $f:X\to Y$, the pullback $f^!$ is $t$-exact.
\end{Emp}

\begin{Emp} \label{E:tstr}
{\bf Perverse $t$-structures on placid $\infty$-stacks.}

\smallskip

(a) Following \cite{BKV}, for every placid $\infty$-stack $\C{X}$ we equip the $\infty$-category $\cD(\cX)$
with a canonical perverse $t$-structure $({}^p\cD^{\leq 0}(\cX),{}^p\cD^{\geq 0}(\cX))$.
Namely, using \cite[Lemma~6.1.2(a) and Propositions~6.3.1, 6.3.3]{BKV} it can be uniquely characterised by the following properties:

\smallskip

\quad (i) when $\cX\in\Schft_k$, then $({}^p\cD^{\leq 0}(\cX),{}^p\cD^{\geq 0}(\cX))$ extends the $t$-structure $({}^p\cD_c^{\leq 0}(\cX),{}^p\cD_c^{\geq 0}(\cX))$ on $\cD_c(\cX)$ described in Section~\re{tstrdc}(b);

\smallskip

\quad (ii) for every smooth morphism $f:\cX\to\cY$ of placid $\infty$-stacks, the pullback $f^!$ is $t$-exact;

\smallskip

\quad (iii) the $t$-structure $({}^p\cD^{\leq 0}(\cX),{}^p\cD^{\geq 0}(\cX))$ is {\em compatible with filtered colimits}, that is,
the $\infty$-subcategory ${}^p\cD^{\geq 0}(\cX)\subseteq\cD(\cX)$ is closed under filtered colimits.

\smallskip

(b) By \cite[Section~5.3.1(e) and Lemma~6.1.2(d)]{BKV}, we conclude that for every smooth covering $f:\cX\to\cY$ of placid $\infty$-stacks
and $K\in \cD(\cX)$ we have $K\in{}^p\cD^{\geq 0}(\cX)$ if and only if $f^!K\in{}^p\cD^{\geq 0}(\cY)$.
\end{Emp}








\begin{Lem} \label{L:gluing}
Assume that $X\in\Schft_k$ is equipped with a finite constructible stratification $\{X_{\al}\}_{\al}$ such that each $X_{\al}\subseteq X$ is of pure codimension $d_{\al}$, let $\eta_{\al}:X_{\al}\hra X$ be the inclusion maps, and let $K\in\cD(X)$. Then we have $K\in \mathstrut^{p}\cD^{\leq 0}(X)$ (resp. $K\in \mathstrut^{p}\cD^{\geq 0}(X)$) if and only if $\eta_{\al}^*K\in {}^p\cD^{\leq -d_{\al}}(X_{\al})$ (resp. $\eta_{\al}^!K_{\al}\in {}^p\cD^{\geq -d_{\al}}(X_{\al})$) for all $\al$.
\end{Lem}

\begin{proof}
The ``only if'' assertion follows from the fact that functor $\eta_{\al}^*[-d_{\al}]$ is right $t$-exact, while functor $\eta_{\al}^![-d_{\al}]$ is left   $t$-exact (see \cite[Lemma~6.2.5(b)]{BKV}). By adjointness, functor $(\eta_{\al})_![d_{\al}]$ is right  $t$-exact, while functor $(\eta_{\al})_*[d_{\al}]$ is left  $t$-exact. From this the ``if'' assertion follows. Indeed, if $\eta_{\al}^!K\in {}^p\cD^{\geq -d_{\al}}(X_{\al})$ for all $\al$, then $(\eta_{\al})_*\eta_{\al}^!K\in {}^p\cD^{\geq 0}(X)$ for all $\al$. Since $K$ is a finite extension of the $(\eta_{\al})_*\eta_{\al}^!K$'s,
 we conclude that $K\in \mathstrut^{p}\cD^{\geq 0}(X)$. The assertion for $\mathstrut^{p}\cD^{\leq 0}(X)$ is similar.
\end{proof}


\begin{Prop}\label{pullcheck}
Let $\cX$ be an admissible $\infty$-stack (see Section~\re{admstack}), and we equip $\cD(\cX)$ with its canonical perverse $t$-structure
(see Section~\re{tstr}). Let $K\in \cD_{\on{ess}-c}(\cX)$ be such that for every  $x\in \cX(k)$, we have $\iota_x^{!}K\in \mathstrut^{p}\cD^{\geq 0}(\pt)$.
Then $K\in \mathstrut^{p}\cD^{\geq 0}(\cX)$.
\end{Prop}

%TO WRITE DOWN A MORE GENERAL CRITERION???

\begin{proof}
By Section~\re{tstr}(b), we can assume that $\cX$ is an affine admissible $k$-scheme $X$. 

\smallskip

Assume first that $X$ is of finite type over $k$. By \rl{ess-c}, there exists a finite constructible stratification
$\{X_{\al}\}_{\al}$ of $X$ such that each $X_{\al}$ is smooth connected, each inclusion $\eta_{\al}:X_{\al}\hra X$ is weakly equidimensional of relative dimension $-d_{\al}$ and all cohomology sheaves $\cH^i(K_{\al})$ of all $K_{\al}:=\eta^!_{\al}K$ are local systems.

By \rl{gluing}, we have $K\in \mathstrut^{p}\cD^{\geq 0}(X)$ if and only if  $K_{\al}\in {}^p\cD^{\geq -d_{\al}}(X_{\al})$ for all $\al$.
In particular, it suffices to show that  $K_{\al}\in {}^p\cD^{\geq 0}(X_{\al})$ for all $\al$. Thus, replacing $X$ by $X_{\al}$ and $K$ by
$K_{\al}$, we can assume that $X$ is smooth connected and all cohomology sheaves $\cH^i(K)$ are local systems.
Then our assumption that $\iota_x^{!}K\simeq \iota_x^* K[2\dim X]\in \mathstrut^{p}\cD^{\geq 0}(\pt)$ implies that
$K\in \cD^{\geq -2\dim X}(X)$, where $\cD^{\geq -2\dim X}$ refers to the usual (rather than perverse) $t$-structure. Since $\cD^{\geq -2\dim X}(X)=\mathstrut^{p}\cD^{\geq 0}(X)$, we are done.

\smallskip

For a general $X$, choose an admissible presentation $X\simeq\lim_{\al} X_{\al}$, with projections $\pi_{\al}$.  Since  $K\in \cD_{\on{ess}-c}(X)$ we conclude from \rl{adm-essc} that there exists an index $\al$ and $K_{\al}\in\cD_{\on{ess}-c}(X_{\al})$ such that $K\simeq \pi_{\al}^!K_{\al}$. Moreover, since the projection $\pi_{\al}:X(k)\to X_{\al}(k)$ is surjective, our assumption implies that $\iota_{x_{\al}}^{!}(K_{\al})\in \mathstrut^{p}\cD^{\geq 0}(\pt)$ for all  $x_{\al}\in X_{\al}(k)$. Therefore, by the assertion for $X_{\al}$, shown above, we get $K_{\al}\in \mathstrut^{p}\cD^{\geq 0}(X_{\al})$. Since $\pi_{\al}^!$ is $t$-exact, the assertion follows.
\end{proof}

\begin{Emp} \label{E:pervfun}
{\bf Perversity function.}

\smallskip

(a) By a {\em perversity} on an $\cI$-stratified $\infty$-stack $(\cY,\{\cY_{\al}\}_{\al\in\cI})$ (see Section~\re{plstr}),
we mean a function $p_{\nu}:\cI\to \B{Z}:\al\mapsto\nu_{\al}$, or, what is the same, a collection $\{\nu_{\al}\}_{\al\in\cI}$ of integers.

\smallskip

(b) Let $f:\cX\to \cY$ be a morphism of $\infty$-stacks, where $\cX$ is a placid $\infty$-stack,
and $(\cY, \{\cY_{\al}\}_{\al\in\cI})$  is a placidly stratified $\infty$-stack, satisfying assumptions (i) and (ii) of Section~\re{small}(c).
Then $f$ gives rise to perversity $p_{f}:=\{\nu_{\al}\}_{\al\in\cI}$, defined by $\nu_{\al}:=b_{\al} +\dt_{\al}$ for all $\al\in\cI$.
\end{Emp}





\begin{Emp} \label{E:pervplstr}
{\bf Perverse $t$-structures on placidly stratified $\infty$-stacks.}

\smallskip

(a) Following \cite[Definition~5.5.1]{BKV},  we say that an $\infty$-stack $\cY$ {\em admits gluing of sheaves}, if for every topologically
fp-locally closed embedding $\eta:\cX\to\cY$, the pushforward $\eta_*:\cD(\cX)\to \cD(\cY)$ (see \cite[Section~5.4.4]{BKV}) admits a
left adjoint $\eta^* :\cD(\cY)\to \cD(\cX)$.

\smallskip

(b) Let $(\cY,\{\cY_{\al}\}_{\al\in\cI})$ be a placidly stratified $\infty$-stack such that $\cY$ admits gluing of sheaves. As every $\cY_{\al}$ is placid, every $\cD(\cY_{\al})$ has a canonical perverse  $t$-structure $(\mathstrut^{p}\cD^{\leq 0}(\cY_{\al}),\mathstrut^{p}\cD^{\geq 0}(\cY_{\al}))$ (see Section~\re{tstr}). Since $\cY$ admits gluing of sheaves, we have pullback functors $\eta_{\al}^{*},\eta_{\al}^{!}:\cD(\cY)\to\cD(\cY_{\al})$.

\smallskip

Then, by \cite[Proposition~6.4.2]{BKV}, for every perversity function  $p_{\nu}=\{\nu_{\al}\}_{\al\in\cI}$ there exists a unique $t$-structure $(\mathstrut^{p_{\nu}}\cD^{\leq 0}(\cY),\mathstrut^{p_{\nu}}\cD^{\geq 0}(\cY))$ on $\cD(\cY)$ such that
\begin{equation*}
\mathstrut^{p_{\nu}}\cD^{\leq 0}(\cY)=\{K\in\cD(\cY)~\vert~\eta_{\al}^{*}K\in\mathstrut^{p}\cD^{\leq -\nu_{\al}}(\cY_{\al})\text{ for all }\al\in\cI\},
\end{equation*}
\begin{equation*}
\mathstrut^{p_{\nu}}\cD^{\geq 0}(\cY)=\{K\in\cD(\cY)~\vert~\eta_{\al}^{!}K\in\mathstrut^{p}\cD^{\geq -\nu_{\al}}(\cY_{\al})\text{ for all }\al\in\cI\}.
\end{equation*}

(c) We say that a sheaf $K\in \cD(\cY)$ is {\em $p_{\nu}$-perverse}, if it is perverse with respect to perversity $p_{\nu}$.
\end{Emp}

\begin{Emp} \label{E:interm}
{\bf The intermediate extension.} Suppose we are in the situation of Section~\re{pervplstr}(b), and let $\cU\subseteq\cY$ be an
fp-open $\infty$-substack.

\smallskip

(a) Then $\cU\subseteq\cY$ is equipped with a constructible stratification $\{\cU_{\al}\}_{\al\in\cI_{\cU}}$, where   $\cU_{\al}:=\cU\cap \cY_{\al}$ for every $\al\in \cI$ and $\cI_{\cU}:=\{\al\in\cI~\vert~\cU_{\al}\neq\emptyset\}$. Moreover,
$(\cU,\{\cU_{\al}\}_{\al\in\cI_{\cU}})$ is a placidly stratified $\infty$-stack.

\smallskip

(b) The perversity function  $p_{\nu}:\cI\to\B{Z}$ restricts to a perversity function $p^{\cU}_{\nu}:\cI_{\cU}\to\B{Z}$, thus gives rise to a
perverse $t$-structure $(\mathstrut^{p^{\cU}_{\nu}}\cD^{\leq 0}(\cU),\mathstrut^{p^{\cU}_{\nu}}\cD^{\geq 0}(\cU))$ on $\cD(\cU)$.

\smallskip

(c) For every $p_{\nu}$-perverse sheaf $K\in \cD(\cY)$, its restriction $K|_{\cU}\in \cD(\cU)$ is $p^{\cU}_{\nu}$-perverse. Conversely, for every $p^{\cU}_{\nu}$-perverse sheaf $K_U\in \cD(\cU)$ there exists a unique extension $K\in\cD(\cY)$ (called the {\em intermediate extension}) such that $K$ is $p_{\nu}$-perverse and $K$ does not have non-zero subobjects and quotients supported on $\cY\sm\cU$ (see \cite[Corollary~6.4.9]{BKV}).
\end{Emp}

\begin{Emp} \label{E:!ls}
{\bf $!$-local systems.}

\smallskip

(a) For every $\infty$-prestack $\C{X}$, we define a full subcategory $\Loc^!(\cX)\subseteq\cD(\cX)$ of {\em $!$-local systems} defined as follows:
\smallskip

\quad $\bullet$ For $Y\in \Affft_k$, we denote by $\Loc^!(Y)$ be the full $\infty$-subcategory of $\cD(Y)$ consisting of objects
$\omega_{Y,\cL}:=\omega_{Y}\otimes \cL$, where $\cL$ is a usual (ind-constructible) local system on $Y$ and $\om_Y$ is a dualizing complex.
For every morphism $f:Y'\to Y$ of $\Affft_k$, we have a natural isomorphism
$f^!(\omega_{Y,\cL})\simeq \omega_{Y',f^*\cL}$, thus the class of $!$-local systems is closed under $!$-pullbacks.

\smallskip

\quad $\bullet$ Next, for $X\in \Aff_k$, we denote by $\Loc^!(X)$ be the full $\infty$-subcategory of $\cD(X)$ consisting of objects
$f^!K$, where $f:X\to Y$ is a morphism with $Y\in \Affft_k$ and $K\in\Loc^!(Y)$. Finally, for an arbitrary $\infty$-prestack $\cX$, we denote by
$\Loc^!(\cX)$ be the full $\infty$-subcategory of $\cD(\cX)$ consisting of objects $K$ such that $f^!K\in \Loc^!(X)$ for every morphism
$f:X\to \cX$ from an affine scheme $X$.

\smallskip

(b) By construction, the class of $!$-local systems is closed under $!$-pullbacks and $!$-tensor products. In particular,
for every morphism $f:\cX\to Y$ with $Y\in \Affft_k$ and every local system $\cL$ on $Y$, the pullback $\om_{\cX,\cL}:=f^!(\om_{Y,\cL})$ is a $!$-local system. To simplify the notation, we will often write $\om_{\cL}$ instead of $\om_{\cX,\cL}$.

\smallskip

(c) For every $Y\in\Algft_k$ and $K\in\Loc^!(X)$, 
we have $K\in \cD^{\geq -2\dim Y}(Y)$, where $\cD^{\geq -2\dim Y}$ refers to the usual (rather than perverse) $t$-structure.  More generally, mimicking the proof of \cite[Lemma~6.3.5(a)]{BKV}, for every placid $\infty$-stack $\cX$ and $K\in\Loc^!(\cX)$ we have
$K\in \mathstrut^{p}\cD^{\geq 0}(\cX)$.

\smallskip

(d) Similarly, mimicking the proof of \cite[Lemma~6.3.5(d)]{BKV}, one shows that if $\eta:\cX\hra\cY$ is an fp-locally closed immersion between placid $\infty$-stacks of codimension $d$ with $\cY$ smooth, then for every  $K\in\Loc^!(\cY)$ we have $\eta^{*}K\in \mathstrut^{p}D^{\leq -2d}(\cX) $.
\end{Emp}

The following result is a slight generalization of \cite[Theorem~6.5.3]{BKV}.

\begin{Thm}\label{g-small}
Let $(\cY,\{\cY_{\al}\}_{\al\in\cI})$ be a placidly stratified $\infty$-stack, let $\C{U}\subseteq \C{Y}$ be an fp-open $\{\cY_{\al}\}_{\al\in\cI}$-adapted $\infty$-substack, and let $f:\cX\to\cY$ be a $\C{U}$-small morphism of $\infty$-stacks such that
