\subsection{Lemmas on quasi-coherent sheaves}\label{app}

Motivated by a nice trick explained to us by Zhiwei Yun, in this section we will establish simple properties of quasi-coherent sheaves, playing a central role in the proof of Proposition~\ref{p-tau2}.

%In the sequel, all tensor products are derived.

\begin{Lem} \label{coh-loc}
Let $i:X\hra Y$ be a closed embedding of codimension $d$ between smooth connected schemes over $k$. Then

\smallskip

(a) the derived pullback functor $i^{*}: D^{+}(\on{QCoh}(Y))\to D^{+}(\on{QCoh}(X))$ sends $D^{\geq 0}$ to $D^{\geq -d}$;

\smallskip

(b) for every non-zero sheaf $K\in\on{QCoh}(Y)$, which is scheme-theoretically supported on $X$, we have $\cH^{-d}(i^{*}K)\neq 0$.
\end{Lem}
\begin{proof}
(a) follows from the Koszul resolution of $i_*\mathcal{O}_X$.

\smallskip

(b) By assumption, one has $K=i_{*}M$ for some $M\in\on{QCoh}(X)$. Thus, by the projection formula, we have $i^{*}i_{*}M\simeq M\otimes_{\mathcal{O}_{X}}i^{*}i_{*}\mathcal{O}_X$, and the assertion follows from the Koszul resolution for $i_*\mathcal{O}_X$ as well.
\end{proof}

\begin{Cor}\label{coh2}
In the situation of Lemma~\ref{coh-loc}, let $K\in D^{\geq 0}(\on{QCoh}(Y))$ be such that $\cH^{0}(K)$ has a non-zero subsheaf $K'$, which is scheme-theoretically supported on $X$. Then $\cH^{-d}(i^{*}K)\neq 0$.
\end{Cor}
\begin{proof}
Consider the fiber sequence
\[i^{*}\cH^{0}(K)\to i^{*}K\to i^{*}\tau^{> 0}K.\]
Since $i^{*}\tau^{> 0}K$ belongs to $D^{\geq -d+1}$ by Lemma~\ref{coh-loc}(a), we conclude that $\cH^{-d}(i^{*}\cH^0(K))\simeq\cH^{-d}(i^{*}K)$. Thus, replacing $K$ by $\cH^{0}(K)$, we can assume that $K\in\on{QCoh}(Y)$. Then, using Lemma \ref{coh-loc}(a) for $i^{*}(K/K')$, we obtain that the map
\[\cH^{-d}(i^{*}K')\to \cH^{-d}(i^{*}K)\]
is injective. Since  $\cH^{-d}(i^{*}K')\neq 0$ by Lemma~\ref{coh-loc}(b), the assertion follows.
\end{proof}

\begin{Prop}\label{coh3}
Let $\eta_1,\dots, \eta_m:X\to Y$ be closed embeddings of smooth connected $k$-schemes, let $p_X:X\times Y\to X$ and
 $p_Y:X\times Y\to Y$ be projections, and let $K\in D^{+}(\on{QCoh}(X\times Y))$ be such that

\smallskip

(i)	$K$ is set-theoretically supported on the union of the graphs of the $\eta_a$'s;

\smallskip

(ii)	we have $K\otimes p_{X}^{*}A\in D^{\geq 0}$ for all $A\in\on{QCoh}(X)$.

\smallskip

\noindent Then we have $K \otimes p_{Y}^{*}B\in D^{\geq \dim X-\dim Y}$ for all $B\in\on{QCoh}(Y)$.
\end{Prop}

\begin{proof}
Let $n$ be the minimal integer $j$ such that $\cH^{j}(K \otimes p_{Y}^{*}B)\neq 0$. We want to show that $n\geq \dim X-\dim Y$. By assumption~(i), there exists a nonzero subsheaf $K'\subseteq \cH^{n}(K\otimes p_{Y}^{*}B)$, which is scheme-theoretically supported on the graph of some $\eta_a$.

Consider morphism $\Gm_{\eta_a}:=(\Id_X,\eta_a):X\to X\times Y$.  It is a closed embedding of smooth connected $k$-schemes of codimension $\dim Y$.
Thus, by Corollary \ref{coh2}, we have $\cH^{n-\dim Y}(\Gm_{\eta_a}^{*}(K \otimes p_{Y}^{*}B))\neq 0$. So it suffices to show that $\Gm_{\eta_a}^{*}(K\otimes p_{Y}^{*}B)\in D^{\geq \dim X-2\dim Y}$.

Using isomorphisms
\[\Gm_{\eta_a}^{*}(K \otimes p_{Y}^{*}B)\simeq \Gm_{\eta_a}^{*}(K) \otimes \eta_{a}^{*}B\simeq \Gm_{\eta_a}^{*}(K \otimes p_{X}^{*}(\eta_{a}^{*}B))\]
and Lemma~\ref{coh-loc}(a), it suffices to prove that $K \otimes p_{X}^{*}(\eta_a^{*}B)\in D^{\geq \dim X-\dim Y}$.
By Lemma~\ref{coh-loc}(a), we have $\eta_{a}^{*}B\in D^{\geq \dim X-\dim Y}$, so the assertion follows from assumption (ii).
\end{proof}


\section{Group analogs of results of \cite{BKV}}

In this section, we will show analogs of the results \cite{BKV} in the group case.


\subsection{Flatness of the Chevalley map for arcs}


\begin{Emp} \label{E:looparc}
{\bf Arc and loop spaces.} We set $\co:=k[[t]]$ and $F:=k((t)))$.

\smallskip

(a) For an affine scheme of finite type $X$ over $\co$, we denote by $\clp(X)$ the affine scheme over $k$ (called  the {\em arc space} of $X$),
representing a functor $A\mapsto X(A[[t]])$. Then $\clp(X)\simeq\lim_{n\in\B{N}}\cL_n(X)$, where
$\cL_n(X)$ is an affine scheme of finite type over $k$ (called the {\em $n$-truncated arc space} of $X$), representing a functor $A\mapsto X(A[t]/(t^{n+1}))$.

\smallskip

(b) We have a closed embedding $X\hra \cL_n (X)$, corresponding to the $A$-algebra homomorphism
$A\hra A[t]/(t^{n+1})$, and projections $\ev_n:\cL_n (X)\to X$ and $\ev:\clp(X)\to X$, corresponding to the $A$-algebra homorphisms $A[t]/(t^{n+1})\to A$ and $A[[t]]\to A$ such that $t\mapsto 0$.

\smallskip

(c) We have a natural action of multiplicative group $\B{G}_m$ on $\cL_n (X)$ over $X$, which corresponds to the action of $A^{\times}$ on the $A$-algebra $A[t]/(t^{n+1})$ given by the rule $a\cdot f(t):=f(at)$. Then for $x\in \cL_n (X)(k)$ and $a\in \B{G}_m$,  the limit $\lim_{a\to 0}(a\cdot x)$ exists and is equal to $\ev_n(x)$.

\smallskip

(d) If $X$ is smooth over $\cO$, then the argument of \cite[Section~3.1.4]{BKV} shows that the arc space $\cL(X)$ is admissible and  $\cL(X)\simeq\lim_n\cL_n(X)$ is an admissible presentation.

\smallskip

(e) For every affine scheme of finite type $X$ over $F$, we denote by $\cL(X)$ the ind-scheme over $k$ representing functor
$A\mapsto X(A((t)))$, which is called the {\em loop  space} of $X$ (compare \cite[Section~3.1.5]{BKV}).
\end{Emp}


\begin{Emp} \label{E:setup}
{\bf Set up.}

\smallskip

(a) Let $G$ be a connected reductive group over $k$, let $B\supseteq T$ be a Borel group and a maximal torus of $G$, respectively, let $W$\label{N:W} be the Weyl group of $G$, let $\La:=X_{*}(T)$\label{N:X*T} be the lattice of cocharacters of $T$, let $\widetilde{W}:=\La\rtimes W$\label{N:Waff} be the extended affine Weyl group of $G$, and let $R$\label{N:R} be the set of roots of $G$.

\smallskip

(b) By a theorem of Steinberg--Chevalley \cite{S}, the restriction map $k[G]\to k[T]$ induces an isomorphism $k[G]^{G}\isom k[T]^{W}$, where $G$ acts by conjugacy. Let $\kc:=T/W=\Spec(k[G]^G)$\label{N:c} be the Chevalley space of $G$. Then we have canonical projections  $\chi:G\rightarrow \kc$\label{N:chi} and $\pi:T\rightarrow\kc$.

\smallskip

(c) Let $\mathfrak{D}:=\prod_{\alpha\in R}(1-\alpha)$\label{N:mathfrakD} be the discriminant function.
Then $\mathfrak{D}\in k[\kc]=k[T]^W$, and the regular semisimple locus $\kc^{\rs}\subseteq\kc$\label{N:crs} is the complement of the locus
$Z(\mathfrak{D})$ of zeros of $\mathfrak{D}$. We denote by  $G^{\rs}:=\chi^{-1}(\kc^{\rs})$\label{N:grs} and $T^{\rs}:=\pi^{-1}(\kc^{\rs})$\label{N:trs} the preimages of $\kc^{\rs}$.

\smallskip

(d) For most of the paper (everywhere except \rl{eqdim}) we will assume that the derived group $G^{\der}$ of $G$ is simply connected. In this case, $\kc$ is a smooth affine scheme (by \cite[Theorem~6.1]{S}). Furthermore, this assumption implies that the centralizer of every semisimple
$g\in G$ is connected (see \cite[$\S$~2.11, Theorem]{H}) that centralizer of every $g\in G^{\rs}$ is a maximal torus and that the restriction $\pi^{\rs}:T^{\rs}\to \fc^{\rs}$ of $\pi$ is a $W$-torsor (see \cite[$\S$~2.5, Remark]{H}).

\smallskip

(e) We denote by $I:=\ev^{-1}(B)\subseteq\clp (G)$\label{N:I} the Iwahori subgroup scheme of $\cL G$ and denote by
$v:I\to\clp(\kc)$ the restriction of $\chi:\kg\rightarrow \kc$. Similarly, for every $n\in\B{N}$, we set $I_n:=\ev_n^{-1}(B)\subseteq \cL_n(G)$ and let $v_n:I_n\to\cL_n(\kc)$ be the restriction of $\chi_n:= \cL_{n}(\chi):\cL_{n}(G)\to\cL_n(\kc)$.

\smallskip

(f) Following \cite{Yun1, Yun}, we assume that the characteristic of $k$ is either zero  or greater than $2h$, where $h$ is the Coxeter number of $G$. Note that this assumption implies that the characteristic of $k$ is prime to $|W|$, hence prime to the cardinality of $Z(G^{\der})$.
\end{Emp}



