The following result is central for what follows.

\begin{Thm}\label{flat1}
%Assume $G_{der}$ be simply connected, assume that $p$ is a very good prime.
For every $n\in\NN$, the morphisms $\chi_n:\cL_{n}(G)\to\cL_n(\kc)$ and $v_n:I_n\to\cL_n(\kc)$ are flat.
\end{Thm}

Our strategy will be to deduce the result from the corresponding results for Lie algebras shown in \cite[Theorem~3.4.7]{BKV}.\footnote{Notice that unlike many of the results of \cite{BKV}, which are proven under an assumption that the characteristic of $k$ is prime to $|W|$, our proof of \cite[Theorem~3.4.7]{BKV} uses \cite[Corollary~2.5.2]{Yun1} and therefore is only valid under the stronger assumption of Section~\re{setup}(f).}

\begin{Lem} \label{L:eqdim}
Assume that $G$ satisfies the assumption of Section~\re{setup}(f) but not necessary of Section~\re{setup}(d), and
let $\C{U}_G\subseteq G$ be the locus of unipotent elements of $G$. Then we have equalities
%
\begin{equation} \label{Eq:eqdim}
\dim\cL_n(\C{U}_G)=\dim\cL_{n}(G)-\dim \cL_n(\kc),\quad \dim(\cL_n(\C{U}_G)\cap I_n)=\dim I_n-\dim \cL_n(\kc).
\end{equation}
%
\end{Lem}
\begin{proof}
Let $G^{\on{sc}}$ be the semisimple covering of the derived group of $G$, and let $\C{N}_{\fg}$ be the variety of nilpotent elements of
$\fg:=\Lie G$.

Since the projection $G^{\on{sc}}\to G$ induces an isomorphism  $\C{U}_{G^{\on{sc}}}\isom\C{U}_G$, we can replace $G$ by $G^{\on{sc}}$,
thus assuming that $G$ is semisimple and simply connected. Then, applying results of Springer \cite{Spr} (or
using quasi-logarithms of \cite[Section~1.8]{KV} and results of \cite{BR}) one shows that there exists an $\Ad G$-equivariant isomorphism
$\Phi:\C{U}_{G}\isom\C{N}_{\fg}$, inducing an isomorphism $R_u(B)\isom \Lie R_u(B)$. Therefore $\Phi$ induces isomorphisms
%
\begin{equation} \label{Eq:isom2}
\cL_n(\C{U}_G)\isom \cL_n(\C{N}_{\fg}), \quad \cL_n(\C{U}_G)\cap I_n\isom\cL_n(\C{N}_{\fg})\cap\Lie I_n.
\end{equation}
%

Since $\C{N}_{\fg}=\chi_{\fg}^{-1}(0_{\fc})$, where $\chi_{\fg}:\fg\to\fc_{\fg}$ is the Chevalley map for $\fg$ and
$0_{\fc}:=\chi_{\fg}(0)$, and since  $\cL_n$ commutes with limits, we have $\cL_n(\C{N}_{\fg})=\cL_{n}(\chi_{\fg})^{-1}(0_{\fc})$.
Therefore equalities \form{eqdim} follows from isomorphisms \form{isom2} and flatness of morphisms
$\cL_n(\chi_{\fg}):\cL_n(\fg)\to\cL_n(\fc_{\fg})$ and $v_n:\Lie I_n\to\cL_n(\fc_{\fg})$, established in \cite[Theorem~3.4.7]{BKV}.
\end{proof}

\begin{Cor} \label{C:eqdim}
In the situation of Theorem~\ref{flat1}, for every $a\in\fc(k)$, we have equalities
%
\begin{equation} \label{Eq:eqdim2}
\dim\cL_n(\chi^{-1}(a))=\dim\cL_{n}(G)-\dim \cL_n(\kc), \quad \dim(\cL_n(\chi^{-1}(a))\cap I_n)=
\dim I_n-\dim \cL_n(\kc).
\end{equation}
%
\end{Cor}
\begin{proof}
%Assume first that $s$ lies in the center $Z(G)$. Then the map $g\mapsto zg:G\isom G$ is $\Ad G$-equivariant, so it induces an isomorphism
%$\chi^{-1}(\chi(1))\isom \chi^{-1}(\chi(s))$, therefore the inequality \form{in} for $s$ follows from that for $1$,
%established in Step 2.

To show the first equality \form{eqdim2}, we choose any $s\in T(k)\cap \chi^{-1}(a)$. Then $\chi^{-1}(a)\subseteq G$ consists of elements $g$ with Jordan decomposition $g=g_s u_s$
such that $g_s$ is $G$-conjugate to $s$. Since $G^{\der}$ is assumed to be simply connected, the centralizer $G_s$ is connected. Moreover, the map $[(g,u)]\mapsto g(su)g^{-1}$ induces an isomorphism
%
\begin{equation} \label{Eq:is}
G\times^{G_{s}} \cU_{G_s}\isom \chi^{-1}(a),
\end{equation}
%
(see, for example, \cite[Ch. II, 3.10, Lemma and Thm]{Slo}).

Therefore it induces an isomorphism
%
\begin{equation} \label{Eq:isom4}
\cL_{n}(G)\times^{\cL_{n}(G_s)}\cL_n(\cU_{G_s})\isom\cL_n(G\times^{G_{s}} \cU_{G_s})\isom\cL_n(\chi^{-1}(a)),
\end{equation}
%
where for the left isomorphism we use \cite[Section~3.1.4(f)]{BKV}. Then
\[
\dim\cL_n(\chi^{-1}(a))=\dim \cL_n(G)-\dim \cL_n(G_s)+\dim\cL_n(\cU_{G_s}),
\]
so the first equality \form{eqdim2} is equivalent to the first equality \form{eqdim} for $G_s$. Since our assumption
of Section~\re{setup}(f) for $G$ implies that $G_s$, the assertion thus follows from \rl{eqdim}.

\smallskip

To show the second equality \form{eqdim2}, it suffices to show that the maps $[(g,u)]\mapsto g(su)g^{-1}$ for $s\in T(k)\cap\chi^{-1}(a)$ induce an isomorphism
%
\begin{equation} \label{Eq:isom3}
\coprod_{s\in T(k)\cap\chi^{-1}(a)}\left(I_n\times^{\cL_{n}(G_{s})\cap I_n}(\cL_n(\C{U}_{G_{s}})\cap I_n)\right)\isom \cL_n(\chi^{-1}(a))\cap I_n.
\end{equation}
%
Indeed, assuming isomorphism \form{isom3}, the second equality \form{eqdim2} is equivalent to the second equality \form{eqdim} for $G_s$
and thus would follow from \rl{eqdim}.

\smallskip

Notice first that the maps $[(g,u)]\mapsto g(su)g^{-1}$ induce an isomorphism
%
\begin{equation} \label{Eq:isom5}
\coprod_{s\in T(k)\cap \chi^{-1}(a)}\left(B\times^{G_{s}\cap B}R_u(G_{s}\cap B)\right)\isom \chi^{-1}(a)\cap B.
\end{equation}
%
Indeed, this follows from the fact that for every $g\in\chi^{-1}(a)\cap B$ its semisimple part $g_s\in B$ is $B$-conjugate to
a unique element $s\in T\cap \chi^{-1}(a)$.

Next, we observe that the diagram
%
\begin{equation} \label{Eq:cd}
\begin{CD}
I_n\times^{\cL_{n}(G_{s})\cap I_n}(\cL_{n}(\C{U}_{G_{s}})\cap I_n) @>>> \cL_n(G)\times^{\cL_n(G_s)}\cL_{n}(\C{U}_{G_{s}})\\
@VVV @VVV\\
B\times^{G_{s}\cap B}R_u(G_{s}\cap B) @>>> G\times^{G_{s}}\C{U}_{G_{s}},
\end{CD}
\end{equation}
%
where the horizontal maps are induced by the embedding $B\hra G$ and vertical maps by the projection $\ev_n:\cL_n(G)\to G$, is Cartesian.

Finally, isomorphism \form{isom3} follows from a combination of isomorphisms \form{is}, \form{isom4} and \form{isom5}, using the Cartesian diagram \form{cd}.
\end{proof}


Now we are ready to prove Theorem~\ref{flat1}.


\begin{proof}[Proof of Theorem~\ref{flat1}]
First we will show the case of $\chi_n$. As the source and the target of $\chi_n$ are smooth and connected, it suffices to prove that all non-empty geometric fibers of $\chi_n$ are equidimensional of constant dimension $\dim\cL_{n}(G)-\dim \cL_n(\kc)$.

Since the function
%
\begin{equation} \label{Eq:dim}
\cL_n(G)\to\B{Z}:g\mapsto \dim_g \chi_n^{-1}(\chi_n(g))
\end{equation}
%
is upper semi-continuous (see \cite[Theorem 13.1.3]{EGAIV} or \cite[Tag~02FZ]{Sta}), it thus suffices to show
that
\begin{equation} \label{Eq:ineq}
\dim_g \chi_n^{-1}(\chi_n(g))\leq\dim\cL_{n}(G)-\dim \cL_n(\kc)
\end{equation}
%
for every $g\in \cL_n(G)(k)$.

Recall that group $\B{G}_m$ acts on $\cL_n(G)$ and $\cL_n(\fc)$ (see Section~\re{looparc}(c)), the morphism
$\chi_n$ is $\B{G}_m$-equivariant, and element $\ov{g}:=\ev_n(g)\in G(k)$ lies in the closure of the $\B{G}_m$-orbit of $g\in\cL_n(G)(k)$.

Thus, by the semi-continuity of function \form{dim} we conclude that
\[
\dim_g \chi_n^{-1}(\chi_n(g))\leq \dim_{\ov{g}} \chi_n^{-1}(\chi_n(\ov{g})).
\]
Therefore it is suffices to show inequality \form{ineq} for $g\in G(k)$.

Finally, since functor $\cL_n$ commutes with limits, we have an identification
\[
\chi_n^{-1}(\chi_n(g))\simeq\chi_n^{-1}(a)\simeq\cL_n(\chi^{-1}(a))\text{ for }a:=\chi(g)\in \fc(k).
\]
Thus, inequality \form{ineq} for $g\in G(k)$ follows from the first equality \form{eqdim2}.

\smallskip

The proof for $v_n$ is similar. First of all, it suffices to show that for every $g\in I_n$
we have inequality
%
\begin{equation} \label{Eq:ineq2}
\dim_g v_n^{-1}(v_n(g))\leq\dim I_n-\dim \cL_n(\kc).
\end{equation}
%
Next, since $I_n\subseteq \cL_n(G)$ is closed and $\B{G}_m$-invariant, repeating the argument for $\chi_n$ we conclude that it suffices 
to show inequality \form{ineq2} for $g\in B(k)$. Finally, using identification
\[
v_n^{-1}(v_n(g))\simeq \cL_n(\chi^{-1}(a))\cap I_n\text{ for }a:=\chi(g)\in \fc(k),
\]
inequality \form{ineq2} follows from the second equality \form{eqdim2}.
\end{proof}

