\subsection{The Goresky--Kottwitz--MacPherson stratification}

\begin{Emp} \label{E:constr}
{\bf Construction} (compare \cite[Sections~3.3.2--3.3.3]{BKV}).

\smallskip

(a) We set $a:=|W|$, $\cO':=k[[t^{\frac{1}{a}}]]$, let $\xi\in k$ be a fixed $a$-th root of unity, and let $\sigma\in\Aut(\cO'/\cO)$ the automorphism given by $t^{\frac{1}{a}}\mapsto\xi t^{\frac{1}{a}}$.  We denote by $T':=\Res_{\cO'/\cO}T$ the Weil restriction of scalars, and
for $w\in W$ we consider the subscheme of fixed points $T_{w}:=\Res_{\cO'/\cO} (T)^{w\sigma}$. Since the characteristic of $k$ is assumed to be prime to $a$ (see Section~\re{setup}(f)), each $T_w$ is a smooth group scheme over $\cO$.

\smallskip

(b) To every pair $(w,\br)$, where $w\in W$ and $\br$ is a function $R\to\frac{1}{a}\B{Z}_{\geq 0}$, one associates the fp-locally closed subscheme $T_{w,\br}\subseteq\clp(T_{w})$ such that
\[
T_{w,\br}=\{t\in\clp(T_{w})~\vert~\val(1-\al(t))=r(\al)\text { for all }\al\in R \}.
\]
Thus, $T_{w,\br}$ is either empty or an open subscheme in some congruence subgroup scheme of $\clp(T_{w})$, in which case $T_{w,\br}$ is connected and strongly pro-smooth.
Moreover, by Sections~\re{admstack}(e) and \re{looparc}(c), scheme $T_{w,\br}$ is admissible. We will call $(w,\br)$ a {\em GKM pair}, if
$T_{w,\br}\neq\emptyset$.

\smallskip

(c) The projection $\pi:T\to\kc$ of affine schemes over $k$ induces a projection $\pi_{w}:T_w\to\kc$ of affine schemes over $\cO$, hence a projection $\pi_{w,\br}:T_{w,\br}\hra\clp(T_w)\to\clp(\fc)$.

\smallskip

(d) In the case $(w,\br)=(1,0)$, we have an equality $T_{w,\br}=\clp (T^{\rs})$.

\smallskip

(e) For every $u\in W$ and a GKM pair $(w,\br)$, the automorphism $u_*$ of $T$ induces an isomorphism $T_{w,\br}\isom  T_{uwu^{-1},u(\br)}$ over $\clp(\fc)$. In particular, we have an action of $W$ on the set of GKM pairs given by the formula $u(w,\br):=(uwu^{-1},u(\br))$, and we denote by $W_{w,\br}\subseteq W$ the stabilizer of $(w,\br)$.
\end{Emp}

\begin{Prop}\label{defwr}

For every GKM pair $(w,\br)$, the schematic image $\kc_{w,\br}$ of $\pi_{w,\br}$ is a connected affine strongly pro-smooth fp-locally closed subscheme of $\clp(\kc)$, and the map $\pi_{w,\br}: T_{w,\br}\to\kc_{w,\br}$ is a $W_{w,\br}$-torsor.
\end{Prop}
\begin{proof}
Since $\pi:T\to\fc$ a finite morphism which is a $W$-torsor over $\kc^{\rs}$ (see Section~\re{setup}(d)), the assertion follows from
\cite[Lemma~3.2.6]{BKV} by the same arguments as in \cite[Section~3.3.4]{BKV}.
\end{proof}

\begin{Emp} \label{E:notcodim}
{\bf Notation.}
%Since $G^{\der}$ was assume to be  simply connected, the Chevalley space $\kc$ is smooth.
As in \cite[Section~3.4.1]{BKV}, for every GKM pair $(w,\br)$, we consider codimensions $a_{w,\br}:=\codim_{\clp (T_{w})}(T_{w,\br})$ and $b_{w,\br}:=\codim_{\clp(\kc)}(\kc_{w,\br})$, denote by $r$ the rank of $G$, and set $d_{\br}:=\sum_{\al\in R} \br(\al)$, $c_{w}:=r-\dim(T^{w})$ and  $\delta_{w,\br}:=\frac{d_{\br}-c_{w}}{2}$.
\end{Emp}

The following result is a group analog of \cite[Corollary~3.4.9(a)]{BKV}:

\begin{Lem}\label{L:codim}
For every GKM pair $(w,\br)$, the fp-locally closed subscheme $I_{w,\br}:=v^{-1}(\kc_{w,\br})\subseteq I$ is of pure codimension $b_{w,\br}$.

%(b) the induced map $v_{w,\br}:I_{w,\br}\to\kc_{w,\br}$ is flat and universally open equidimensional.
\end{Lem}
\begin{proof}
Repeating the argument of \cite[Corollary~3.4.9(a)]{BKV}, the assertion is a formal corollary of the flatness of $v_n$ (Theorem~\ref{flat1}).
\end{proof}



One has the following analog of \cite[Theorem~8.2.2]{GKM}:

\begin{Prop}\label{codim}
For every GKM pair $(w,\br)$, we have an equality $b_{w,\br}=\delta_{w,\br}+a_{w,\br}+c_w$.
\end{Prop}

The proof is based on the following simple result.

\begin{Lem} \label{L:tangent}
(a) Let $X$ be a scheme with placid presentation $X\simeq \lim_{\al}X_{\al}$, and let $\pr_{\al}:X\to X_{\al}$ be projections.
Then for every $x\in X(k)$, the tangent space $T_x(X)$ has a placid (even admissible) presentation $T_x(X)\simeq \lim_{\al}T_{x_{\al}}(X_{\al})$
with $x_{\al}:=\pr_{\al}(x)\in X_{\al}(k)$ for each $\al$.

\smallskip

(b) Let $f:X\to Y$ be an fp-morphism between strongly pro-smooth $k$-schemes. Then for every $x\in X(K)$, the differential $df_x:T_x(X)\to T_y(Y)$ is finitely presented, and we have an equality
\[
\un{\dim}_f(x)=\un{\dim}_{df_x}(0).
\]

\smallskip

(c) Let $f:X\to Y$ be a morphism of smooth schemes over $\C{O}$, let
$x\in X(\C{O})=L^+(X)(k)$ be such that the generic fiber $f_F:X_F\to Y_F$ is \'etale at $x$, let $df_x:T_x(X)\to T_{f(x)}(Y)$ be the differential (an $\C{O}$-linear map of relative tangent spaces), and let $\clp(f):\clp(X)\to\clp(Y)$ be the map between arc spaces.

\smallskip

Then $d(\clp(f))_x:T_x(\clp(X))\to T_{f(x)}(\clp(Y))$ is an fp-closed embedding of pure codimension $\val(\det df_x)$, where $\val(\det df_x)$ denotes the valuation of the determinant of $df_x$.
\end{Lem}

\begin{proof}
(a) The isomorphism  $T_x(X)\simeq \lim_{\al}T_{x_{\al}}(X_{\al})$ follows from the fact that functor of tangent spaces commutes with limits. To finish, we observe that each projection $X_{\beta}\to X_{\al}$ is smooth, hence the differential
$T_{x_{\beta}}(X_{\beta})\to T_{x_{\al}}(X_{\al})$ is surjective, thus smooth.

\smallskip

(b) By assumption, there is a Cartesian diagram
\[
\begin{CD}
X@>f>> Y\\
@Vp_XVV @VVp_YV\\
X' @>f'>> Y'
\end{CD}
\]
such that $X',Y'\in\Schft_k$ are smooth and vertical morphisms are strongly pro-smooth. Since functor of tangent spaces preserves fiber products,
the assertion for $f$ follows from the corresponding assertion for $f'$. Finally, since $X'$ and $Y'$ are smooth over $k$, the assertion for $f'$ follows. 

\smallskip

(c) Assume first that $X=Y=\B{A}^n_{\C{O}}$ and $f$ is an $\C{O}$-linear map. In this case, $f$ is injective and the assertion is easy.
Next, to deduce the general case follows from
the linear case, we observe that $d(\clp(f))_x$ is naturally identified with $\clp(df_x):\clp(T_x(X))\to \clp(T_{f(x)}(Y))$.
\end{proof}

Now we are ready to prove Proposition~\ref{codim}.

\begin{proof}[Proof of Proposition~\ref{codim}]
Let $x\in T_{w,\br}$ and $y:=\pi_{w,\br}(x)\in\fc_{w,\br}$. Then we have a commutative diagram
\[
\xymatrix{T_{x}(T_{w,\br})\ar[r]\ar[d]_{d(\pi_{w,\br})_x}&T_{x}(\clp (T_w))\ar[d]^{d(\pi_{w})_x}\\T_{y}(\kc_{w,r})\ar[r]&T_{y}(\clp(\kc)).}
\]

Since the map $\pi_{w,\br}:T_{w,\br}\to\kc_{w,\br}$ is \'etale (by Proposition~\ref{defwr}), the map $d(\pi_{w,\br})_x$ is an isomorphism (compare the proof of \rl{tangent}(b)). Since the generic fiber $(\pi_w)_F:(T_w)_F\to \fc_F$ is \'etale at $x\in T_w(\cO)$, the map
$d(\pi_w)_x$ is injective of codimension $\val(\det d(\pi_w)_x)$ (by \rl{tangent}(c)). Therefore, by \rl{tangent}(b), we have equalities
%
\[
b_{w,\br}=\codim_{T_{y}(\clp(\kc))}(T_{y}(\kc_{w,r}))=\codim_{T_{y}(\clp(\kc))}(T_{x}(T_{w,r}))=
\]
\[
=\codim_{T_{x}(\clp(T_w))}(T_{x}(T_{w,r}))+\codim_{T_{y}(\clp(\kc))}(T_{x}(\clp(T_w)))=a_{w,\br}+\val(\det d(\pi_w)_x).
\]
%
It thus suffices to show that
\[
\val(\det d(\pi_w)_x)=\delta_{w,\br}+c_w=\frac{d_{\br}+c_w}{2}.
\]
But this follows by the argument of \cite[Lemma~8.2.1]{GKM} except we have to replace the identity \cite[(2.3.1)]{GKM} by its group version \cite[Section~4.23]{H}.
\end{proof}

\begin{Emp}
{\bf Remark.}
Note that our proof of the codimension formula is much shorter than the one of \cite{GKM}, as we already know that the map $\pi_{w,\br}:T_{w,\br}\to\kc_{w,\br}$ is \'etale.% by general techniques used in \cite[Prop. 3.1.11, Lem. 3.2.6]{BKV}.
\end{Emp}

\begin{Cor}\label{cor-codim}
For every GKM pair $(w,\br)$, we have an inequality $b_{w,\br}\geq\delta_{w,\br}$. Moreover, equality holds if and only if $w=1$ and $\br=0$.
\end{Cor}
\begin{proof}
Since $a_{w,\br}, c_w\geq 0$, the inequality $b_{w,\br}\geq\dt_{w,\br}$ follows from Proposition~\ref{codim}.
Moreover, equality holds if and only if $c_w = a_{w,\br} = 0$. Furthermore, this happens if and only if
$w = 1$ and $T_{w,\br}=T_{\br}\subseteq \clp(T)$ is open. Finally, $T_{\br}\subseteq \clp(T)$ is open if and only if $\br=0$.
\end{proof}

\subsection{The affine Grothendieck-Springer fibration}
\begin{Emp} \label{E:fibr}
%Let $G$ be a connected split reductive group with $G_{der}$ simply connected over $k$, $(B,T)$ a Borel pair, $I=\ev^{-1}(B)\subseteq \clp G$ the corresponding Iwahori subgroup.
{\bf The fibration} (compare \cite[Sections~4.1.1--4.1.3]{BKV}).

\smallskip

(a) Let $\Fl:=\cL G/ I$ be the affine flag variety, and set
\[
\wt{\fC}:=\{([g],\g)\in\Fl\times\cL G~\vert~g^{-1}\g g\in I\}.
\]%=\{([g],\g)\in\Fl\times\cL G~\vert~\g ([g])=[g]\}.\]
By functoriality, the Chevalley morphism $\chi:G\to\kc$ induces a map $\cL\chi:\cL G\to\cL\kc$,
and we set $\kC:=(\cL\chi)^{-1}(\clp(\kc))\subseteq \cL G$. The second projection $\Fl\times\cL G\to\cL G$ induces a projection
$\frak{p}:\wt{\fC}\to\kC$.

\smallskip

(b) Note that $\wt{\fC}$ is the inverse image of the fp-closed substack $[I/I]\subseteq[\cL G/I]$ by the map
\[\Ad:\Fl\times \cL G\to[\cL G/I]:([g],\g)\mapsto [g^{-1}\g g],\]
where $I$ acts on the right hand side by conjugation. Therefore  $\wt{\fC}$ is an fp-closed ind-subscheme of $\Fl\times\cL G$.
Moreover, since $\Fl$ is an ind-fp-proper ind-scheme over $k$, the map $\frak{p}$ is ind-fp-proper (compare \cite[Lemma~4.1.4]{BKV}).

\smallskip

(c) The group ind-scheme $\cL G$ acts on  $\wt{\fC}$ by the rule
\[h([g],\g)=([hg],h\g h^{-1})\] and the map $\Ad$ from part~(b) induces an isomorphism of $\infty$-stacks $[\wt{\fC}/\cL G]\isom [I/I]$. Moreover, the map $\frak{p}$ is $\cL G$-equivariant and hence induces a map between quotient stacks
\begin{equation}
\ov{\frak{p}}:[\wt{\fC}/\cL G]\to[\kC/\cL G],
\label{equiv-prop}
\end{equation}
which is also ind-fp-proper (by part~(b) and \cite[Section~1.2.9(b)]{BKV}).

\smallskip

(d) The projection $\pr:I\to T$ induces a morphism $[\wt{\fC}/\cL G]\isom [I/I]\to T$, which we also denote by $\pr$. Explicitly,
$\pr$ send a class $[([g],\g)]$ to the class of $g^{-1}\g g\in I$.
\end{Emp}


\begin{Emp} \label{E:open}
{\bf The constructible stratification} (compare \cite[Section~4.1.7]{BKV}).

\smallskip

(a) Let $Z(\kD)\subseteq\fc$ be the locus of zeros of $\kD\in k[\fc]$, and set $\clp(\kc)_{\bullet}:=\clp(\kc)\sm\clp(Z(\kD))$. It is a non-quasi-compact open subscheme of $\clp(\kc)$, which has an open increasing covering \[\clp(\kc)_{\bullet}=\bigcup_{m\in\NN}\kc_{\leq m},\]
where $\kc_{\leq m}:=\{a\in\clp(\kc)~\vert~\val(\kD(a))\leq m\}$.

\smallskip

(b) We set $\kC_{\bullet}:=(\cL\chi)^{-1}(\kc_{\bullet})\subseteq\kC$, $\kC_{\leq m}:=(\cL\chi)^{-1}(\kc_{\leq m})\subseteq \kC_{\bullet}$, and $\wt{\fC}_{\bullet}=\frak{p}^{-1}(\kC_{\bullet})$. We can then write $\wt{\fC}_{\bullet}$ as an increasing union of open ind-schemes:
\begin{equation}
\kC_{\bullet}=\bigcup_{m\in\NN}\kC_{\leq m}.
\label{colimC}
\end{equation}
Then each $\kC_{\leq m}$ is an ind-placid ind-scheme, being an fp-locally closed sub-indscheme of an ind-placid ind-scheme $\cL G$.

\smallskip

(c) For every GKM pair $(w,\br)$, we set $\kC_{w,\br}:=\chi^{-1}(\kc_{w,\br})\subseteq\kC_{\bullet}$ and $\wt{\fC}_{w,\br}:=\frak{p}^{-1}(\kC_{w,\br})\subseteq\wt{\fC}_{\bullet}$. As in the Lie algebra case,
$\{\kc_{w,\br}\}_{w,\br}$ forms a bounded constructible stratification of $\cL(\kc)_{\bullet}$
and induces a bounded constructible stratification $\{[\fC_{w,\br}/\cL G]_{\red}\}_{w,\br}$ of $[\fC_{\bullet}/\cL G]$.

\smallskip

(d) The projection $\ov{\frak{p}}$ from Section~\re{fibr}(c) induces projections $\ov{\frak{p}}_{\bullet}:[\wt{\fC}_{\bullet}/\cL G]\to [{\fC}_{\bullet}/\cL G]$ and
$\ov{\frak{p}}_{w,\br}:[\wt{\fC}_{w,\br}/\cL G]_{\red}\to [{\fC}_{w,\br}/\cL G]_{\red}$.
\end{Emp}


\begin{Emp} \label{E:affsprfib}
{\bf Affine Springer fibers.}

\smallskip

(a) For every $\g\in\kC_{\bullet}(k)\subseteq G^{\rs}(F)$, the closed ind-subscheme
\[
\Fl_{\g}=\{[g]\in\Fl~\vert~g^{-1}\g g\in I\},%=\{[g]\in\Fl~\vert~\g([g])=[g]\},
\]
is the preimage of $\frak{p}^{-1}(\g)$ and is usually called the {\em affine Springer fiber} of $\g$. 
By Section~\re{fibr}(b), $\Fl_{\g}$ is an ind-fp-proper ind-scheme over $k$.

\smallskip

(b) As in the Lie algebra case, the reduced ind-scheme $(\Fl_{\g})_{\red}$ is a finite-dimensional scheme, locally of finite type over $k$. Moreover, if $\g\in\kC_{w,\br}(k)$, then, in the notation of
Section~\re{notcodim}, we have an equality $\dim(\Fl_{\g})_{\red}=\delta_{w,\br}$.

