\begin{Thm} \label{small}
The projection $\ov{\frak{p}}_{\bullet}:[\wt{\fC}_{\bullet}/\cL G]\to[\kC_{\bullet}/\cL G]$ is $[\kC_{\leq 0}/\cL G]$-small (see Section~\re{small}).
\end{Thm}
\begin{proof}
Note that $([\kC_{\bullet}/\cL G],\{[\kC_{w,\br}/\cL G]_{\red}\}_{w,\br})$ is a placidly stratified $\infty$-stack (by
Sections~\re{open}(c) and \re{stratum}(a)), and that $[\wt{\fC}_{\bullet}/\cL G]\simeq[I_{\bullet}/I]$ is a placid $\infty$-stack
(by Section~\re{fibr}(c) and \re{basic example}(a)).

\smallskip

Moreover, each $[\wt{\fC}_{w,\br}/\cL G]\simeq [I_{w,\br}/I]$ is an fp-locally closed substack of $[\wt{\fC}_{\bullet}/\cL G]\simeq[I_{\bullet}/I]$ of pure codimension $b_{w,\br}$ (by \rl{codim} and Section~\re{dimfn}(b)(ii)), each $\ov{\frak{p}}_{w,\br}$ is locally fp-representable and equidimensional of relative dimension $\delta_{w,\br}$
(by \rp{topproper}(b) and Section~\re{eqdim}(b)). Finally, inequalities of Section~\re{small}(c)(iii) follow from Corollary~\ref{cor-codim}.
\end{proof}


\begin{Emp} \label{E:regstratum}
{\bf Fibration over a regular stratum.}

\smallskip

(a) Arguing as in \cite[Corollaries~4.2.2--4.2.3]{BKV}, we have a commutative diagram
%
\[
\begin{CD}
[\clp(T^{\rs})/\clp(T)] @>\sim>> [\wt{\fC}_{\leq 0}/\cL G] \\
 @VVV @VV\ov{\frak{p}}_{\leq 0}V\\
[\clp(T^{\rs})/W\ltimes\cL(T)_{\red}] @>\sim>> [\fC_{\leq 0}/\cL G]_{\red},
\end{CD}
\]
%
where the top isomorphism is the isomorphism $[\psi_{w,\br}]$ of Section~\re{stratum}(a) for $(w,\br)=(1,0)$.

\smallskip

(b) Using isomorphism $\cL(T)_{\red}\simeq \clp(T)\times\La$ (see \cite[Section~4.1.11]{BKV}), we conclude from the commutative diagram of part~(a),
that the projection $\ov{\frak{p}}_{\leq 0}:[\wt{\fC}_{\leq 0}/\cL G]\to [\fC_{\leq 0}/\cL G]_{\red}$ is a $\wt{W}$-torsor.

\smallskip

(c) Notice that the composition
\[
[\clp(T^{\rs})/\clp(T)]\isom [\wt{\fC}_{\leq 0}/\cL G]\overset{\pr}{\lra}T
\]
sends $[t]\mapsto\ev(t)$. In particular, it is $\wt{W}$-equivariant with respect to the natural action of $W$ and the trivial action of $\La$ on both sides.
