\begin{Emp}
{\bf Observations} (compare \cite[Sections~7.1.1--7.1.3]{BKV}).

\smallskip

(a) Recall the projection $\ov{\frak{p}}:[\wt{\fC}/\cL G]\to[\kC/\cL G]$
is ind-fp-proper (see Section~\re{fibr}(c)), so the pullback $\ov{\frak{p}}^{!}$ admits a left adjoint $\ov{\frak{p}}_!$ that satisfies base change (by \cite[Proposition~5.3.7]{BKV}).

\smallskip

(b) Using observations of Section~\re{open}(b) and arguing as in \cite[Lemma~7.1.2]{BKV}, one obtains that
the $\infty$-stack $[\kC_{\bullet}/\cL G]$ admits gluing of sheaves.

\smallskip

(c) By Theorem~\ref{small}, the stratified $\infty$-stack $([\fC_{\bullet}/\cL G],\{[\fC_{w,\br}/\cL G]_{\red}\}_{w,\br})$ is placidly stratified, and the projection $\ov{\frak{p}}_{\bullet}:[\wt{\fC}_{\bullet}/\cL G]\to[\kC_{\bullet}/\cL G]$ is $[\kC_{\leq 0}/\cL G]$-small.
Therefore morphism $\ov{\frak{p}}_{\bullet}$ gives rise to a perversity $p_{\nu}=\{\nu_{w,\br}\}_{w,\br}$,
defined by $\nu_{w,\br}:=\dt_{w,\br}+b_{w,\br}$  (see Sections~\re{pervfun}(b) and \re{notcodim}).

\smallskip

(d) By parts~(b),(c) and Section~\re{pervplstr}(b), the $\infty$-category $\cD([\fC_{\bullet}/\cL G])$ is equipped with
 a canonical $t$-structure, corresponding to the perversity $p_{\nu}$.
\end{Emp}

\begin{Thm} \label{T:perv}
For every $!$-local system $K\in\Loc^{!}([\wt{\fC}_{\bullet}/\cL G])$, the push-forward $(\ov{\frak{p}}_{\bullet})_!(K)$ is $p_{\nu}$-perverse. Moreover, it is the intermediate extension of its restriction to $[\kC_{\leq 0}/\cL G]$.
\end{Thm}
\begin{proof}
Since projection $\ov{\frak{p}}_{\bullet}$ is $[\kC_{\leq 0}/\cL G]$-small (by Theorem~\ref{small}), the assertion follows from
Theorem~\ref{g-small}.
\end{proof}

\begin{Emp} \label{E:gsp}
{\bf Basic example.}

\smallskip

(a) Let $\pr:[\wt{\fC}/\cL G]\to T$ be the projection (see Section~\re{fibr}(d)). Then a local system $\cL$ on $T$ gives rise to the $!$-local system $\om_{\cL}$ on $[\wt{\fC}/\cL G]$ (see Section~\re{!ls}(b)), hence to the object  $\cS_{\cL}:=\ov{\frak{p}}_!(\om_{\cL})\in\cD([\kC/\cL G])$, called the {\em affine Grothendieck--Springer sheaf}.

\smallskip

(b) Let $\cS_{\cL,\bullet}$ be the restrictions of $\cS_{\cL}$ to the open substack $[\kC_{\bullet}/\cL G]$. Since $\ov{\frak{p}}_!$ satisfies base change, we have an identification $\cS_{\cL,\bullet}\simeq (\ov{\frak{p}}_{\bullet})_!(\om_{\cL})\in\cD([\kC_{\bullet}/\cL G])$. Thus, by \rt{perv}, the sheaf $\cS_{\cL,\bullet}$ is $p_{\nu}$-perverse and is the intermediate extension of its restriction $\cS_{\cL,\leq 0}\in\cD([\kC_{\leq 0}/\cL G])$.

\smallskip

(c) For every $\g\in \kC_{\bullet}(k)$, we denote by $\iota_{\g}$ the corresponding morphism $\pt\to [\kC_{\bullet}/\cL G]$.
Then, by base change, we have an isomorphism
%
\begin{equation} \label{Eq:rgmc}
\iota_{\g}^!(\cS_{\cL,\bullet})\simeq R\Gm_c(\Fl_{\g},\om_{\cL}).
\end{equation}
%
\end{Emp}
%\subsection{Action of the affine Weyl group}

\begin{Cor} \label{C:action}
(a) For a local system $\cL$ on $T$, we have natural isomorphisms 
\[
a_{w,\cL}:\cS_{\cL,\bullet}\isom \cS_{w_!(\cL)\bullet}\text{ for } w\in \wt{W},\text{ satisfying }a_{w_1,(w_2)_!(\cL)}\circ a_{w_2,\cL}\simeq a_{w_1w_2,\cL}\text{ for }w_1,w_2\in\wt{W}.
\]

\smallskip

(b) The affine Grothendieck--Springer sheaf $\cS_{\cL,\bullet}\in\cD([\kC_{\bullet}/\cL G])$ is equipped with a natural $\La$-action, that is,   has a natural lift to $\cD^{\La}([\kC_{\bullet}/\cL G])$. Furthermore, $\cS_{\cL,\bullet}$ has a natural lift to $\cD^{\wt{W}}([\kC_{\bullet}/\cL G])$,
if $\cL$ is $W$-equivariant.
\end{Cor}

\begin{proof}
(a) Since $\cS_{\cL,\bullet}$ is the intermediate extension of $\cS_{\cL,\leq 0}$ (see Section~\re{gsp}(b)), for every $w\in\wt{W}$ the restriction map
\[
\Hom(\cS_{\cL,\bullet},\cS_{w_!(\cL),\bullet})\to \Hom(\cS_{\cL,\leq 0},\cS_{w_!(\cL),\leq 0})
\]
is an isomorphism. Thus, it remains to construct a collection of isomorphisms
\[
a_{w,\cL}:\cS_{\cL,\leq 0}\isom \cS_{w_!(\cL),\leq 0},\text{ satisfying  }a_{w_1,(w_2)_!(\cL)}\circ a_{w_2,\cL}\simeq a_{w_1w_2,\cL}.
\]

By the base change, we have an isomorphism  $\cS_{\cL,\leq 0}\simeq (\ov{\frak{p}}_{\leq 0})_!(\om_{\cL})$.
Recall that the projection $\ov{\frak{p}}_{\leq 0}:[\wt{\kC}_{\leq 0}/\cL G]\to [\kC_{\leq 0}/\cL G]_{\red}$ is a $\wt{W}$-torsor, and the projection $\pr:[\wt{\kC}_{\bullet}/\cL G]\to T$ is $\wt{W}$-equivariant (see Section~\re{regstratum}(b),(c)).  Since $\om_{\cL}=\pr^!(\om_T\otimes \cL)\in \cD([\wt{\kC}_{\leq 0}/\cL G])$,
for every $w\in\wt{W}$ we have an isomorphism $w_!(\om_{\cL})\simeq \om_{w_!(\cL)}$, hence an isomorphism
\[
a_{w,\cL}: \cS_{\cL,\leq 0}\simeq (\ov{\frak{p}}_{\leq 0})_!(\om_{\cL})\simeq (\ov{\frak{p}}_{\leq 0}\circ w)_!(\om_{\cL})\simeq
(\ov{\frak{p}}_{\leq 0})_!w_!(\om_{\cL})\simeq (\ov{\frak{p}}_{\leq 0})_!(\om_{w_!(\cL)})\simeq \cS_{w_!(\cL),\leq 0}.
\]
Moreover, the identity $a_{w_1,(w_2)_!(\cL)}\circ a_{w_2,\cL}\simeq a_{w_1w_2,\cL}$ is straightforward.

\smallskip

(b) Since perverse sheaves have no negative Exts, it follows for example from  \cite[Remark~1.2.1.12]{Lu2} that the $\infty$-category
$\Perv^{p_{\nu}}([\kC_{\bullet}/\cL G])$ of $p_{\nu}$-perverse sheaves is equivalent to its homotopy category. Since each $\cS_{\cL,\bullet}$ is $p_{\nu}$-perverse, it thus enough to construct the action at the level of homotopy categories. So both assertions follows from part~(a).
\end{proof}

\begin{Cor}\label{C:action2}
Fix $\g\in\fC_{\bullet}(k)$. For a local system (resp. $W$-equivariant local system) $\cL$ on $T$,

\smallskip

(a) the complex $R\Gm_c(\Fl_{\g},\omega_{\cL})$ is equipped with an action of $\La\times\cL G_{\g}$ (resp. $\wt{W}\times\cL G_{\g}$);

\smallskip

(b) for every $i\in\B{Z}$, the cohomology group  $H^i_c(\Fl_{\g},\omega_{\cL})$ is equipped with an action of
$\La\times\pi_0(\cL G_{\g})$ (resp. $\wt{W}\times\pi_0(\cL G_{\g})$). 
\end{Cor}

\begin{proof}
(a) Notice that the morphism $\iota_{\g}:\pt\to [\kC_{\bullet}/\cL G]$ from Section~\re{gsp}(c) factors through $[\pt/\cL G_{\g}]$.
Therefore the pullback $\iota_{\g}^!(\cS_{\cL,\bullet})\in \cD^{\La}(\pt)$ of $\cS_{\cL,\bullet}\in\cD^{\La}([\kC_{\bullet}/\cL G])$ has a natural lift to an object of $\cD^{\La}([\pt/\cL G_{\g}])=\cD^{\La\times\cL G_{\g}}(\pt)$. From this the assertion follows using isomorphism \form{rgmc}. The assertion for $W$-equivariant local systems is similar.

\smallskip

(b) By part~(a), for every $i\in\B{Z}$, the cohomology group  $H^i_c(\Fl_{\g},\omega_{\cL})$ is equipped with an action of
$\La\times\cL G_{\g}$ (resp. $\wt{W}\times\cL G_{\g}$). Now the assertion follows from the fact that the $\cL G_{\g}$-action on each $H^i_c(\Fl_{\g},\omega_{\cL})$ factors through
$\pi_0(\cL G_{\g})$.
\end{proof}

\begin{Emp}\label{E:hom}
{\bf Remark.} By the Poincar\'e duality, the cohomology group $H^i_c(\Fl_{\g},\omega_{\cL})$ coincides with the homology group $H_{-i}(\Fl_{\g},\C{F}_{\cL})$ considered in \cite{BV}. Thus, by \cite[Corollary~2.2.8]{BV}, we have an a priori different Lusztig action
of  $\La$ (resp. $\wt{W}$) on each $H^i_c(\Fl_{\g},\omega_{\cL})$.
\end{Emp}

\begin{Prop} \label{P:compat}
For every $\g\in\fC_{\bullet}(k)$ and $i\in\B{Z}$, the action of $\La$ (resp. $\wt{W}$) on $H^i_c(\Fl_{\g},\omega_{\cL})$ from \rco{action2}
coincides with the action from \cite[Corollary~2.2.8]{BV}.
\end{Prop}

\begin{proof}
By the construction of the actions in \rco{action2} and \cite[Corollary~2.2.8]{BV}, it suffices to show that for every $w\in\wt{W}$,
the isomorphism
%
\begin{equation} \label{Eq:isom}
a_{w,\cL}:H^i_c(\Fl_{\g},\omega_{\cL})\isom H^i_c(\Fl_{\g},\omega_{w_!(\cL)}),
\end{equation}
%
induced by the isomorphism
$a_{w,\cL}$ of \rco{action}, coincides with the isomorphism of \cite[Proposition~2.2.7(c)]{BV}.

\smallskip

Recall that the affine Weyl group $\wt{W}$ is generated by a set $\wt{S}\subseteq\wt{W}$ of simple affine reflections and a finite abelian group
$\Omega:=N_{\cL G}(I)/I$ (compare \cite[Section~2.1.2(d)]{BV}). Thus, it suffices to show the equality of isomorphisms $a_{w,\cL}$ for  $w\in\Omega$ and $w\in\wt{S}$.

\smallskip

To show the assertion for $w\in\Omega=N_{\cL G}(I)/I$, note that $w$ induces an automorphism $w_*$ of
$[\wt{\fC}/\cL G]\simeq [I/I]$ over $[\fC/\cL G]$ and in both cases the isomorphism $a_{w,\cL}$ of \form{isom} is induced by $w_*$.

\smallskip

To show the assertion for $w=s\in\wt{S}$, consider diagram of adjoint quotients
\[
\begin{CD}
[I/I] @>\pr^s>> [B_s/B_s] @>\pr_s>> T\\
@V\ov{\frak{p}}_s VV @V p_s VV\\
[P_s/P_s] @>\ov{\pr}^s>> [L_s/L_s]\\
@V\ov{\frak{p}}^s VV\\
[\fC/\cL G],
\end{CD}
\]
where $P_s\supsetneq I$ is the minimal standard parahoric of $\cL G$, corresponding to $s$, $P_s^+\subseteq P_s$ is the pro-unipotent radical of $P_s$, $L_s:=P_s/P^+_s$ is the corresponding ``Levi subgroup'', $B_s:=I/P_s^+\subseteq L_s$ is the Borel subgroup of $L_s$, and
all the maps are natural projections. 

\smallskip

Set $\cS^{\on{fin}}_{\cL}:=(p_s)_{!}\pr_s^!(\om_{T,\C{L}})\in\cD([L_s/L_s])$. Then, by the usual (finite-dimensional) Springer theory (see, for example, \cite[Section~1.2.1.(e)]{BV}),
we have a natural isomorphism
\[
a^{\on{fin}}_{s,\cL}: \cS^{\on{fin}}_{\cL}\isom\cS^{\on{fin}}_{s_!(\cL)}.
\]

On the other hand, by the proper base change, we have a natural identification
\[
\cS_{\cL}\simeq (\ov{\frak{p}}^s)_!(\ov{\frak{p}}_s)_!(\pr^s)^!\pr_s^!(\om_{T,\C{L}})\simeq
(\ov{\frak{p}}^s)_!(\ov{\pr}^s)^!(p_s)_{!}\pr_s^!(\om_{T,\C{L}})=(\ov{\frak{p}}^s)_!(\ov{\pr}^s)^!(\cS^{\on{fin}}_{\cL}).
\]
So isomorphism $a^{\on{fin}}_{s,\cL}$ induces an isomorphism
%
\begin{equation*} \label{Eq:awl}
a^{\on{Lu}}_{s,\cL}: \cS_{\cL}\isom\cS_{s_!(\cL)},
\end{equation*}
%
where ``$\on{Lu}$'' stands for Lusztig, and by definition the isomorphism \form{isom} of \cite[Proposition~2.2.7(c)]{BV} is induced by isomorphism $a^{\on{Lu}}_{s,\cL}$.

\smallskip

It remains to check that the restriction of the isomorphism $a^{\on{Lu}}_{s,\cL}$ to $[\fC_{\bullet}/\cL G]$ coincides with the isomorphism
of $a_{s,\cL}$ of \rco{action}. By construction, it suffices to show that the restriction of the isomorphism
$a^{\on{Lu}}_{s,\cL}$ to $[\fC_{\leq 0}/\cL G]$ is induced by the geometric action of $s\in \wt{W}$ on $[\wt{\fC}_{\leq 0}/\cL G]$. But this follows from the fact that the usual Springer action $a^{\on{fin}}_{s,\cL}$ is induced by the geometric action on the regular semisimple locus.
\end{proof}


\begin{Emp}
{\bf Remarks.} The following observations are not used in this work:

\smallskip

(a) Arguing as in \cite[Proposition~2.2.7]{BV} or \cite[Section~3.3]{B} (using presentation of $\wt{W}$ by generators and relations), one can show that a small modification of the argument of \rp{compat} provides a Lusztig action of $\La$ (resp. $\wt{W}$) on $\cS_{\cL}$ on the level of homotopy categories. In particular, using the perversity of $\cS_{\cL,\bullet}$ and observation of \cite[Remark~1.2.1.12]{Lu2} again, one can deduce that the induced action on $\cS_{\cL,\bullet}$ lifts uniquely to the action on the level of $\infty$-categories. Moreover, the resulting action of $\La$ (resp. $\wt{W}$) on  $\cS_{\cL,\bullet}$ coincides  with the one of \rco{action}.

\smallskip

(b) Furthermore, using perversity of finite-dimensional Springer sheaves, one can show that the Lusztig action of $\La$ (resp. $\wt{W}$) on $\cS_{\cL}$ on the level of homotopy categories discussed in part~(a) can be lifted to the action on the level of $\infty$-categories (see \cite{BeKV2}). Furthermore, this lift can be shown to be unique.
\end{Emp}

