\subsection{Perversity of $\tau$-coinvariants}

%In this paragraph we simultaneously treat the group case and the Lie algebra case of \cite{BKV}.

Now we are ready to prove the main result of this work.

\begin{Thm}\label{T:perv-tau}
For every local system on $\cL$ on $T$ and representation $\tau\in\on{Rep}_{\bql}(\La)$, the sheaf of $\tau$-coinvariants $\cS_{\cL,\bullet,\tau}=\on{coinv}_{\tau}(\cS_{\cL,\bullet})\in\cD([\kC_{\bullet}/\cL G])$ is $p_{\nu}$-perverse.
\end{Thm}

\begin{Emp}
{\bf Remark.}
Unlike $\cS_{\cL,\bullet}$, it is not true that $\cS_{\cL,\bullet,\tau}$ is the intermediate extension of its restriction to
$[\kC_{\leq 0}/\cL G]$. Also $\cS_{\cL,\bullet,\tau}$ is not necessary irreducible, even if $\tau$ and $\C{L}$ are irreducible.
\end{Emp}

\begin{proof}
%We treat simultaneously both cases, but consider the group case as the main case. We explain the needed modifications in the Lie algebra case.
As $\cS_{\cL,\bullet}$ is $p_{\nu}$-perverse (by \rt{perv}), and the functor of $\tau$-coinvariants is right $t$-exact (by Lemma~\ref{r-tex}), we only have to prove that $\cS_{\cL,\bullet,\tau}\in \mathstrut^{p_{\nu}}\cD^{\geq 0}([\kC_{\bullet}/\cL G])$. By definition, we have to check that for every GKM pair $(w,\br)$, we have
\begin{equation*}
\eta_{w,\br}^{!}(\cS_{\C{L},\bullet,\tau})\in \mathstrut^{p}\cD^{\geq -\nu_{w,\br}}([\kC_{w,\br}/\cL G]_{\red}).
\label{res-tau}
\end{equation*}

Next, using identity $\nu_{w,\br}=\dt_{w,\br}+b_{w,\br}=2\dt_{w,\br}+c_w+a_{w,\br}=d_{\br}+a_{w,\br}$ (by Proposition~\ref{codim}),
it thus suffices to check that for every GKM pair $(w,\br)$, we have
\begin{equation*}
\eta_{w,\br}^{!}(\cS_{\C{L},\bullet,\tau})\in \mathstrut^{p}\cD^{\geq -d_{\br}}([\kC_{w,\br}/\cL G]_{\red}).
%\label{res-tau}
\end{equation*}

Since $\cS_{\cL,\bullet,\tau}$ is essentially constructible (by \rco{ess-cons}), the pullback $\eta_{w,\br}^{!}(\cS_{\C{L},\bullet,\tau})$ is essentially constructible (by Section~\re{esscons}(c)). Using the fact that the $\infty$-stack $[\kC_{w,\br}/\cL G]_{\red}$ is admissible (see Section~\re{stratum}(a)), it follows from Proposition~\ref{pullcheck}
that it suffices to show that for every $\g\in \kC_{w,r}(k)$, one has an inclusion
%
\begin{equation} \label{Eq:res-tau}
\iota_{\g}^{!}(\cS_{\C{L},\bullet,\tau})\in \cD^{\geq -d_{\br}}(\pt).
\end{equation}
%
Combining isomorphism $\iota_{\g}^{!}(\cS_{\C{L},\bullet})\simeq R\Gm_c(\Fl_{\g},\omega_{\cL})$ (see Section~\re{gsp}(c)) with observations of Sections~\re{isot}(c),(d), we get an isomorphism
\[
\iota_{\g}^{!}(\cS_{\C{L},\bullet,\tau})\simeq (\iota_{\g}^{!}(\cS_{\C{L},\bullet}))_{\tau}\simeq R\Gm_c(\Fl_{\g},\omega_{\cL})_{\tau}\simeq \tau\otimes^{L}_{\bql[\La]} R\Gm_c(\Fl_{\g},\omega_{\cL}),
\]
where $\tau$ is the right $\qlbar[\La]$-module, corresponding to $\tau\in\on{Rep}_{\bql}(\La)$ (see Section~\re{isot}(d)). Now inclusion \form{res-tau} follows from Proposition~\ref{p-tau2} below.
%Finally if $\tau$ is finite dimensional, then by \ref{L-cstr} and \eqref{coinv-cc}, we  know that $(\cS_{\cL,\bullet})_{\tau}$ is constructible (\cite[Thm. 4.3.15]{B} for the Lie algebra case).
\end{proof}

%\begin{Rem}
%The Lie algebra statement was proved conditionnally in \cite[Thm.5.3.1]{B} using a stronger form of Yun's theorem.
%\end{Rem}

%Let us formulate the following proposition that we prove in \ref{app} from which we deduce the theorem:
\begin{Prop}\label{p-tau2}
For every $\g\in\kC_{w,\br}(k)$ and every representation $\tau\in\on{Rep}_{\bql}(\La)$, we have
\[\tau\otimes^{L}_{\bql[\La]}R\Gm_c(\Fl_{\g},\omega_{\cL})\in\cD^{\geq -d_{\br}}.\]
\end{Prop}

\begin{proof}
Set $V:=R\Gm_c(\Fl_{\g},\omega_{\cL})$ and we want to show that $\tau\otimes^{L}_{\bql[\La]}V\in\cD^{\geq -d_{\br}}$.
To make the proof more structural, we will divide it into steps:

\smallskip

{\bf Step 1.} Note that $\La_{\g}:=\Hom_F(\B{G}_m,G_{\g})$ is naturally a subgroup of $\cL G_{\g}$ via the map $\la\mapsto \la(t)$.
By \rco{action2}(a), $V$ is equipped with an action of $\La\times \cL G_{\g}$, therefore with an action of
$\La\times \La_{\g}$. We claim that for every $\nu\in\on{Rep}_{\qlbar}(\La_{\g})$, we have
\[
\nu\otimes^{L}_{\bql[\La_{\g}]}V\in\cD^{\geq -2\dt_{w,\br}}.
\]

\begin{proof}
Consider projection $p:\Fl_{\g}\to Y:=[\Fl_{\g}/\La_{\g}]$, and let $\pr_{\g}:\Fl_{\g}\to T$ be the restriction of $\pr:[\wt{\fC}/\cL G]\to T$ (see Section~\re{fibr}(d)). As in Section~\re{stratum}(c), the projection $\pr_{\g}$ factors through
$p:\Fl_{\g}\to Y$. Thus, $V\simeq R\Gm_c(Y,p_!p^!\omega_{\cL})$, where we write $\omega_{\cL}$ instead of $\omega_{Y,\cL}$ (see Section~\re{!ls}(b)). Moreover, the $\La_{\g}$-action on $V$ comes from the $\La_{\g}$-action on $p_!p^!\omega_{\cL}$ (compare \rl{taucoinv}(a)).

\smallskip

Then, using Sections~\re{isot}(c),(d) and \rl{taucoinv}(b), we have an identification

\[
\nu\otimes^{L}_{\bql[\La]}V\simeq \coinv_{\nu}(V)\simeq\coinv_{\nu} (R\Gm_c(Y,p_!p^!\omega_{\cL}))\simeq
\]
\[
\simeq R\Gm_c(Y,\coinv_{\nu}(p_!p^!\omega_{\cL})))\simeq  R\Gm_c(Y,A_{\nu}\overset{!}{\otimes} \omega_{\cL}).
\]

Using Sections~\re{!ls}(b),(c) we conclude that $A_{\nu}\overset{!}{\otimes} \omega_{\cL}$ is a $!$-local system on $Y$, hence it lies in $\cD^{\geq -2\dim Y}(Y)$ with respect to the usual (rather than perverse) $t$-structure.
%
%because $\om_Y\in \cD^{\geq -2\dim Y}(Y)$ and $\ov{\red}_{g}^*(\C{L})\otimes\pi^*(\nu')$ is a local system.
Therefore we have
\[
\nu\otimes^{L}_{\bql[\La]}V\simeq  R\Gm_c(Y,A_{\nu}\overset{!}{\otimes}\omega_{\cL})\in D^{\geq -2\dim Y},
\]
so our assertion follows from the equality $\dim Y=\dim\Fl_{\g}=\dt_{w,\br}$.
\end{proof}


\smallskip

{\bf Step 2.} As in \cite[Section~2.3.1]{BV}, we have a canonical isomorphism $\pi_{0}(\cL G_{\g})\simeq X_*(G_{\g})_{\Gm_{F}}$, where we set
$X_*(G_{\g}):=\Hom_{\ov{F}}(\gm,G_{\g})$. Moreover the composition $\La_{\g}\hra \cL G_{\g}\to\pi_0(\cL G_{\g})$ 
can be rewritten as
\[
\La_{\g}=X_*(G_{\g})^{\Gm_{F}}\hra X_*(G_{\g})\to X_*(G_{\g})_{\Gm_{F}}\simeq\pi_0(\cL G_{\g}).
\]
In particular, the homomorphism $\La_{\g}\to\wt{\La}_{\g}:=\pi_0(\cL G_{\g})$ is injective, and the quotient $\ov{\La}_{\g}:=\wt{\La}_{\g}/\La_{\g}$ is finite.

\smallskip

Consider induced representation  $\wt{V}:=\on{ind}_{\La_{\g}}^{\wt{\La}_{\g}}(V)$ of $\La\times \wt{\La}_{\g}$. Then, by Step 1, for every representation  $\wt{\nu}\in\on{Rep}_{\qlbar}(\wt{\La}_{\g})$, we have
\[
\wt{\nu}\otimes^{L}_{\bql[\wt{\La}_{\g}]}\wt{V}\simeq (\wt{\nu}|_{\La_{\g}})\otimes^{L}_{\bql[\La_{\g}]}V\in \cD^{\geq -2\dt_{w,\br}},
\]
where $\wt{\nu}|_{\La_{\g}}$ denotes the restriction of $\nu$, and we want to show that
\[
\tau\otimes^{L}_{\bql[\La]}\wt{V}\simeq (\tau\otimes^{L}_{\bql[\La]}V)^{\oplus|\ov{\La}_{\g}|}\in \cD^{\geq -d_{\br}}.
\]

\smallskip

{\bf Step 3.} Next we are going to rephrase the assertion of Step 2 geometrically:

\smallskip

Set $X:=\Spec(\bql[\wt{\La}_{\g}])$ and $Y:=\Spec(\bql[\La])$. Then $X$ and $Y$ are connected affine algebraic groups (hence connected
smooth affine schemes) of dimensions
$\dim X=r-c_{w}$ and $\dim Y=r$. Since $\wt{V}$ is equipped with an action of
$\La\times\wt{\La}_{\g}$, it corresponds to an object $K\in D^b(\on{QCoh}(X\times Y))$.

\smallskip

%We want to apply Proposition~\ref{coh3} to $\cF_V[-d_{\g}]$.
Note that a quasi-coherent sheaf $A\in\on{QCoh}(X)$ corresponds to a representation $\wt{\nu}\in\on{Rep}_{\bql}(\wt{\La}_{\g})$, and the derived tensor product $\wt{\nu}\otimes^{L}_{\bql[\wt{\La}_{\g}]}\wt{A}$ corresponds to $K\otimes^{L} p_{X}^{*}(\iota^*A)\in D^{b}(\on{QCoh}(X\times Y))$, where involution $\iota:\la\mapsto\la^{-1}$ appears because of conventions of Section~\re{isot}(d).
 Similarly, a representation $\tau\in \on{Rep}_{\bql}(\La)$ corresponds to a quasi-coherent sheaf $B\in\on{QCoh}(Y)$ and the derived tensor product $K\otimes^{L} p_{Y}^{*}(\iota^*B)\in D^{b}(\on{QCoh}(X\times Y))$ corresponds to $\tau\otimes^{L}_{\bql[\La]}\wt{V}$.

\smallskip

Hence, by Step 2, we have $K\otimes^L p_{X}^{*}A\in D^{\geq -2\dt_{w,\br}}$ for all $A\in\on{QCoh}(X)$, and it suffices to show
that we have $K \otimes^{L} p_{Y}^{*}B\in D^{\geq -d_{\br}}$ for all $B\in\on{QCoh}(Y)$.

%Since $d_{\br}=2\dt_{w,\br}+c_w$, we would like to apply Proposition~\ref{coh3} to $\cF$.

\smallskip

{\bf Step 4.} Recall that $G_{\g}\subseteq G$ is a maximal torus. Hence every Borel subgroup $B\supseteq G_{\g}$ over $\ov{F}$ gives rise to an isomorphism
\[
\phi=\phi_B:G_{\g}\hra B\to B/[B,B]\simeq T,
\] and following \cite{BV} we call such isomorphisms {\em admissible}.\footnote{The collection of admissible isomorphisms form a $W$-torsor.}

\smallskip

Every admissible isomorphism $\phi$ gives rise to a surjective homomorphism of groups
\[
\La=X_*(T)\overset{\phi}{\lra} X_*(G_{\g}) \to X_*(G_{\g})_{\Gm_F}\simeq \wt{\La}_{\g} \overset{\iota}{\to}\wt{\La}_{\g},
\]
where $\iota$ is the map $\iota:g\mapsto g^{-1}$, hence a surjective homomorphism of $\qlbar$-algebras
$\qlbar[\La]\to\qlbar[\wt{\La}_{\g}]$. Therefore $\phi$ gives rise to a closed embedding $Y\hra X$, which we will denote by $\eta_{\phi}$.

%\footnote{The utility of inversion $\iota$ is explained in details in \cite[B.3.5]{BV} in order to have the right compatibility between the action of $\La$ and $\pi_{0}(\cL G_{\g})$.}

\smallskip

%{\bf Step 5.} The surjection \form{phi} gives rise to the closed embedding $Y\hra X$, which we will denote by $f_{\phi}$.
Also the surjective homomorphism of groups $\wt{\La}_{\g}\to\ov{\La}_{\g}$ gives rise to a homomorphism of algebraic groups $\ov{\La}_{\g}=\Spec(\bql[\ov{\La}_{\g}])\to \Spec(\bql[\wt{\La}_{\g}])=X$. In particular, every $\la\in\ov{\La}_{\g}$ induces an automorphism of $X$, hence a closed embedding $\eta_{\phi,\la}:=\la\circ \eta_{\phi}:Y\hra X$.

\smallskip

{\bf Step 5.}  By Claim~\ref{yun-supp} below, the quasi-coherent sheaf $K\in D^b(\on{QCoh}(X\times Y))$ is set-theoretically supported on the union of graphs of the $\eta_{\phi,\la}$'s. Hence, by observation of Step~3 and identities $\dim X-\dim Y=c_w$ and $-d_{\br}=-2\dt_{w,\br}-c_w$, our assertion follows from Proposition~\ref{coh3} applied to the quasi-coherent sheaf $K[-2\dt_{w,\br}]$ and closed embeddings $\{\eta_{\phi,\la}\}_{\phi,\la}$.
\end{proof}

\begin{Cl}\label{yun-supp}
 The quasi-coherent sheaf $K\in D^b(\on{QCoh}(X\times Y))$ from Step 3 is set-theoretically supported on the union of graphs of the $\eta_{\phi,\la}$'s,
 where $\phi$ runs over the set of all admissible isomorphisms $G_{\g}\isom T$ and $\la$ runs over elements of $\ov{\La}_{\g}$.
\end{Cl}

\begin{proof}
It suffices to show that each cohomology sheaf $\cH^i(K)$ is supported on the union of graphs of the $\eta_{\phi,\la}$'s.

\smallskip

By definition, $\cH^i(K)$ corresponds to the representation $H^i(\wt{V})\simeq \on{ind}_{\La_{\g}}^{\wt{\La}_{\g}}(H^i(V))$ of $\La\times \wt{\La}_{\g}$, where (as before) $H^i(V)$ is a representation of $\La\times{\La}_{\g}$, obtained as a restriction of the representation of $\La\times \cL G_{\g}$. Moreover, the action of $\La\times{\La}_{\g}$ on $H^i(V)$ naturally extends to the action of $\La\times \wt{\La}_{\g}$.
Namely, this follows from the fact that the action of $\cL G_{\g}$ on $H^i(V)=H^i(\Fl_{\g},\omega_{\cL})$ factors through
$\wt{\La}_{\g}=\pi_0(\cL G_{\g})$ (see \rco{action2}(b)).

\smallskip

By the observations of the previous paragraph, representation $H^i(\wt{V})$ of $\wt{\La}_{\g}\times\La$ decomposes as a direct sum
$\bigoplus_{\la\in\ov{\La}_{\g}} {}^{\la} H^i(V)$, where ${}^{\la} H^i(V)$ denotes the twist of $H^i(V)$ by $\la$. Therefore, it suffices to show that the quasi-coherent sheaf $K^i\in \on{QCoh}(X\times Y)$, corresponding to $H^i(V)$, is set-theoretically supported on the union of graphs of the $\eta_{\phi}$'s. As it was explained in the proof of \cite[Claim~5.3.4]{BV}, the assertion follows from  \cite[Theorem~2.3.4]{BV}, which is the group version of \cite[Theorem~2]{Yun}.
\end{proof}



\begin{Cor}\label{C:perv-tau}
For every $W$-equivariant local system on $\cL$ on $T$ and every $\tau\in\on{Rep}_{\bql}(\wt{W})$, the sheaf of $\tau$-coinvariants $\cS_{\cL,\bullet,\tau}=\on{coinv}_{\tau}(\cS_{\cL,\bullet})\in\cD([\kC_{\bullet}/\cL G])$ is $p_{\nu}$-perverse.
\end{Cor}

\begin{proof}
Since  $\cS_{\cL,\bullet,\tau}\simeq (\cS_{\cL,\bullet,\tau|_{\La}})^{W}$ and $(\cS_{\cL,\bullet,\tau|_{\La}})^{W}$ is a retract of
$\cS_{\cL,\bullet,\tau|_{\La}}$, the assertion follows from  \rt{perv-tau}.
\end{proof}

\begin{Emp}
{\bf Remark.} Note that \rt{perv-tau} is a formal consequence of \rco{perv-tau}. Indeed, for every local system on $\cL$ on $T$, the local system $\wt{\cL}:=\bigoplus_{w\in W}w_!(\cL)$ has a natural $W$-equivariant structure. Moreover, for every $\tau\in\on{Rep}_{\bql}(\La)$ and $\wt{\tau}:=\ind_{\La}^{\wt{W}}(\tau)\in\on{Rep}_{\bql}(\wt{W})$, we have a natural isomorphism $\cS_{\cL,\bullet,\tau}\simeq \cS_{\wt{\cL},\bullet,\wt{\tau}}$.
\end{Emp}

Finally, we are going to show a version of \rco{perv-tau} for Lie algebras.

\begin{Emp}
{\bf Lie algebra case.}
Let $\fg$ be the Lie algebra of $G$, let $\fC_{\fg,\bullet}\subseteq\cL\fg$ be the locally closed ind-subscheme, denote in \cite{BKV} by
$\fC_{\bullet}$, and let $\cS_{\fg,\bullet}\in\cD([\fC_{\fg,\bullet}/\cL G])$ be the affine Grothendieck--Springer sheaf for Lie algebras denoted by $\cS_{\bullet}$ in \cite{BKV}. Then, by \cite[Theorem~7.1.4]{BKV}, $\cS_{\fg,\bullet}$ is perverse and is equipped with a $\wt{W}$-action. Hence, as in \rco{action2}(b),  $\cS_{\fg,\bullet}$ has a natural lift to an object of $\cD^{\wt{W}}([\fC_{\fg,\bullet}/\cL G])$, so for every representation $\tau\in\on{Rep}_{\bql}(\wt{W})$, one can form the sheaf of $\tau$-coinvariants $\cS_{\fg,\bullet,\tau}=\on{coinv}_{\tau}(\cS_{\fg,\bullet})\in\cD([\kC_{\fg,\bullet}/\cL G])$.
 \end{Emp}


 \begin{Thm}\label{T:pervtaulie}
For every $\tau\in\on{Rep}_{\bql}(\wt{W})$, the sheaf $\cS_{\fg,\bullet,\tau}\in\cD([\kC_{\fg,\bullet}/\cL G])$ is perverse.
\end{Thm}

\begin{proof}
To prove the result, we repeat the argument of \rt{perv-tau} word-by-word, replacing results of the current work by those of \cite{BKV} and replacing \cite[Theorem~2.3.4]{BV} by \cite[Theorem~2]{Yun}.
\end{proof}




