\section{Solution Approach}\label{sec:solution}

\subsection{Minimum Weight Triangulation}
\label{sec:MWT}

\begin{algorithm}[b]
	\caption{MWT for polygon with holes $\mathcal{W}$ with weights $w$.}\label{alg:mwt}
	\begin{algorithmic}[1]
		\Ensure Weight $w_{i,j}$ is precomputed for each pair $(v_i, v_j)$ of $\mathcal{W}$'s vertices. If~$v_i$, $v_j$ are not visible to each other, then it must be that $w_{i,j} = \infty$. 
		\Procedure{MinWeightTriangulation}{$\mathcal{W}$, $w$, $n_\mathcal{P}$, $\mathit{it}_\mathit{max}$, $t_\mathit{max}$}
		\State $\mathcal{T} \leftarrow \Call{ConstrainedDelaunayTriangulation}{\mathcal{W}}$
		\For{$\mathit{it} \leftarrow 1,\dots,\mathit{it}_\mathit{max}$}
		\State\label{algl:mwt:1} $\mathcal{P} \leftarrow \varnothing$ \Comment{simple polygon (to be constructed)}
		\State $\mathcal{T}' \leftarrow \mathcal{T}$ \Comment{mesh with unadded triangles}
		\State $\Lambda \leftarrow \{\text{random triangle${}\in\mathcal{T}'$}\}$ \Comment{set of candidate triangles}
		\While{$\Lambda \neq \varnothing$ and $\vert\mathcal{P}\vert\leq n_\mathcal{P}$}\Comment{$\vert\mathcal{P}\vert\sim{}$the num. of $\mathcal{P}$'s vertices}
		\State $\Delta \leftarrow{}$random triangle${}\in\Lambda$.
		\State $\mathcal{P} \leftarrow \mathcal{P} \cup \Delta$
		\State $\mathcal{T}' \leftarrow \mathcal{T}' \setminus \Delta$
		\State\label{algl:mwt:1.9} $\Lambda \leftarrow \{\Delta' \in \mathcal{T}' \;\vert\;\text{$\mathcal{P}$ and $\Delta'$ share a single edge exclusively}\}$ 
		\EndWhile\label{algl:mwt:2}
		\State\label{algl:mwt:3} $w_\mathcal{P} \leftarrow{}$Reindex weights $w$ according to $\mathcal{P}$'s vertices.
		\State\label{algl:mwt:4} $\mathcal{T}_{\mathcal{P}}\leftarrow{}$\Call{MinWeightTriangulationSimple}{$\mathcal{P}$, $w_\mathcal{P}$}
		\State\label{algl:mwt:5} $\mathcal{T} \leftarrow \mathcal{T}' \cup \mathcal{T}_{\mathcal{P}}$ \Comment{merge the new and original meshes}
		\If{it elapsed more than $t_\mathit{max}$ sec from the procedure's start}
		\State {\bf break}
		\EndIf
		\EndFor
		\State Report $\mathcal{T}$.
		\EndProcedure
	\end{algorithmic}
\end{algorithm}

