\subsection{Correspondences}
\label{appendix:correspondences}

\begin{definition}[Correspondence]
Let $\Theta$ and $X$ be topological spaces. 
A \emph{correspondence} from $\Theta$ to $X$, 
denoted $\corr: \Theta \rightrightarrows X$, 
is a mapping that assigns to each $\theta \in \Theta$ a subset of $X$, that is,
\(
   \corr(\theta) \subseteq X,  \; \text{for every} \, \theta \in \Theta.
\)
\end{definition}

\begin{definition}[Compact-valued Correspondence]
    Let $X$ and $\Theta$ be topological spaces. 
    A correspondence $\corr: \Theta \rightrightarrows X$ is \emph{compact-valued} 
    if for every $\theta \in \Theta$, the set $\corr(\theta)$ is compact in $X$.
\end{definition}

\begin{definition}[Continuity of a Correspondence] \label{def:continuity_of_a_correspondence}
Let $X$ and $\Theta$ be topological spaces, and let $\corr: \Theta \rightrightarrows X$ be a correspondence.
\begin{itemize}
    \item $\corr$ is \textbf{\emph{upper hemicontinuous}} at $\theta \in \Theta$ if for every open set $V$ with $\corr(\theta) \subset V$, 
    there exists a neighborhood $U$ of $\theta$ such that  
    \[
    \corr(\theta') \subset V, \quad \forall \theta' \in U.
    \]
    \item $\corr$ is \textbf{\emph{lower hemicontinuous}} at $\theta \in \Theta$ if for every open set $V$ with $V \cap \corr(\theta) \neq \emptyset$, there exists a neighborhood $U$ of $\theta$ such that  
    \[
    \corr(\theta') \cap V \neq \emptyset, \quad \forall \theta' \in U.
    \]
    \item $\corr$ is \textbf{\emph{continuous}} if it is both upper and lower hemicontinuous at every $\theta \in \Theta$.
\end{itemize}
\end{definition}

\begin{lemma}[Berge's Maximum Theorem] \label{lemma:berges_maximum_theorem}
Let $X$ and $\Theta$ be topological spaces, and let $f: X \times \Theta \to \mathbb{R}$ be a continuous function. 
Suppose that $\corr: \Theta \rightrightarrows X$ is a compact-valued correspondence and that $\corr(\theta) \neq \emptyset$ for all $\theta \in \Theta$. Define the function
\[
    f^\star(\theta) = \sup_{x \in \corr(\theta)} f(x, \theta)
\]
and the solution correspondence
\[
    \corr^\star(\theta) = \arg\max_{x \in \corr(\theta)} f(x, \theta).
\]
If $\corr$ is continuous, then the function $f^\star: \Theta \to \mathbb{R}$ is continuous and
the solution correspondence $\corr^\star: \Theta \rightrightarrows X$ is compact-valued and upper hemicontinuous.
\end{lemma}
For more information see \cite{beavis1990optimization}.


\subsection{Falling and Rising Factorials and Stirling Numbers}
\label{appendix:falling_factorials}

For clarity, we restate the factorial operators given in \sectionref{sec:preliminaries}.
\begin{definition}[Falling and Rising Factorials] \label{def:falling_factorial}
For $x \in \Rfield$ and $m \in \Nfield$ ,
the \emph{falling factorial} is defined as
\begin{equation*} 
    \fallingfact{x}{m}
    \eqdef \prod_{i=0}^{m-1} (x - i)
    = x (x - 1) \cdots (x - m + 1),
\end{equation*}
and the \emph{rising factorial} is defined as
\begin{equation*}
    \risingfact{x}{m}
    \eqdef \prod_{i=0}^{m-1} (x + i)
    = x (x + 1) \cdots (x + m - 1).
\end{equation*}
In both cases, the empty product is equal to one so that 
$\fallingfact{x}{0}=\risingfact{x}{0}=1$.
\end{definition}



\begin{lemma}
    \label{lemma:falling_factorial_identities}
    For all $T, m \in \Nfield$,
    \begin{enumerate}[label={\arabic*.}, ref=\ref{lemma:falling_factorial_identities}.\arabic*]
        \item
        \label{lemma:falling_factorial_identities_1}
        $\fallingfact{T}{m+1} = T \cdot \fallingfact{(T-1)}{m}$

        \item
        \label{lemma:falling_factorial_identities_2}
        $\fallingfact{T}{m} + m \cdot \fallingfact{T}{m-1} = \fallingfact{(T+1)}{m}$

        \item
        \label{lemma:falling_factorial_identities_3}
        \(\fallingfact{T}{m} = (-1)^m \risingfact{(-T)}{m}\)
    \end{enumerate}
\end{lemma}


\begin{definition}[The Stirling Numbers of the First Kind]
    \label{def:stirling_numbers_of_the_first_kind}
    The \emph{Stirling numbers of the first kind} $ \unstirling{n}{k}$
    count the number of permutations of \( n \) elements consisting of exactly \( k \) disjoint cycles, where $1 \leq k \leq n$.
    They satisfy the recurrence relation:
    \[
        \unstirling{n+1}{k} = n \unstirling{n}{k} + \unstirling{n}{k-1}, \quad \text{for}\ \ n \geq 1,\, k \geq 1,
    \]
    with base cases:
    \[
        \unstirling{0}{0} = 1, \qquad \unstirling{n}{0} = 0 \ \ \text{for}\ \ n > 0, \quad \unstirling{0}{k} = 0 \ \ \text{for}\ \ k > 0. 
    \]
    The \emph{signed Stirling numbers of the first kind} $\stirling{n}{k}$ are defined by:
    \[
        \stirling{n}{k} = (-1)^{n-k} \unstirling{n}{k}.
    \]
\end{definition}

\begin{lemma}[Expansion of Falling Factorials]
    \label{lemma:falling_factorial_expansion}
    The rising and falling factorial can be expressed in terms of the Stirling numbers of the first kind as:
    \begin{equation*}
        \risingfact{x}{n} = \sum_{k=0}^{n} \unstirling{n}{k} x^k, 
        \quad \quad
        \fallingfact{x}{n} = \sum_{k=0}^{n} \stirling{n}{k} x^k.
    \end{equation*}    
\end{lemma}
\citet{graham1994concrete}  provides a thorough overview of rising and falling factorials, 
along with Stirling numbers and their combinatorial properties.


\subsection{Properties of Elementary Symmetric Polynomials}
\label{appendix:elementary_symmetric_polynomials}


\begin{remark}[Generating Function for ESPs]
    \label{remark:esps_gen_func}
    The ESPs of a vector \( x \in \mathbb{R}^K \)
    can be expressed through their generating function by
    \[
        \sum_{m=0}^{K} \sigma_m(x) t^m = \prod_{k=1}^{K} (1 + x(k) \cdot t) 
    \]
\end{remark}


\begin{lemma}[Recurrence Relation for ESPs] 
    \label{lemma:elementary_symmetric_polynomial_recurrence_relation}
    Let $m, K \in \Nplus$ and $x \in \Rdim{K}$.
    It holds that
    \begin{equation*}
    \esp{m}{x} = x(k) \cdot \esp{m-1}{ x\minind{k} } + \esp{m}{ x\minind{k} },
    \end{equation*} 
    for every  $k \in [K]$.
\end{lemma}
See \cite{macdonald1998symmetric} for more information about recurrence relations in symmetric polynomials.



\begin{lemma}[Summation of reduced ESPs] 
    \label{lemma:elementary_symmetric_polynomial_sum_identity}
    For all $K \in \Nplus$ and $x \in \Rdim{K}$,
    \begin{equation*}
        \sum_{i=1}^{K} \esp{m}{ x\minind{i} } = (K - m) \cdot \esp{m}{x}
        , \ \  0\le m\le K.
    \end{equation*}
\end{lemma}

\begin{lemma}[Shifted ESP Expansion]
    \label{lemma:elementary_symmetric_polynomial_with_shift}
    Let \( x \in \mathbb{R}^K \), \( t \in \mathbb{R} \), and \( n \in \Nfield \). 
    Then, 
    \begin{equation*}
        \sigma_n(\univec{t}{K} - x) = \sum_{i=0}^{n} (-1)^i \sigma_i(x) \binom{K - i}{n - i} t^{n - i}.
    \end{equation*}
\end{lemma}
The proofs of 
\lemmaref{lemma:elementary_symmetric_polynomial_sum_identity,lemma:elementary_symmetric_polynomial_with_shift} 
are provided in \appendixref{appendix:technical_A}.








\section{Proof of Theorem \ref{theorem:nash}}
\label{appendix:the_adversarial_game_dynamics}

In this section, we prove \theoremref{theorem:nash}, which characterizes a Nash equilibrium of the game.
\begin{lemma}[Compact Action Space and Continuity]
\label{lemma:continuity_of_the_value_function}
For every $H \geq 1$, there exists a \emph{continuous, non-empty and compact-valued correspondence}
$\corr_H : \Rdim{K} \rightrightarrows \intsimplex{K-1}$
(see \appendixref{appendix:correspondences} for definitions),
such that 
\begin{equation}
    \label{eq:compact_selection_value_function}
    \pot{H}{K}{s} = \min_{r \in \corr_H(s)} \; \max_{q \in \Delta} \; \pot{H-1}{K}{s + q \oslash r}.
\end{equation}
Consequently, $\potfunction{ H }{K}$ is continuous for all \(H \in \Nfield\).
\end{lemma}
While no fixed compact subset of the simplex interior contains 
the optimal bookmaker's actions for all $H$ and $s$, 
\lemmaref{lemma:continuity_of_the_value_function} establishes that for each specific pair $(H, s)$, 
such a compact set, $\corr_H(s)$, exists. 
The continuity of the correspondence $\corr_H$ in $s$ ensures that, for all $H$, 
the value function $\potfunction{H}{K}$ is continuous---a key property supporting our analysis and results.
\lemmaref{lemma:continuity_of_the_value_function} 
is built on bounding the value function by the loss of a \naive bookmaker
acting with the uniform distribution $r = \univec{\frac{1}{K}}{K}$ in all rounds.
See \appendixref{appendix:compact_selection_and_continuity} for the full proof.
\begin{lemma}\label{lemma:value_function_if_convex}
    Let \( H \geq 1 \) and suppose that the value function \( \potfunction{H-1}{K} \) is convex.  
    Then, for every state \( s \), there exists an optimal gambler who is decisive; 
    that is, 
    \begin{equation}
        \label{eq:proof_of_the_game_dynamics_paper_eq}
        \pot{H}{K}{s} = \min_{r \in \corr_H(s)} \; \max_{k \in [K]} \; \pot{H-1}{K}{s + \basis{k} \oslash r}.
    \end{equation}
\end{lemma}
\begin{proof}[Proof of \lemmaref{lemma:value_function_if_convex}]
    Let $H \geq 1,\, s \in \Rdim{K}$ and suppose that $\potfunction{H-1}{K}$ is a convex function. 
    The gambler's action is a mixture of $K$ decisive actions;
    that is, any vector $q \in \simplex{}$ can be written as a convex combination of the standard basis vectors $\stdbasis{K}$.  
    Let $X \in \stdbasis{K}$ be a one-hot random variable distributed according to $q$, i.e.,
    \begin{equation}\label{eq:proof_nash_def_of_X}
        \mathbb{P}(X = \mathbf{e}_k) = \vecind{q}{k} \quad \text{for all } k \in [K],
    \end{equation}
    and express \eqref{eq:compact_selection_value_function} as
    \begin{equation*}
        \pot{H}{K}{s} 
        =
        \min_{ r \in \corr_H(s) }\; \max_{ q \in \simplex{}} \;
                \pot{ H-1 }{K}{ s +  \mathbb{E}_{q} \left[X\right] \oslash r  }.
    \end{equation*}
    For any $r \in  \corr_H(s)$ it holds that
    \begin{align*}
        \max_{ q \in \simplex{}} 
                \pot{ H-1 }{K}{ s +  \mathbb{E}_{q} \left[X\right] \oslash r  }
        &\stackrel{(a)}{=} 
        \max_{q \in \simplex{}} \pot{ H-1 }{K}{\mathbb{E}_{q}\left[ s + X \oslash r \right ]}
        \\
        &\stackrel{(b)}{\leq} 
        \max_{q \in \simplex{}} \mathbb{E}_{q} \left[ \pot{ H-1 }{K}{s + X \oslash r} \right]
        \\ 
        &\stackrel{(c)}{=} 
        \max_{q \in \simplex{}} \sum_{k \in \nset{K}} 
            q(k) \cdot  \pot{ H-1 }{K}{s + \basis{k} \oslash r }
        \\ 
        &\stackrel{(d)}{=} 
        \max_{q \in \stdbasis{K}} \sum_{k \in \nset{K}} 
            q(k) \cdot  \pot{ H-1 }{K}{s + \basis{k} \oslash r }
        \\ 
        &=
            \max_{k \in \nset{K}} \pot{ H-1 }{K}{s + \basis{k} \oslash r },
    \end{align*}
    where: $(a)$ follows by the linearity of expectation;
    $(b)$ follows by Jensen's inequality and the assumption that $\potfunction{H-1}{K}$ is a convex function;
    $(c)$ follows by \eqref{eq:proof_nash_def_of_X};
    and $(d)$ holds since the sum is linear in $q$, and a maximum of a linear function over the simplex 
    is attained at a vertex.   
\end{proof}


As the state vector $s \in \mathbb{R}^K$ captures the payouts already committed to the possible outcomes, 
it is natural to expect that if $\hat{s} \succeq s$, 
then the bookmaker's optimal loss given $\hat{s}$ cannot be smaller than given $s$. 
Interestingly, even a single coordinate in $s$ being smaller than the corresponding coordinate in $\hat{s}$ 
results in a strictly smaller optimal loss. 
\begin{lemma}[Coordinate-wise Monotonicity of the Value Function] \label{lemma:cwm_lemma}
    Let  $\hat{s},s \in \Rdim{K}$.
    \begin{enumerate}[label={{\arabic*.}}, ref={\ref{lemma:cwm_lemma}.\arabic*}]
        \item  \label{lemma:cw_weak_m}
        \textbf{\emph{(Weak)}} 
        For every $H \in \Nfield$, \,  $\hat{s} \succeq s \implies \pot{H}{K}{\hat{s}} \geq \pot{H}{K}{s}$.
        \item \label{lemma:cw_strict_m}
        \textbf{\emph{(Strict)}}
        For every $H \in \Nplus$, \,  $\hat{s} \succ s \implies \pot{ H }{K}{\hat{s}} > \pot{ H }{K}{s}$. 
    \end{enumerate}
\end{lemma}
The proof of \lemmaref{lemma:cwm_lemma} is presented in \appendixref{appendix:proof_cwm_lemma}.


\begin{lemma} \label{lemma:proof_opt_bookmaker_under_convexity}
    Let \( H \geq 1 \) and suppose that the value function \( \potfunction{H-1}{K} \) is convex.  
    Then, for every state~$s$, 
    the optimal bookmaker's action $\optr$ is unique and satisfies
    \begin{equation} \tag{\ref{eq:main_results_thm_the_game_dynamics}}
        \pot{H}{K}{s} = \pot{ H-1 }{K}{s + q \oslash \optr } \quad \forall q \in \stdbasis{K}.
    \end{equation}
\end{lemma}
The proof of \lemmaref{lemma:proof_opt_bookmaker_under_convexity}, 
given in \appendixref{appendix:proof_opt_bookmaker_under_convexity}, 
proceeds by contradiction: 
any action $r$ that fails to satisfy \eqref{eq:main_results_thm_the_game_dynamics} enables a redistribution of probability mass that reduces the loss, contradicting optimality. Uniqueness follows from the coordinate-wise strict monotonicity of the value function (\lemmaref{lemma:cw_strict_m}), which ensures no two distinct actions yield the same loss.

\begin{lemma} \label{lemma:convexity_of_value_function}
    $\potfunction{H}{K}$ is a convex function for every $H \in \Nfield$.
\end{lemma}

\begin{proof}[Proof of \lemmaref{lemma:convexity_of_value_function}]
    We prove by induction on $H$.
    In the base case, $\potfunction{0}{K}$ is a convex function as it is the maximum of finite convex functions.   
    Let $H \in \Nplus$ and assume that $\potfunction{H-1}{K}$ is a convex function.
    Let \( a, b \in \Rdim{K},\, \lambda \in [0, 1] \),
    and let
    \( r_a, r_b, r \in \simplex{K-1} \) be the optimal bookmaker 
    actions for states \( a, b \) and \( \lambda a + \left( 1-\lambda \right) b \), 
    respectively.
    It holds that
    \begin{align*}
        \pot{ H }{K}{ \lambda a + \left(1-\lambda \right) b } 
        &\stackrel{(a)}{=} \max_{k \in \nset{K}} \pot{ H-1 }{K}{ 
                \lambda {a} + (1-\lambda) {b} + \basis{k} \oslash \left( \lambda {r} + \left(1-\lambda\right) {r} \right)  
            }
        \\
        &\stackrel{(b)}{\leq} \max_{k \in \nset{K}} \pot{ H-1 }{K}{
                \lambda {a} + (1-\lambda) {b} 
                + {\basis{k}} \oslash {\left( \lambda r_a + \left(1-\lambda\right) r_b \right)}
            }
        \\ 
        &\stackrel{(c)}{\leq} \max_{k \in \nset{K}} \pot{ H-1 }{K}{
                \lambda \left( a +  \basis{k} \oslash r_a \right) 
                + \left(1-\lambda\right) \left( b + \basis{k} \oslash r_b \right)
            }
        \\ 
        &\stackrel{(d)}{\leq} 
            \max_{k \in \nset{K}} \left( \lambda \pot{ H-1 }{K}{ a + \basis{k} \oslash r_a}  
            + \left(1-\lambda\right) \pot{ H-1 }{K}{ b + \basis{k} \oslash r_b }
            \right)
        \\
        &\stackrel{(e)}{\leq} 
            \lambda \max_{k \in \nset{K}} \pot{ H-1 }{K} { a + \basis{k} \oslash r_a } 
            + \left(1-\lambda\right) \max_{k \in \nset{K}} \pot{ H-1 }{K}{ b + \basis{k} \oslash r_b }
        \\
        &\stackrel{(f)}{=} 
            \lambda \pot{ H }{K}{a} + \left(1-\lambda\right) \pot{ H + 1}{K}{b},
    \end{align*}
    where the steps are justified as follows:
    \begin{enumerate}[label={$(\alph*)$}]
        \item 
        Follows from \lemmaref{lemma:proof_opt_bookmaker_under_convexity}.
        \item
        Follows from the optimality of \(r\), which implies that the action $\lambda r_a + (1-\lambda)r_b$
        induces a larger objective.
        \item 
        Follows from the convexity of the function \(x \mapsto \frac{1}{x}\) in $\mathbb{R}_+$ 
        and \lemmaref{lemma:cw_weak_m}. In particular, define the vectors 
        \begin{equation*}
            \begin{aligned}
                s &\eqdef \lambda {a} + (1-\lambda) {b} 
                    + {\basis{k}} \oslash {\left( \lambda r_a + \left(1-\lambda\right) r_b \right)},
                \\
                \hat{s} &\eqdef \lambda \left( a +  \basis{k} \oslash r_a \right) 
                    + \left(1-\lambda\right) \left( b + \basis{k} \oslash r_b \right).
            \end{aligned}
        \end{equation*}
        As $r_a(k),r_b(k) > 0$, it holds that $\lambda r_a(k) + \left(1-\lambda\right) r_b(k) > 0$.
        By weak coordinate-wise monotonicity of the value function,
        $\pot{H-1}{K}{s} \leq \pot{H-1}{K}{\hat{s}}$.
        \item
        By the induction hypothesis, \(\potfunction{H-1}{K}\) is a convex function.
        \item
        Holds as maximizing each function separately can only increase the overall value.
        \item 
        Follows from our choice of $r_a,r_b$ as the optimal actions for states $a$ and $b$, respectively. 
    \end{enumerate}
\end{proof}

\begin{proof}[Proof of Theorem \ref{theorem:nash}]
    Fix $H \in \Nplus$ and $s \in \Rdim{K}$.
    By \lemmaref{lemma:convexity_of_value_function}, the value function $\potfunction{H-1}{K}$ is convex.
    This implies, by \lemmaref{lemma:value_function_if_convex}, the existence of an optimal gambler who is decisive.
    Moreover, \lemmaref{lemma:proof_opt_bookmaker_under_convexity} guarantees uniqueness of the optimal 
    bookmaker action $\optr \in \simplex{}$, which satisfies
    \begin{equation} \tag{\ref{eq:main_results_thm_the_game_dynamics}}
        \pot{H}{K}{s} = \pot{ H-1 }{K}{s + q \oslash \optr } \quad \forall q \in \stdbasis{K}.
    \end{equation}
\end{proof}




\subsection{Proof of Lemma \ref{lemma:continuity_of_the_value_function}}
\label{appendix:compact_selection_and_continuity}

This section proves \lemmaref{lemma:continuity_of_the_value_function}, 
showing that for all $H \geq 1$, 
the minimization over $r$ in the value function (\definitionref{def:value_function}) can be restricted to a continuous, 
compact-valued correspondence 
\[
    \corr_H : \Rdim{K} \rightrightarrows \intsimplex{K-1}. 
\]
Building on this property, 
we establish the continuity of the value function $\potfunction{H}{K}$ with respect to $s$.


We begin with the following lemma:
\begin{lemma}[Uniform Translation] \label{lemma:uniform_translation_property}
    For any \(H \in \Nfield\), $s \in \Rdim{K}$ and $c \in \Rfield$, \;
    \[
        \pot{ H }{K}{s + \univec{c}{K}} = \pot{ H }{K}{s} + c.
    \]
\end{lemma}
The proof of \lemmaref{lemma:uniform_translation_property}, 
provided in \appendixref{appendix:technical_B}, proceeds by induction on $H$ using the recursive definition of the value function in \definitionref{def:value_function}.
\begin{corollary}
    \label{corollary:optimal_bookmaker_state_shift}
    Let $H \in \Nfield$, $s \in \Rdim{K}$ and $c \in \Rfield$. 
    For~the vector $\hat{s} = s + \univec{c}{K}$, it holds that 
    \begin{align*}
        \textstyle\arg\inf_{r \in \simplex{}} 
            \left\{ 
                \max_{q \in \simplex{}} \pot{ H }{K}{s + q \oslash r}                
            \right\}
        = 
        \textstyle\arg\inf_{r \in \simplex{}} 
            \left\{ 
                \max_{q \in \simplex{}} \pot{ H }{K}{\hat{s} + q \oslash r}                
            \right\}.
    \end{align*}
\end{corollary}


The key idea in the proof of \lemmaref{lemma:continuity_of_the_value_function}
is that the value function must be bounded above by the maximal loss incurred under any alternative bookmaking strategy. 
In particular, the value function is upper bounded by the performance of
a \naive bookmaker acting with the uniform distribution $r = \univec{\frac{1}{K}}{K}$ in all rounds.
For $H \in \Nplus$ define the function $\omega_H : \Rdim{K} \to \Rpplus{}$ as
\begin{equation}
    \label{eq:def_of_omega_H_s}
    \omega_{H}(s) 
    \; \eqdef \;
    \frac{1}
    {\max_{i \in [K]} s(i) - \min_{j \in [K]} s(j)  + H K },
\end{equation}    
and define the correspondence  $\corr_H : \Rdim{K} \rightrightarrows \intsimplex{K-1}$ as
\begin{equation}
    \label{eq:def_of_corr_H}
    \corr_{H}(s) 
    \; \eqdef \;
    \{ r \in \simplex{K-1} \mid r \succeq \univec{\omega_H(s)}{K} \}.
\end{equation}
\begin{lemma} \label{lemma:properties_of_corr}
    The correspondence $\corr_H$ is continuous, non-empty and compact-valued
    (see \appendixref{appendix:correspondences} for definitions) for all $H \in \Nplus$ .
\end{lemma}
The proof of \lemmaref{lemma:properties_of_corr} is provided in \appendixref{appendix:technical_B}.


\begin{proof}[Proof of Lemma \ref{lemma:continuity_of_the_value_function}]
Let $H \in \Nplus$, $s \in \Rdim{K}$ and define
\begin{equation}
    \hat{s} \eqdef s - \univec{\min_{j \in [K]} s(j)}{K}. \label{eq:proof_of_uniform_translation_def_of_hat_s}
\end{equation}
Consider a game with $H$ rounds and initial state vector \( \hat{s} \).
An optimal loss is bounded above by the loss of any other bookmaker, hence
\begin{align}
    \label{eq:value_bound_by_naive_bookmaker}
    \pot{ H }{K}{\hat{s}} \leq \max_{i \in [K]} \vecind{\hat{s}}{i} + H K,
\end{align}
where the RHS of \eqref{eq:value_bound_by_naive_bookmaker} is the maximal loss of the \naive bookmaker 
acting with the uniform distribution $r = \univec{\frac{1}{K}}{K}$ in all rounds.
We claim that
\begin{equation}
    \label{eq:proof_of_uniform_translation_hat_s}
     \textstyle\arg\inf_{r \in \simplex{}} 
            \left\{ 
                \max_{q \in \simplex{}} \pot{ H-1 }{K}{\hat{s} + q \oslash r}                
            \right\}
    \subseteq  \corr_H(s).
\end{equation}
Assume in contradiction there exists $r$ in the LHS of \eqref{eq:proof_of_uniform_translation_hat_s}
which is not in the RHS. 
Then there exist $k \in \nset{K}$ and $\kappa > 0$ such that 
\[
    \vecind{r}{k} = 
    \frac{1}{\max_{i \in [K]} s(i) - \min_{j \in [K]} s(j)  + H K  + \kappa}.
\] 
Since the $q$ term in the LHS of \eqref{eq:proof_of_uniform_translation_hat_s} can be $\basis{k}$, 
we obtain 
\begin{align*}
    \pot{H}{K}{\hat{s}} 
    \geq \;   
    & \max_{i \in [K]} s(i) - \min_{j \in [K]} s(j) + H K + \kappa 
    \\ 
    \stackrel{(a)}{=} \;
    & \max_{i \in [K]} \hat{s}(i) + H K + \kappa
    \\ 
    > \; 
    & \max_{i \in [K]} \hat{s}(i) + H K 
    \\ 
    \stackrel{(b)}{\geq}
    &\pot{H}{K}{\hat{s}},
\end{align*}
which yields a contradiction.
Here, $(a)$ follows from the construction of $\hat{s}$ in \eqref{eq:proof_of_uniform_translation_def_of_hat_s},
and $(b)$ follows from the upper bound on $\pot{H}{K}{\hat{s}}$ in \eqref{eq:value_bound_by_naive_bookmaker}.
Combining \eqref{eq:proof_of_uniform_translation_hat_s} with \corollaryref{corollary:optimal_bookmaker_state_shift}, 
we conclude that
\begin{equation}
    \label{eq:proof_of_uniform_translation_s_conclusion}
     \textstyle\arg\inf_{r \in \simplex{}} 
            \left\{ 
                \max_{q \in \simplex{}} \pot{ H-1 }{K}{s + q \oslash r}                
            \right\}
    \subseteq  \corr_H(s).
\end{equation}
Thus, the value function $\potfunction{H}{K}$ is given by
\begin{equation*}    
    \pot{H}{K}{s} = \min_{r \in \corr_H(s)} \max_{q \in \Delta} \pot{H-1}{K}{s + q \oslash r},
\end{equation*}
where by \lemmaref{lemma:properties_of_corr}, $\corr_H(s)$ is a continuous, non-empty and compact-valued correspondence.


We prove by induction on $H$ that $\potfunction{H}{}$ is continuous.
\begin{itemize}
\item \emph{Base case} \(( H = 0 )\):
In the base case, $\potfunction{0}{K}$ is continuous as it is the maximum of finite continuous functions.   
\item 
\emph{Inductive step} \( (H-1 \to H) \):
Let $H \in \Nplus$ and define the function $\mathcal{U} : \Rdim{K} \times \Rplus{K} \to \Rfield$ as
\begin{equation}
    \label{eq:def_of_U_func}
    \mathcal{U}(s,r) \; \eqdef \; \max_{q\in\Delta}\; \pot{H-1}{K}{\, s + q\oslash r\,}.
\end{equation}
We claim that \,$\mathcal{U}(s,r)$ is continuous in $(s,r)$:
for any fixed \(q \in \Delta\), the mapping 
\[
    (s,r) \mapsto s + q\oslash r
\]
is continuous in \((s, r)\) on \(\Rdim{K} \times \Rplus{K}\) as division by a positive number 
and addition of vectors are continuous. 
By the induction hypothesis, \(\potfunction{H-1}{K}\) is continuous, and thus 
the composition 
\(
    (s,r) \mapsto  \pot{H-1}{K}{s + q\oslash r}
\)
is continuous.
Since \(\Delta^{K-1}\) is a compact set, the function
$\mathcal{U}$ is the pointwise maximum of continuous functions over a compact set, and hence continuous in \((s,r)\).
We express the value function as:
\begin{align*}
    \pot{H}{K}{s} 
    &=
    \inf_{r\in \corr_H(s) }\; \max_{q\in\Delta}\; \pot{H-1}{K}{\, s + q\oslash r\,}
    \\ 
    &=
    \inf_{r\in \corr_H(s)} \mathcal{U}(s,r),
\end{align*}
where the first equality follows from \eqref{eq:proof_of_uniform_translation_s_conclusion},
and the second equality follows from the definition of $\mathcal{U}(s,r)$ in \eqref{eq:def_of_U_func}.
The function $\mathcal{U}(s,r)$ is continuous, as established above, 
and the correspondence $\corr_H : \Rdim{K} \rightrightarrows \Delta^{K-1}$ is compact-valued, 
continuous, and non-empty-valued by \lemmaref{lemma:properties_of_corr}. 
Hence, the conditions of Berge's Maximum Theorem (\lemmaref{lemma:berges_maximum_theorem}) are satisfied, 
and $\potfunction{H}{K}$ is continuous.
\end{itemize}
\end{proof}








\subsection{Proof of Lemma \ref{lemma:cwm_lemma}}
\label{appendix:proof_cwm_lemma}

This section provides the proof of \lemmaref{lemma:cwm_lemma}, which establishes coordinate-wise monotonicity of the value function. 
We first prove the strict case (\lemmaref{lemma:cw_strict_m}) and then derive the weak case (\lemmaref{lemma:cw_weak_m}) as a direct adaptation.

\subsubsection{Proof of Lemma \ref{lemma:cw_strict_m}}

The degenerate case \( K = 1 \) follows directly from \definitionref{def:value_function}:
Let $H \in \Nplus$ and \( \hat{s}, s \) be $1$-dimensional vectors such that \( \hat{s} \succ s \);
that is, $\hat{s}(1) > s(1)$.
It holds that
\begin{align*}
    \pot{H}{K}{\hat{s}} 
    = \;
    &\hat{s}(1)+ H 
    \\
    > \;
    &s(1)+ H 
    \\ 
    = \;
    &\pot{H}{K}{s} ,
\end{align*}
where the equalities follow from the fact that $q_t(1) = r_t(1) = 1$ for all $t \in [H]$.


To prove coordinate-wise strict monotonicity in the general case, 
we analyze the game at the last round, as its structure differs from other rounds. 
The following lemma establishes a Nash equilibrium of the game when \( H = 1 \).
\begin{lemma} \label{lemma:nash_last_round}
    In case $H=1$, for every $s \in \Rdim{K}$ 
    the optimal bookmaking action $\optr \in \corr_1(s)$ is unique and satisfies
    \begin{equation} \label{eq:nash_last_round}
        \pot{1}{K}{s} = \pot{ 0 }{K}{s + q \oslash \optr } \quad \forall q \in \stdbasis{K}.
    \end{equation}
\end{lemma}
The proof of \lemmaref{lemma:nash_last_round} is presented in \appendixref{appendix:technical_B}.

\begin{proof}[Proof of \lemmaref{lemma:cw_strict_m}]
Let \( \hat{s}, s \in \Rdim{K} \) be such that \( \hat{s} \succ s \).  
We prove by induction on~$H$. 

\begin{itemize}
\item \emph{Base case} (\( H=1 \)):  
By \lemmaref{lemma:nash_last_round}, it holds that 
\begin{equation*}
    \pot{1}{K}{s} = \vecind{s}{k} + \frac{1}{\vecind{r}{k}} \quad \forall k \in [K]
\end{equation*}
for some \( r \in \simplex{} \).
Assume in contradiction that \( \pot{1}{K}{\hat{s}} \leq \pot{1}{K}{s} \).  
Then there exists \( \hat{r} \in \simplex{} \) such that  
\begin{equation}
    \label{eq:proof_of_coordinate_wise_monotonicity_base}
    \vecind{\hat{s}}{k} + \frac{1}{\vecind{\hat{r}}{k}} \leq \vecind{s}{k} + \frac{1}{\vecind{r}{k}} \quad \forall k \in \nset{K}.
\end{equation}


Since \( \hat{s} \succ s \), there exists \( i \in \nset{K} \) such that \( \vecind{\hat{s}}{i} > \vecind{s}{i} \).  
By \eqref{eq:proof_of_coordinate_wise_monotonicity_base}, it must hold that \( \vecind{\hat{r}}{i} > \vecind{r}{i} \).  
Then, there must exist \( j \in \nset{K}\setminus \{i\} \) such that \( \vecind{\hat{r}}{j} < \vecind{r}{j} \).  
% But since \( \vecind{\hat{s}}{j} \geq \vecind{s}{j} \), it follows that  
It follows that
\begin{align*}
    \vecind{\hat{s}}{j} + \frac{1}{\vecind{\hat{r}}{j}} 
    \stackrel{(a)}{\geq} 
    \vecind{s}{j} + \frac{1}{\vecind{\hat{r}}{j}} 
    \stackrel{(b)}{>} 
    \vecind{s}{j} + \frac{1}{\vecind{r}{j}},
\end{align*}
where $(a)$ holds as $\hat{s} \succeq s$, and $(b)$ holds since $\vecind{\hat{r}}{j} < \vecind{r}{j}$.
This contradicts \eqref{eq:proof_of_coordinate_wise_monotonicity_base}.



\item \emph{Inductive step} (\( H \to H+1 \)):  
Define 
\begin{align*}    
    \simplex{}_\omega 
    &= 
    \left\{ r \in \simplex{} \, \mid \, r \succeq \univec{ \min \{ \omega_{H+1}(s) ,\, \omega_{H+1}(\hat{s})\} }{K} \right\}.
\end{align*}
$\simplex{}_\omega$ is a compact set for which 
\(
    \corr_H(s), \corr_H(\hat{s}) \subseteq \simplex{}_\omega.
\)
Hence, by \lemmaref{lemma:continuity_of_the_value_function},
\begin{align}    
    \pot{H+1}{K}{s} 
    &= \min_{ r \in \simplex{}_\omega } \; \max_{ q \in \simplex{} } \pot{H}{K}{ s + q \oslash r }
    \label{eq:proof_of_coordinate_wise_monotonicity_inductive_step_value_functions_s}
    \\[6pt]
    \pot{H+1}{K}{\hat{s}} 
    &= \min_{ r \in \simplex{}_\omega } \; \max_{ q \in \simplex{} }  \pot{H}{K}{ \hat{s} + q \oslash r }.
    \label{eq:proof_of_coordinate_wise_monotonicity_inductive_step_value_functions_hat_s}
\end{align}


By \eqref{eq:proof_of_coordinate_wise_monotonicity_inductive_step_value_functions_hat_s}, 
there exists \( \hat{r} \in \simplex{}_\omega \) such that  
\begin{equation}
    \label{eq:monotonicity_of_value_function_b}
    \pot{H+1}{K}{\hat{s}} = \max_{ q \in \simplex{} } \pot{H}{K}{ \hat{s} + q \oslash \hat{r} }.
\end{equation}
Fix
\begin{equation}
    \label{eq:proof_of_coordinate_wise_monotonicity_def_of_bar_q}
    \bar{q} \in \arg \max_{q \in \simplex{}} \pot{H}{K}{ s + q \oslash \hat{r} }.
\end{equation}  
It holds that  
\begin{align*}
    \pot{H+1}{K}{s} 
    &\stackrel{(a)}{=} \;
    \min_{ r \in \simplex{}_\omega } \max_{ q \in \simplex{} } \pot{H}{K}{ s + q \oslash r }
    \\ 
    &\stackrel{(b)}{\leq} \;
    \max_{ q \in \simplex{} } \pot{H}{K}{ s + q \oslash \hat{r} }
    \\ 
    &\stackrel{(c)}{=} \;
    \pot{H}{K}{ s + \bar{q} \oslash \hat{r} }
    \\
    &\stackrel{(d)}{<} \;
    \pot{H}{K}{ \hat{s} + \bar{q} \oslash \hat{r} }
    \\
    &\stackrel{(e)}{\leq} \; 
    \max_{ q \in \simplex{} } \pot{H}{K}{ \hat{s} + q \oslash \hat{r} } 
    \\
    &\stackrel{(f)}{=} \;
    \pot{H+1}{K}{\hat{s}},
\end{align*}
where the steps are justified as follows:
\begin{enumerate}[label={$(\alph*)$}]
    \item 
    Follows from \eqref{eq:proof_of_coordinate_wise_monotonicity_inductive_step_value_functions_s}.
    \item 
    Holds since the minimizing $r$ yields an objective no larger than that induced by any $\hat{r}$.  
    \item 
    Follows from the choice of $\bar{q}$ in \eqref{eq:proof_of_coordinate_wise_monotonicity_def_of_bar_q}.
    \item 
    Follows from the induction hypothesis on $H$. 
    In particular, since \(s \prec \hat{s} \), it holds that
    \[
        s + \bar{q} \oslash \hat{r} \prec \hat{s} + \bar{q} \oslash \hat{r},
    \] 
    and thus, by the induction hypothesis,
    \[
        \pot{H}{K}{ s + \bar{q} \oslash \hat{r} } < \pot{H}{K}{ \hat{s} + \bar{q} \oslash \hat{r} }.
    \]
    \item 
    Holds since taking the maximum over $q$, with $\hat{s}$ and $\hat{r}$ fixed, can only increase the value.
    \item 
    Follows from the choice of $\hat{r}$ as one that satisfies \eqref{eq:monotonicity_of_value_function_b}.
\end{enumerate}
This establishes that \( \pot{H+1}{K}{s} < \pot{H+1}{K}{\hat{s}} \), completing the proof.
\end{itemize}
\end{proof}

\subsubsection{Proof of Lemma \ref{lemma:cw_weak_m}}

\begin{proof}[Proof of \lemmaref{lemma:cw_weak_m}]
    Let \( \hat{s}, s \in \Rdim{K} \) be such that \( \hat{s} \succeq s \).  
    For the case $H=0$, it holds that
    \begin{equation*}
        \pot{0}{K}{\hat{s}}
        \eqdef \;
        \max_{k \in [K]} \hat{s}(k) 
        \geq \;
        \max_{k \in [K]} s(k) 
        = \;
        \pot{0}{K}{s}.
    \end{equation*}
    Assume $H \geq 1$. 
    If $\hat{s} = s$ the statement is trivial.
    Otherwise, since $\hat{s} \succ s$, the result follows from \lemmaref{lemma:cw_strict_m}.
\end{proof}






\subsection{Proof of Lemma \ref{lemma:proof_opt_bookmaker_under_convexity}}
\label{appendix:proof_opt_bookmaker_under_convexity}

\begin{proof}[Proof of \lemmaref{lemma:proof_opt_bookmaker_under_convexity}]
    Let $H \geq 1,\, K \geq 2$ and $s \in \Rdim{K}$.
    The case $H=1$  is treated in \lemmaref{lemma:nash_last_round}, and for $K=1$ the result follows immediately.
    By \lemmaref{lemma:value_function_if_convex}, there exists $r \in \corr_H(s)$ for which
    \begin{equation*}
        \pot{H}{K}{s} = \max_{k \in [K]} \pot{H-1}{K}{s + \basis{k} \oslash r}.
    \end{equation*}
    By coordinate-wise strict monotonicity (\lemmaref{lemma:cw_strict_m}),
    there exists vector $u \in \Rpplus{K}$ such that 
    \begin{equation} \label{eq:opt_bookmaker_def_of_u}
        \pot{ H - 1 }{K}{s + \basis{k} \oslash r}
        = \pot{ H -1 }{K}{s} + u(k)  \quad \forall k \in [K].
    \end{equation}
    Assume, towards a contradiction, 
    that $r$ does not satisfy \eqref{eq:main_results_thm_the_game_dynamics};
    that is, there exists $i \in \nset{K}$ and $\varepsilon > 0$ such that
    \begin{equation}
        \label{eq:definition_of_kappa}
        \max_{k \in \nset{K}} u(k) - u(i) = \varepsilon.
    \end{equation}
    Relying on the continuity of the value function (\lemmaref{lemma:continuity_of_the_value_function})
    and the fact that 
    \begin{equation*}
        \lim_{r(i) \to 0} \pot{ H -1 }{K}{s + \frac{\basis{i}}{\vecind{r}{i}}} = \infty,
    \end{equation*}
    the intermediate value theorem guarantees the existence of a scalar 
    \(0 < \tilde{r} < r(i) \) for which
    \begin{equation}
        \label{eq:definition_of_new_tilde_r}
        \pot{ H -1 }{K}{s + \frac{\basis{i}}{\tilde{r}}}
        = \pot{ H -1 }{K}{s} + u(i) + \frac{\varepsilon}{2}.
    \end{equation}
    We construct a new action $\hat{r}$ as follows:
    \begin{align*}
        \hat{r}(k) = 
        \begin{cases}
            \; \tilde{r} & \text{if } k = i, \\[5pt]
            \; r(k) + \displaystyle\frac{r(i) - \tilde{r} }{K-1} & \text{if } k \neq i.
        \end{cases} 
    \end{align*}
    It is easy to verify that $\hat{r} \in \simplex{K-1}$.
    By acting with $\hat{r}$ the bookmaker's loss decreases:
    \begin{itemize}
    \item 
    \emph{For $k = i$}: 
    \begin{align*}
        \pot{ H -1 }{K}{s + \frac{\basis{i}}{\hat{r}(i)}} 
         &\stackrel{(a)}{=} 
        \pot{ H-1 }{K}{s} + u(i) + \frac{\varepsilon}{2} 
        \\
        &\stackrel{(b)}{ < } 
        \pot{ H -1 }{K}{s} + \max_{k \in \nset{K}} u(k),
    \end{align*}
    where $(a)$ follows from our choice of $\hat{r}(i) = \tilde{r}$ to satisfy \eqref{eq:definition_of_new_tilde_r},
    and $(b)$ follows from \eqref{eq:definition_of_kappa}, verifying a gap of $\frac{\varepsilon}{2} > 0$.
    \item 
    \emph{For $k \in \nset{K} \setminus \{i\}$}:
    \begin{align*}
        \pot{ H -1}{K}{s + \frac{\basis{k}}{\hat{r}(k)}}
        &\stackrel{(a)}{<} 
        \pot{ H -1}{K}{s + \frac{\basis{k}}{r(k)}}
        \\
        &\stackrel{(b)}{\leq} 
        \pot{ H -1}{K}{s} + \max_{k \in \nset{K}} u(k),
    \end{align*}
    where $(a)$ follows from coordinate-wise strict monotonicity (\lemmaref{lemma:cw_strict_m})
    combined with the fact that \( \hat{r}(k) > r(k) \),
    and $(b)$ follows from \eqref{eq:opt_bookmaker_def_of_u}.
    \end{itemize}
    It follows that $r$ is suboptimal, contradicting the optimality assumption.    


    It remains to show that the optimal bookmaking action is unique.
    Let $\optr, \hat{r} \in \corr_H(s)$ be two vectors that satisfy \eqref{eq:main_results_thm_the_game_dynamics}.
    I.e., 
    \[
        \pot{ H-1 }{K}{s + \frac{\basis{k}}{\optr(k)}} 
        = \pot{ H-1 }{K}{s + \frac{\basis{k}}{r(k)}} \quad \forall k \in [K].
    \]
    Suppose, for the sake of contradiction,  
    that there exists $k \in [K]$ such that $\optr(k) \neq r(k)$,
    and without loss of generality, assume $r(k) > \optr(k)$.
    By coordinate-wise strict monotonicity (\lemmaref{lemma:cw_strict_m}),
    it follows that
    \[
        \pot{ H-1 }{K}{s + \frac{\basis{k}}{\optr(k)}} 
        < \pot{ H-1 }{K}{s + \frac{\basis{k}}{r(k)}},
    \]
    contradicting the optimality of $r$.
\end{proof}






















\section{Proof of Lemma \ref{lemma:main_lemma_in_conditions}}
\label{appendix:value_vectors}


In this section, we prove \lemmaref{lemma:main_lemma_in_conditions}, which establishes necessary constraints for $H$-achievable vectors.
We begin by examining the partial derivatives of the polynomial $\denomfunction{H}{K}$, defined in \eqref{eq:main_results_def_of_denom_poly},
as presented in the following lemma.
\begin{lemma}[Partial Derivatives of $\denomfunction{H}{K}$] \label{lemma:der_of_denom}
For every \(H, K \in\Nplus\),
\begin{enumerate}[label={\arabic*.}, ref={\ref{lemma:der_of_denom}.\arabic*}]
\item \label{lemma:partial_derivatives_of_denom_1}
$\denomfunction{H}{K}$ is an infinitely differentiable function.

\item   \label{lemma:partial_derivatives_of_denom_2}
For every \(m \in \nset{K}\) and \( \mathfrak{I} \in \binom{\nset{K}}{m} \) 
\begin{align*}
    \frac{ \partial^m  \denomfunction{H}{K}}{\partial^m v_{\mathfrak{I}} } (v)
    = \denom{H}{K-m}{v\minind{\mathfrak{I}}},
\end{align*}
where for \( \mathfrak{I} = \{ i_1, \ldots, i_m \} \) the expression \( \partial^m v_{\mathfrak{I}} \) 
stands for \( \partial v(i_1) \ldots \partial v(i_m) \).

\item \label{lemma:partial_derivatives_of_denom_3}
For every \(k\in[K]\) and $m > 1$, 
\[
    \frac{\partial^m \denomfunction{H}{K}}{\partial v(k)^m}\, (v) = 0.
\]
\end{enumerate}
\end{lemma}
The proof of \lemmaref{lemma:der_of_denom} is provided in \appendixref{appendix:technical_C}
and builds on the recurrence relation established in \lemmaref{lemma:recurrence_relation_or_the_denom}:
\[
     \denom{ H }{K}{v} = \vecind{v}{k} \cdot \denomfunction{ H }{K-1}( v\minind{k} ) - H \cdot \denomfunction{ H-1 }{K-1}(v\minind{k} ),
\]
for all $H,K \in \Nplus$.


For the analysis, we use an equivalent form of the polynomial \(\denomfunction{H}{K}\), given by
\begin{equation}
  \label{eq:def_of_ppoly_explicit}
  \denom{H}{K}{v}
  = \sum_{m=0}^{K} (-1)^m \fallingfact{H}{m}\,\esp{K-m}{v}
\end{equation}
for all $H,K\in\Nfield$, which follows from \lemmaref{lemma:falling_factorial_identities_3}.
For convenience, we introduce an alternative notation for the polynomial \(\denomfunction{H}{K}\).
For $H \in \Nplus$ and $K \in \Nfield$, define the polynomial
\begin{equation}
    \label{eq:def_of_num_poly}
    \num{H}{K}{v} \; \eqdef \; H \cdot \denom{H-1}{K}{v}.
\end{equation}
This allows us to express \lemmaref{lemma:recurrence_relation_or_the_denom} in the following equivalent form:  
\begin{equation}    
    \label{eq:appendix_expansion_of_denom}
     \denom{ H }{K}{v} = \vecind{v}{k} \cdot \denomfunction{ H }{K-1}( v\minind{k} ) - \numfunction{ H }{K-1}(v\minind{k} ),
\end{equation}
for all \(H,K \in \Nplus \). 


We prove \lemmaref{lemma:proof_of_bp_2} using the equivalent from of \eqref{eq:necessary_conditions_proof_value_of_v_k},
expressed with the notation $\num{H}{K}{v}$:
\begin{equation*} 
    \vecind{v}{k} 
    = \frac{
        \num{ H }{K-1}{v\minind{k}}
    }{
        \denom{ H }{K-1}{v\minind{k}}
    }.
\end{equation*}
To prove \lemmaref{lemma:proof_of_bp_3}, we will show that
\begin{equation} \label{eq:derivation_of_proof_of_bp_3}
    \textstyle \forall\, m \in [K],\; \forall \, \mathfrak{I} \in \binom{\nset{K}}{m}, \quad \denom{H}{K-m}{v\minind{\mathfrak{I}}} > 0.
\end{equation}
The following lemma establishes that this condition implies the same result:
\begin{lemma} \label{lemma:derivation_of_proof_of_bp_3}
    Let \(H,K\in\Nplus\) and \(v\in\Rdim{K}\).  
    If \(v\) satisfies the constraint in \lemmaref{lemma:proof_of_bp_2}, then the positivity condition  
    \eqref{eq:derivation_of_proof_of_bp_3} implies that \(v\) also satisfies the constraint in \lemmaref{lemma:proof_of_bp_3}.
\end{lemma}
\begin{proof}[Proof of \lemmaref{lemma:derivation_of_proof_of_bp_3}] 
For a fixed $k \in [K]$, it holds that
\begin{equation} \label{eq:proof_of_thm_partial_derivative}
    \frac{ \partial  \denomfunction{H}{K}}{\partial v(k) } (v)
    \stackrel{(a)}{=} \denom{H}{K-1}{v\minind{k}}  
    \stackrel{(b)}{>} 0\,,
\end{equation}
where $(a)$ follows from \lemmaref{lemma:partial_derivatives_of_denom_2} and $(b)$ follows by \eqref{eq:derivation_of_proof_of_bp_3}.
Thus, 
\begin{itemize}
    \item By \lemmaref{lemma:proof_of_bp_2}, $\denom{H}{K}{v} = 0$ .
    \item By \eqref{eq:proof_of_thm_partial_derivative}, \( \nabla \denom{H}{K}{v} \) is a strictly positive vector.
    \item By \lemmaref{lemma:partial_derivatives_of_denom_3}, for every \(k\in[K]\) and $m > 1$, 
    \[
        \frac{\partial^m \denomfunction{H}{K}}{\partial v(k)^m}\, (v) = 0,
    \]
    indicating \(\denomfunction{H}{K}\) has no concavity along any axis.
\end{itemize}
We conclude that for all \(  u \in \Rdim{K}, \ \ u \succ v \implies \denom{H}{K}{u} > 0 \),
as \lemmaref{lemma:proof_of_bp_3} states.
\end{proof}


The following lemma provides a lower bound on any $H$-achievable vector.
\begin{lemma}[Lower Bound on $H$-Achievable Vectors] \label{lemma:lower_bound_for_value_vectors}  
    For all $H,K \in \Nplus$, if $v \in \vvset{H,K}$ then $v \succeq \univec{H}{K}$.
    Moreover, when $K>1$, the inequality is strict: $v \succ \univec{H}{K}$.
\end{lemma}
This lower bound follows from the fact that the gambler may commit to a single outcome in each of the remaining $H$ rounds.
According to the definition of the ESP (\definitionref{def:esp}), it follows that for any $H$-achievable vector $v$, 
\begin{equation} \label{eq:pos_esp}
    \textstyle \forall\, m \in [K],\; \forall \, \mathfrak{I} \in \binom{\nset{K}}{m}, \quad \esp{K-m}{v\minind{\mathfrak{I}}} > 0.
\end{equation}
Consequently, throughout the proof of \lemmaref{lemma:main_lemma_in_conditions}, we assume that no division by zero occurs when dividing by sums or products of elements of $v$.
A formal proof of \lemmaref{lemma:lower_bound_for_value_vectors} is provided in \appendixref{appendix:technical_C}.




\begin{proof}[Proof of \lemmaref{lemma:main_lemma_in_conditions}]
The case $K=1$ is immediate from \definitionref{def:bpf}; 
for completeness, a formal proof is provided in \appendixref{appendix:technical_C}.  
We then consider \(K\ge2\), and prove by induction on \(H\).


\paragraph{Base case ($H=1$).}
If $v \in \vvset{1,K}$ then, by \definitionref{def:bpf}, there exists $r \in \Rdim{K}$ such that
\begin{enumerate}[label=1.\roman*., ref=1.\roman*]
    \item \label{base_case_condition_1} 
    $\sum_{k=1}^K \vecind{r}{k} = 1$.

    \item \label{base_case_condition_3} 
    $\forall k \in \nset{K}, \; \vecind{v}{k} = \frac{1}{\vecind{r}{k}}$.
\end{enumerate}
The following hold for every $k\in [K]$:
\begin{align}  
    \denom{0}{K}{v} &= \esp{K}{v} \label{eq:base_denom_0_K}
    \\
    \denom{0}{K-1}{ v\minind{k} } &= \esp{K-1}{ v\minind{k} }  \label{eq:base_denom_0_K-1}
    \\
    \denom{1}{K-1}{ v\minind{k} } &= 
        \textstyle\prod_{\indneq{i}{\nset{K}}{k}} \vecind{v}{i} \left(1 - \sum_{\indneq{j}{\nset{K}}{k}} \frac{1}{\vecind{v}{j}}\right)  \label{eq:base_denom_1_K-1}
    \\
    \num{1}{K-1}{ v\minind{k} } &= \esp{K-1}{ v\minind{k} } \label{eq:base_num_1_K-1}
\end{align}
% =========================================================================================================
% =========================================================================================================
% =========================================================================================================
Condition \ref{base_case_condition_3} is satisfied if and only if
\begin{equation}
    \label{eq:proof_of_bpe_r_equation}
    \forall k \in [K] \quad 
    \vecind{r}{k} 
    = \frac{1}{\vecind{v}{k}}.
\end{equation}
For every $k \in [K]$, it holds that 
\begin{align*}
    \frac{1}{\vecind{v}{k}} 
    &\stackrel{(a)}{=} \frac{
        \esp{K-1}{v\minind{k}}
    }{
        \esp{K}{v}
    }
    \\
    &\stackrel{(b)}{=} \frac{
        \denom{0}{K-1}{ v\minind{k} }
    }{
        \denom{0}{K}{v}
    },
\end{align*}
where  $(a)$ follows from \definitionref{def:esp} of the ESP, 
and $(b)$ follows from \eqref{eq:base_denom_0_K-1} and \eqref{eq:base_denom_0_K}.
Therefore, \lemmaref{lemma:proof_of_bp_1} holds for the base case.


% =========================================================================================================
% =========================================================================================================
% =========================================================================================================


The vector $r$, which is defined as in \eqref{eq:proof_of_bpe_r_equation}, should satisfy Condition \ref{base_case_condition_1}; i.e.,
\begin{equation} \label{eq:proof_of_bpe_base_case_sum_of_r_by_v}    
    \sum_{k \in [K]} \frac{1}{v(k)} = 1.
\end{equation}
For every $k \in \nset{K}$, it holds that
\begin{align*}
    \frac{1}{\vecind{v}{k}} 
    &= \;
    1 - \sum_{\indneq{j}{\nset{K}}{k}} \frac{1}{\vecind{v}{j}}
    \\
    &= \;
    \frac{ \prod_{\indneq{i}{\nset{K}}{k}} \vecind{v}{i} }
            { \prod_{\indneq{i}{\nset{K}}{k}} \vecind{v}{i} }
      \left(1 -  \sum_{\indneq{j}{\nset{K}}{k}} \frac{1}{\vecind{v}{j}} \right)
    \\ 
    &= \;  
    \frac{\denom{1}{K-1}{ v\minind{k} }}{\num{1}{K-1}{ v\minind{k} }},
\end{align*}
where the last equality follows from \eqref{eq:base_denom_1_K-1} and \eqref{eq:base_num_1_K-1}.
Therefore,
\begin{equation}
    \label{eq:value_of_v_k_in_terms_of_N_and_D_base_case}
    \vecind{v}{k} = \frac{\num{1}{K-1}{ v\minind{k} }}{\denom{1}{K-1}{ v\minind{k} }},
\end{equation}
and \lemmaref{lemma:proof_of_bp_2} holds for the base case.


% =========================================================================================================
% =========================================================================================================
% =========================================================================================================

We prove that \eqref{eq:derivation_of_proof_of_bp_3} holds by induction on \(m\).  
Combined with \lemmaref{lemma:derivation_of_proof_of_bp_3}, this completes the proof of \lemmaref{lemma:proof_of_bp_3} for the base case.
\begin{itemize}
\item 
\emph{Base case} \(( m = 1 )\):
For every $k \in [K]$, it holds that  
\begin{align*}
    0 
    &\stackrel{(a)}{=} 
    \denom{1}{K}{v}
    \\
    &\stackrel{(b)}{=} v(k) \cdot \denom{1}{K-1}{ v\minind{k} } - \num{1}{K-1}{ v\minind{k} }
    \\ 
    &\stackrel{(c)}{=}  v(k) \cdot \denom{1}{K-1}{ v\minind{k} } - \esp{K-1}{v\minind{k}}
\end{align*}
where 
$(a)$ follows from \lemmaref{lemma:proof_of_bp_2}; 
$(b)$ follows from the identity in \eqref{eq:appendix_expansion_of_denom};
and $(c)$ follows from \eqref{eq:base_num_1_K-1}.
By \eqref{eq:pos_esp}, both $v(k)$ and $\esp{K-1}{v\minind{k}}$ are $> 0$, 
and therefore,
\( \mathcal{D}_{1,K-1}\left( v\minind{k} \right) \) 
must be $ > 0$. 

\item
\emph{Inductive step} \( (m \to m+1) \):
Let \(m \in [K-1] \,, \mathfrak{I} \in \binom{\nset{K}}{m} \) and \( k \in \nset{K} \setminus \mathfrak{I} \) be fixed.
By \eqref{eq:appendix_expansion_of_denom}, it holds that
\begin{equation*}
    \denom{1}{K-m}{v\minind{\mathfrak{I}}} 
    = v(k) \cdot \denom{1}{K-(m+1)}{ v\minind{\mathfrak{I} \cup \{k\}} } 
        - \esp{K-(m+1)}{ v\minind{\mathfrak{I} \cup \{k\}} }.
\end{equation*}
From the induction hypothesis (on $m$) The LHS of the equation is positive. 
By \eqref{eq:pos_esp}, the term
\( \denom{1}{K-(m+1)}{ v\minind{\mathfrak{I} \cup \{k\}} } \)
must be $ > 0$. 
\end{itemize}


% =========================================================================================================
% =========================================================================================================
% =========================================================================================================
% =========================================================================================================
% =========================================================================================================
% =========================================================================================================
% =========================================================================================================
% =========================================================================================================
% =========================================================================================================


\bigbreak

\paragraph{Inductive step ($H \to H+1$).}
If $v \in \vvset{H+1,K}$ then
there exists an action $r \in \Rdim{K}$ such that 
\begin{enumerate}[label=2.\roman*., ref=2.\roman*]
    \item \label{condition_induction_1} 
    $\sum_{k=1}^K \vecind{r}{k} = 1$.

    \item \label{condition_induction_3} 
    For every $k \in \nset{K}$, the vector $\prescript{k}{}{v}$, defined as
    \begin{equation}
        \label{eq:lemma_definition_of_k_v}
        \vecind{\prescript{k}{}{v}}{i}
        \eqdef 
        \begin{cases}
            \vecind{v}{i} - \frac{1}{\vecind{r}{k}} & \text{if } k = i, \\
            \vecind{v}{i} & \text{otherwise}.
        \end{cases} 
    \end{equation} 
    is $H$-achievable.
\end{enumerate}
Note that 
\begin{equation} \label{eq:helper_eq_proof_res}
    \prescript{k}{}{v}\minind{k} = v\minind{k}, \quad \forall k \in [K].
\end{equation}
For every $k \in [K]$, it holds that
\begin{align}
    0 
    &\stackrel{(a)}{=} \;
    \denom{H}{K} {\prescript{k}{}{v} }  \label{eq:proof_of_bpe_inductive_step_eq_1}
    \\
    &\stackrel{(b)}{=} \; 
     \vecind{\prescript{k}{}{v}}{k} \cdot \denom{H}{K-1}{ \prescript{k}{}{v}\minind{k} }
        - \num{H}{K-1}{ \prescript{k}{}{v}\minind{k} } \nonumber
    \\ 
    &\stackrel{(c)}{=} \;
    \left( \vecind{v}{k} - \frac{1}{\vecind{r}{k}} \right)  \cdot \denom{H}{K-1}{ v\minind{k} }
        - \num{H}{K-1}{ v\minind{k} } \nonumber
    \\ 
    &= \;
    \vecind{v}{k} \cdot \denom{H}{K-1}{ v\minind{k} } - \num{H}{K-1}{ v\minind{k} }
        - \frac{\denom{H}{K-1}{ v\minind{k} }}{\vecind{r}{k}} \nonumber
    \\ 
    &\stackrel{(d)}{=} \;
    \denom{H}{K}{ v } - \frac{\denom{H}{K-1}{ v\minind{k} }}{\vecind{r}{k}},  \label{eq:last_eq_in_proof_of_bpe_inductive_step_eq_1}
\end{align}
where the steps are justified as follows:
\begin{enumerate}[label={$(\alph*)$}]
    \item Follows from Condition \ref{condition_induction_3} and the induction hypothesis on \lemmaref{lemma:proof_of_bp_2}.
    \item Follow from the identity in \eqref{eq:appendix_expansion_of_denom}.
    \item Follow from the definition of the vector $\prescript{k}{}{v}$ in \eqref{eq:lemma_definition_of_k_v} and \eqref{eq:helper_eq_proof_res}.
    \item Follow from the identity in \eqref{eq:appendix_expansion_of_denom}.
\end{enumerate}
Condition \ref{condition_induction_3}, \eqref{eq:helper_eq_proof_res} and the induction hypothesis on \lemmaref{lemma:proof_of_bp_3}, 
imply
\begin{equation}
    \label{eq:proof_of_bpe_inductive_step_eq_2}
    \denom{H}{K-1}{v\minind{k}} > 0 \quad \forall k \in [K].
\end{equation}
By \eqref{eq:last_eq_in_proof_of_bpe_inductive_step_eq_1}, \eqref{eq:proof_of_bpe_inductive_step_eq_2} 
and the fact that $r(k)$ must be $>0$, we conclude that  
\begin{equation}
    \label{eq:proof_of_bpe_denom_in_r_is_non_zero}
   \denom{H}{K}{v} \neq 0,
\end{equation}
and we can divide by this term.
We obtain that $r$ is given by
\begin{equation}
    \label{eq:lemma_value_vector_inductive_step_formula_for_r}
    \vecind{r}{k} = \frac{
                \denom{ H }{K-1}{ v\minind{k} }
            }{
                \denom{ H }{K}{v}
            }
        \quad \quad \forall k \in \nset{K}.
\end{equation}
This completes the inductive step for \lemmaref{lemma:proof_of_bp_1}.



% =========================================================================================================
% =========================================================================================================
% =========================================================================================================




Let $k \in \nset{K}$ be fixed and let $r$ be a vector that is generated as in
\eqref{eq:lemma_value_vector_inductive_step_formula_for_r}.
$r$ satisfies Condition \ref{condition_induction_3} if and only if 
\begin{equation}
    \label{eq:semi_value_vector_inductive_step_r_k_as_sum}
    r(k) = 1 - \sum_{\indneq{i}{\nset{K}}{k}} r(i).
\end{equation}
By \eqref{eq:proof_of_bpe_denom_in_r_is_non_zero}, \eqref{eq:semi_value_vector_inductive_step_r_k_as_sum} holds if and only if 
\begin{equation}
    \label{eq:semi_value_vector_inductive_step_r_k_as_sum_mult}
    \denom{H}{K}{v} \cdot r(k) = \denom{H}{K}{v} - \denom{H}{K}{v} \sum_{\indneq{i}{\nset{K}}{k}} r(i).
\end{equation}
By \eqref{eq:lemma_value_vector_inductive_step_formula_for_r},
the LHS of \eqref{eq:semi_value_vector_inductive_step_r_k_as_sum_mult} is 
\(
    \denom{H}{K-1}{v\minind{k}},
\)
and for every $i \in \nset{K} \setminus \{k\}$,
\begin{align*}
    \denom{H}{K}{v} \cdot\vecind{r}{i} 
    = \;
    &\denom{H}{K-1}{v\minind{i}}
    \\
    = \;
    &\vecind{v}{k} \cdot \denom{H}{K-2}{v\minind{\{i,k\}}} - \num{H}{K-2}{v\minind{\{i,k\}}},
\end{align*}
where the second equality follows from the identity in \eqref{eq:appendix_expansion_of_denom}. 
Thus,
\begin{equation*}
    \denom{H}{K}{v} \sum_{\indneq{i}{\nset{K}}{k}} \vecind{r}{i} 
    = \vecind{v}{k}  \sum_{\indneq{i}{\nset{K}}{k}} \denom{H}{K-2}{v\minind{\{i,k\}}} 
        - \sum_{\indneq{i}{\nset{K}}{k}} \num{H}{K-2}{v\minind{\{i,k\}}},
\end{equation*}
and \eqref{eq:semi_value_vector_inductive_step_r_k_as_sum_mult} holds if and only if
\[
    \denom{H}{K-1}{v\minind{k}}
    = 
    \denom{H}{K}{v} - 
    \vecind{v}{k}  \sum_{\indneq{i}{\nset{K}}{k}} \denom{H}{K-2}{v\minind{\{i,k\}}} 
    +
    \sum_{\indneq{i}{\nset{K}}{k}} \num{H}{K-2}{v\minind{\{i,k\}}}
    .
\]
Further expanding $\denom{H}{K}{v}$ using \eqref{eq:appendix_expansion_of_denom} and rearrange, we get that
\begin{equation}
    \label{eq:proof_of_bp_inductive_step_part_2_main_eq}
    \mathtt{A} = v(k) \cdot \mathtt{B},
\end{equation}
with
\begin{align} 
    \mathtt{A} 
    &= 
    \denom{H}{K-1}{v\minind{k}}
        + \num{H}{K-1}{v\minind{k}}
        - \sum_{\indneq{i}{\nset{K}}{k}} \num{H}{K-2}{v\minind{\{i,k\}}},
    \label{eq:proof_of_bp_inductive_step_part_2_def_A}
    \\
    \mathtt{B} 
    &=
    \denom{H}{K-1}{v\minind{k}} - \sum_{\indneq{i}{\nset{K}}{k}} \denom{H}{K-2}{v\minind{\{i,k\}}}.
    \label{eq:proof_of_bp_inductive_step_part_2_def_B}
\end{align}
A simplification of 
\equationref{eq:proof_of_bp_inductive_step_part_2_def_A,eq:proof_of_bp_inductive_step_part_2_def_B}
is presented in 
\appendixref{appendix:proof_of_bp_inductive_step_part_2_simplification}, 
yielding:
\begin{equation}
    \label{eq:proof_of_bp_inductive_step_part_2_simplification}
    \mathtt{A} = \num{H+1}{K-1}{v\minind{k}} 
    \quad 
    \mathtt{B} = \denom{H+1}{K-1}{v\minind{k}}.
\end{equation}
Thus, \eqref{eq:proof_of_bp_inductive_step_part_2_main_eq} holds if and only if 
\begin{equation}
    \label{eq:proof_of_bp_inductive_step_part_2_main_eq_expanded}
     \num{H+1}{K-1}{v\minind{k}} = v(k) \cdot \denom{H+1}{K-1}{v\minind{k}}.
\end{equation}
The LHS of \eqref{eq:proof_of_bp_inductive_step_part_2_main_eq_expanded} $ \neq 0$;
otherwise, by \eqref{eq:def_of_num_poly}, it implies that
\(
    \denom{H}{K-1}{v\minind{k}} = 0
\), which contradicts \eqref{eq:proof_of_bpe_inductive_step_eq_2}.
By \lemmaref{lemma:lower_bound_for_value_vectors}, $v(k) > 0$. 
It follows that
\(
    \denom{H+1}{K-1}{v\minind{k}} \neq 0,
\)
allowing us to divide both sides of \eqref{eq:proof_of_bp_inductive_step_part_2_main_eq_expanded}, yielding  
\[
    v(k) = \frac{\num{H+1}{K-1}{v\minind{k}}}{\denom{H+1}{K-1}{v\minind{k}}}.
\]
This completes the inductive step for \lemmaref{lemma:proof_of_bp_2}.

% =========================================================================================================
% =========================================================================================================
% =========================================================================================================

We prove that \eqref{eq:derivation_of_proof_of_bp_3} holds by induction on \(m\).  
Combined with \lemmaref{lemma:derivation_of_proof_of_bp_3}, this completes the proof of \lemmaref{lemma:proof_of_bp_3}.
\begin{itemize}
\item
\emph{Base case} \(( m = 1 ) \):
For every $k \in [K]$, it holds that
\begin{align*}
    0 
    &\stackrel{(a)}{=} 
    \denom{H+1}{K}{v}
    \\ 
    &\stackrel{(b)}{=} 
    v(k) \cdot \denom{H+1}{K-1}{ v\minind{k} } - (H+1) \cdot \denom{H}{K-1}{ v\minind{k} }    
\end{align*}
where $(a)$ follows from \lemmaref{lemma:proof_of_bp_2} 
and $(b)$ follows from \lemmaref{lemma:recurrence_relation_or_the_denom}. 
By \eqref{eq:proof_of_bpe_inductive_step_eq_2} and \lemmaref{lemma:lower_bound_for_value_vectors},
 \( \denom{H+1}{K-1}{ v\minind{k} } \) must be $ > 0$. 

\item
\emph{Inductive step} \(( m \to m+1 )\):
Let $m \in [K-1]$,  \( \mathfrak{I} \in \binom{\nset{K}}{m}\) and $k \in \nset{K} \setminus \mathfrak{I}$ be fixed.
By the recurrence relation in \lemmaref{lemma:recurrence_relation_or_the_denom},
\[
    \denom{H+1}{K-m}{v\minind{\mathfrak{I}}} 
    =
     v(k) \cdot \denom{H+1}{K-(m+1)}{ v\minind{\mathfrak{I} \cup \{k\}} } 
        - (H+1) \cdot \denom{H}{K-(m+1)}{ {v}\minind{\mathfrak{I} \cup \{k\}} }
\]
By the induction hypothesis on $m$, the LHS of the equation is $> 0$.
By \lemmaref{lemma:lower_bound_for_value_vectors}, $v(k) > 0$.
Similarly to \eqref{eq:helper_eq_proof_res}, 
it holds that 
\(
    {v}\minind{\mathfrak{I} \cup \{k\}} = \prescript{k}{}{v}\minind{\mathfrak{I} \cup \{k\}}
\).
By Condition \ref{condition_induction_3} and the induction hypothesis (on $H$) on \lemmaref{lemma:proof_of_bp_3},
\(
    \denom{H}{K-(m+1)}{ {v}\minind{\mathfrak{I} \cup \{k\}} } > 0
\).
Therefore, the term \( \denom{H}{K-(m+1)}{ v\minind{\mathfrak{I} \cup \{k\}} } \) must be $ > 0$.
\end{itemize}
\end{proof}

\begin{remark} \label{remark:validity_of_r}
For every \( v \in \vvset{H, K} \), the vector \( r \) defined in \eqref{eq:optimal_odd_thm} is a valid probability distribution with non-zero entries. 
This follows from the structure of \( \vvset{H, K} \): for each such \( v \), \( r \) is the only choice that satisfies the necessary constraints. 
For completeness, an explicit proof is provided in \appendixref{appendix:validity_of_r}.
\end{remark}







