\subsection{Proof of Theorem \ref{theorem:regret_factor} (The Asymptotic Regret Factor)}
\label{appendix:proof_of_theorem_B}

To characterize the regret in \eqref{eq:main_results_optimal_loss_decomposition}, 
we begin by defining the polynomial 
\begin{equation}
    \label{eq:def_of_hatppoly}
   \hatppoly{T}{K}{x} \eqdef \ppoly{T}{K}{x+T}.
\end{equation}
By \theoremref{theorem:optimal_loss}, it holds that 
\begin{equation}
    \label{eq:optimal_loss_in_terms_of_hatppoly}
    \optimalloss{T}{K} = T + \argmaxroot{\hatppolyfunction{T}{K}}.
\end{equation}
Hence, the regret can be expressed as 
\begin{equation} \label{eq:appendix_def_of_regret}
    R_{T,K} = \argmaxroot{\hatppolyfunction{T}{K}}.
\end{equation}
We show in \appendixref{appendix:derivation_of_the_explicit_form_of_tilde_P} that 
$\hatppolyfunction{T}{K}$
can be written as
\begin{equation}
    \label{eq:expansion_of_hatppoly}
    \hatppoly{T}{K}{x} = \sum_{m=0}^{K} x^{K-m}\,\binom{K}{m}\left(\sum_{d=0}^{m} \sum_{i=0}^{d} (-1)^{d} \binom{m}{d}\, \stirling{d}{i}\, T^{m-(d-i)}\right),
\end{equation}
where $\stirling{\cdot}{\cdot}$ stands for the signed Stirling numbers of the first kind (see \definitionref{def:stirling_numbers_of_the_first_kind}).
We define the polynomial \(\betapolyfunction{T}{K}\) as
\[
    \betapoly{T}{K}{x} \,\eqdef\, \hatppoly{T}{K}{\sqrt{T} x}.
\]
Following \equationref{eq:optimal_loss_in_terms_of_hatppoly,eq:appendix_def_of_regret}, 
\[
    \optimalloss{T}{K} = T + \sqrt{T} \cdot\argmaxroot{\betapolyfunction{T}{K}},
\]
and 
\begin{equation}
    \label{eq:appendix_beta_def}
    \beta_{T,K} \eqdef \frac{R_{T,K}}{\sqrt{T}} = \argmaxroot{\betapolyfunction{T}{K}}.
\end{equation}
In \appendixref{appendix:derivation_of_the_explicit_form_of_betapoly} we show that
\begin{align}
    \betapoly{T}{K}{x} 
    &= 
    \sum_{m=0}^{K} x^{K-m}\,\binom{K}{m} \cdot T^{\frac{K}{2}} \cdot \widetilde{c}_{T,m}, 
    \label{eq:expnasion_of_betapoly}
    \\
    \text{where} \quad \quad
    \widetilde{c}_{T,m} &= 
    \sum_{n=0}^{m} T^{\frac{m}{2} - n} \sum_{d=0}^{m} (-1)^{d} \binom{m}{d}\, \stirling{d}{d-n}. \label{eq:expnasion_of_betapoly_coeff}
\end{align}
\begin{lemma} \label{lemma:max_power_of_T_in_betapoly}
    For all $m \in \Nfield$, the maximal power of $T$ in $\widetilde{c}_{T,m}$ is $\leq 0$.
    As a result, the maximal power of $T$ in $\betapolyfunction{T}{K}$ is at most $\frac{K}{2}$.
\end{lemma}
The proof of \lemmaref{lemma:max_power_of_T_in_betapoly} is deferred to \appendixref{appendix:proof_of_max_power_of_T_in_betapoly}.


As defined in \eqref{eq:regret_factor}, 
\(
    \beta_{K} = \lim_{T\to \infty} \beta_{T,K}
\).
By \eqref{eq:appendix_beta_def}, 
\(
    \beta_{K} = \argmaxroot{\lim_{T \to \infty} \betapolyfunction{T}{K}}
\).
With the established limit, we proceed to establish \theoremref{theorem:regret_factor}.
\begin{proof}[Proof of \theoremref{theorem:regret_factor}]
We prove  
\begin{equation} \label{eq:proof_of_thm_B_limit}
    \lim_{T\to \infty} \betapoly{T}{K}{x} = \hermp_K(x).
\end{equation}
By \lemmaref{lemma:max_power_of_T_in_betapoly}, 
the maximal power of $T$ in $\betapolyfunction{T}{K}$ is at most $\frac{K}{2}$.
The coefficient of $T^{\frac{K}{2}}$ in \eqref{eq:expnasion_of_betapoly}
contains the summand of $\widetilde{c}_{T,m}$  with $m = 2n$. 
Assuming that the coefficient of $T^{\frac{K}{2}}$ does not vanish, we have 
\begin{align*}
    \lim_{T\to \infty} \betapoly{T}{K}{x} 
    =
    & \sum_{n=0}^{\lfloor {K}/{2} \rfloor} x^{K-2n}\,\binom{K}{2n} \sum_{d=0}^{2n} (-1)^{d} \binom{2n}{d}\, \stirling{d}{d-n}  .
\end{align*}
As for $d < n$ it holds that $\stirling{d}{d-n} = 0$, we denote $d=n+m$, and obtain
\begin{align*}
    \lim_{T\to \infty} \betapoly{T}{K}{x} 
    &= \;
    \sum_{n=0}^{\lfloor {K}/{2} \rfloor} x^{K-2n}\,\binom{K}{2n} 
        \sum_{m=0}^{n} (-1)^{n+m} \binom{2n}{n+m}\, \stirling{n+m}{m}  
    \\
    &= \;
      K! \sum_{n=0}^{\lfloor {K}/{2} \rfloor} \frac{x^{K-2n} (-1)^{n}}{(K-2n)!(2n)!} 
        \, \sum_{m=0}^{n} (-1)^{m} \binom{2n}{n+m}\, \stirling{n+m}{m}.
\end{align*}
By \citet[][Theorem~1]{gould2015stirling},
\[
    \sum_{m=0}^{n} (-1)^{m} \binom{2n}{n+m}\, \stirling{n+m}{m} = \frac{(2n)!}{n! 2^n}.
\]
Therefore,
\begin{equation} \label{eq:last_eq_in_hermite_proof}
    \lim_{T\to \infty} \betapoly{T}{K}{x} 
    =  K!\,\sum_{n=0}^{\lfloor K/2 \rfloor} \frac{(-1)^{n}}{n!(K-2n)!}\, \frac{x^{K-2n}}{2^{n}}.
\end{equation}
The RHS of \eqref{eq:last_eq_in_hermite_proof} 
is precisely the $K$-th probabilist’s Hermite polynomial \(\hermp_K(x)\)
\citep[e.g.][Eq.~3]{patarroyo2020digressionhermitepolynomials}.
\end{proof}


\subsubsection{Proof of Lemma \ref{lemma:max_power_of_T_in_betapoly}}
\label{appendix:proof_of_max_power_of_T_in_betapoly}
We make use of the following two auxiliary results.

\begin{lemma}[Alternating Binomial Sum of Polynomials]
    \label{lemma:alternating_binomial_polynomial}
    Let \( P(x) \) be a polynomial of degree less than \( n \). 
    Then, the alternating sum of binomial coefficients weighted by \( P(j) \) satisfies the identity:
    \begin{equation}
        \sum_{j=0}^{n} (-1)^j \binom{n}{j} P(j) = 0.
    \end{equation}
\end{lemma}
\lemmaref{lemma:alternating_binomial_polynomial} follows from the theory of finite differences \cite[see][Ch.~2]{graham1994concrete}.


\begin{lemma}[Polynomiality of Stirling Numbers of the First Kind] 
    \label{lemma:polynomiality_of_stirling_numbers_of_the_first_kind}
    For a fixed \( n \in \Nfield \), there exists a polynomial \( G_n(d) \) of degree \( \leq 2n \) such that  
    \[
        \unstirling{d}{d-n} = G_n(d).
    \]
\end{lemma}
\lemmaref{lemma:polynomiality_of_stirling_numbers_of_the_first_kind} 
follows from the combinatorial interpretation of Stirling numbers and their polynomial nature
as established by \cite{GESSEL197824}.


\begin{proof}[Proof of \lemmaref{lemma:max_power_of_T_in_betapoly}]
    Let $0 \leq m \leq K$. 
    It holds that 
    \begin{align*}
    \widetilde{c}_{T,m} 
    \stackrel{(a)}{\eqdef}
    & \sum_{n=0}^{m} T^{\frac{m}{2} - n} \sum_{d=0}^{m} (-1)^{d} \binom{m}{d}\, \stirling{d}{d-n}
    \\
    \stackrel{(b)}{=}
    & \sum_{n=0}^{m} (-1)^{n} \, T^{\frac{m}{2} - n}  \sum_{d=0}^{m} (-1)^{d} \binom{m}{d}\, \unstirling{d}{d-n}
    \\
    \stackrel{(c)}{=}
    &\sum_{n=0}^{m} (-1)^n \, T^{\frac{m}{2} - n} \sum_{d=0}^{m} (-1)^{d} \binom{m}{d}\, G_n(d) ,
    \end{align*}
    where the steps are justified as follows: 
    \begin{enumerate}[label={$(\alph*)$}]
        \item Follows from the definition of the term $\widetilde{c}_{T,m}$ in
        \eqref{eq:expnasion_of_betapoly_coeff}.
        \item Follows from \definitionref{def:stirling_numbers_of_the_first_kind}, 
        where the signed Stirling numbers of the first kind are defined by
        \[
            \stirling{n}{k} = (-1)^{n-k} \unstirling{n}{k}.
        \]
        \item 
        Follows from \lemmaref{lemma:polynomiality_of_stirling_numbers_of_the_first_kind}, 
        which states that each term $\unstirling{d}{d-n}$ can be written as a polynomial $G_n(d)$ of degree at most $2n$.
    \end{enumerate}  
    Thus, if $\frac{m}{2} > n$, then $\text{deg}\left( G_n(d) \right) < m$,
    and by \lemmaref{lemma:alternating_binomial_polynomial} we obtain
    \begin{equation*}
         \sum_{d=0}^{m} (-1)^{d} \binom{m}{d}\, G_n(d) = 0.
    \end{equation*}
\end{proof}






\subsection{Proof of Remark \ref{remark:opt_loss_grows_to_infinity_for_fixed_T}}
\label{appendix:proof_remark_opt_loss_grows_to_infinity_for_fixed_T}

\begin{lemma} \label{lemma:simulating_bookmaker_m_times}
    For any $T, K, m \in \Nplus$ it holds that $\optimalloss{mT}{K} \leq m \cdot \optimalloss{T}{K}$.
\end{lemma}

\begin{proof}[Proof of Lemma~\ref{lemma:simulating_bookmaker_m_times}]
Fix \(T, K, m \in \Nplus\), and let \(\bm^T\) be an optimal bookmaker whose loss is \(L^{\star}_{T,K}\).  
Construct a bookmaker \(\tilde\bm\) for horizon \(mT\) by applying \(\bm^T\) independently to each of the \(m\) disjoint blocks of \(T\) rounds.  
That is, partition the gambler’s sequence \(q_{1},\dots,q_{mT}\) into \(m\) segments and apply \(\bm^T\) to each, starting from a zero state.  
The total loss of \(\tilde\bm\) is at most \(m \cdot L^{\star}_{T,K}\),  
and thus \(L^{\star}_{mT,K} \leq m \cdot L^{\star}_{T,K}\), by the optimality of the loss \( L^{\star}_{mT,K} \).
\end{proof}

\begin{proof}[Proof of \remarkref{remark:opt_loss_grows_to_infinity_for_fixed_T}]
Assume, towards a contradiction, there exists \( \widehat{T} \in \Nplus \) and \(C \in \Rfield \)
such that 
\[
    \lim_{K \to \infty} \frac{R_{\widehat{T},K}}{\sqrt{\widehat{T}}} = C.
\]
Since adding an outcome to the game can only increase the bookmaker's optimal loss,
\begin{align}
    \label{eq:false_assumption_on_bound_of_optimal_loss}
    \forall K \in \Nplus \quad 
    \optimalloss{\widehat{T}}{K} \leq \widehat{T} + C \sqrt{\widehat{T}}
\end{align}
\theoremref{theorem:regret_factor} states that
\begin{equation} \label{eq:lim_H_eq_proof_of_remark_1}
      \forall K \in \Nplus \quad \lim_{T \to \infty} \beta_{T,K} = \argmaxroot{\hermp_K}.
\end{equation}
Lower bound on the RHS of \eqref{eq:lim_H_eq_proof_of_remark_1} 
\citep[e.g.,][]{krasikov2004bounds} 
implies there exist \( m \in \Nplus \) for which 
\begin{equation} \label{eq:lower_bound_on_the_redundancy}
    \forall K \in \Nplus \quad \beta_{m \widehat{T}, \, K} \geq \sqrt{K}
\end{equation}
Define 
\begin{equation} \label{eq:def_of_hat_K_proof_of_remark_1}
    \widehat{K} \eqdef \left\lceil  m {C}^{2} \right\rceil + 1,
\end{equation}
and consider the optimal bookmaking loss in a game with $\widehat{K}$ outcomes and $m\widehat{T}$ rounds:
\begin{align*}
    \optimalloss{m\widehat{T}}{\widehat{K}} 
    &\stackrel{(a)}{\leq} \;
    m \cdot \optimalloss{\widehat{T}}{\widehat{K}}
    \\
    &\stackrel{(b)}{\leq} \;
    m \cdot \left(
        \widehat{T} + C \sqrt{\widehat{T}}
    \right) 
    \\ 
    &= \;
    m \widehat{T} + \sqrt{m {C}^{2} } \sqrt{m \widehat{T}} 
    \\
    &\stackrel{(c)}{<} \;
    m \widehat{T} + \sqrt{\widehat{K}} \sqrt{m \widehat{T}}
    \\
    &\stackrel{(d)}{\leq} \;
    m \widehat{T} + \beta_{m\widehat{T}, \widehat{K}} \sqrt{m \widehat{T}}
    \\
    &=   \;
    \optimalloss{m\widehat{T}}{\widehat{K}},
\end{align*}
where $(a)$ follows from \lemmaref{lemma:simulating_bookmaker_m_times}, stated above;
$(b)$ follows from the upper bound on $\optimalloss{\widehat{T}}{\widehat{K}}$ in \eqref{eq:false_assumption_on_bound_of_optimal_loss};
$(c)$ follows from our definition of $\widehat{K}$ in \eqref{eq:def_of_hat_K_proof_of_remark_1};
and, $(d)$ follows from the lower bound on the regret factor $ \beta_{m\widehat{T}, \widehat{K}}$ in \eqref{eq:lower_bound_on_the_redundancy}.
This yields a contradiction, completing the argument.
\end{proof}





\subsection{Proof of Remark \ref{remark:all_polys_are_denom}}
\label{appendix:proof_of_all_polys_are_denom}

\begin{proof}[Proof of \remarkref{remark:all_polys_are_denom}]
We prove that evaluating $\denomfunction{H}{K}$ at $\univec{x}{K} - s$, 
as defined in \eqref{eq:remark_def_of_biaseddenom}, 
yields the polynomial expression in \eqref{eq:biased_denominator_function}.
\begin{align*}
    \denom{ H }{K}{\univec{ x }{K} - s} 
    &\stackrel{(a)}{=} 
    \sum_{j=0}^{K} (-1)^{K-j} \fallingfact{ H }{K-j} \esp{j}{\univec{ x }{K} - s}\\
    &\stackrel{(b)}{=} 
    \sum_{j=0}^{K} (-1)^{K-j} \fallingfact{ H }{K-j} 
        \sum_{i=0}^{j} (-1)^{i} \esp{i}{s} \binom{K - i}{j - i} x^{j - i}\\
    &= \sum_{j=0}^{K} \sum_{i=0}^{j} 
        (-1)^{K-(j-i)} \fallingfact{ H }{K-j} \esp{i}{s} \binom{K - i}{j - i} x^{j - i}\\ 
    &\stackrel{(c)}= 
    \sum_{j=0}^{K} \sum_{n=0}^{j} 
        (-1)^{K-n} \fallingfact{ H }{K-j} \esp{j - n}{s} \binom{K - j + n}{n} x^{n}\\ 
    &= \sum_{n=0}^{K} (-1)^{K-n} \left( \sum_{j=n}^{K} 
         \fallingfact{ H }{K-j} \esp{j - n}{s} \binom{K - (j - n)}{n} 
        \right) x^{n}\\ 
    &\stackrel{(d)}{=} \sum_{m=0}^{K} (-1)^{m} \left( \sum_{j=K-m}^{K} 
        \fallingfact{ H }{K-j} \esp{j - (K - m)}{s} \binom{K - j + K - m}{K-m} 
        \right) x^{K-m} \\ 
    &\stackrel{(e)}{=} \sum_{m=0}^{K} 
        \left(  (-1)^{m} \sum_{n=0}^{m} 
        \fallingfact{ H }{m-n} \binom{K - n}{K-m} \esp{n}{s} 
        \right) x^{K-m},
\end{align*}
where: $(a)$ uses the definition of $\denomfunction{H}{K}$ in \eqref{eq:def_of_ppoly_explicit}; 
$(b)$ follows from \lemmaref{lemma:elementary_symmetric_polynomial_with_shift};
$(c)$ substitutes $n = j - i$;
$(d)$ by the substitution $m = K - n$;
and $(e)$ via the change of variable $n = j - K + m$.
Accordingly, we obtain the expression stated in \eqref{eq:biased_denominator_function}.
\end{proof}









\subsection{Proof of Remark \ref{remark:algo_complexity} (Algorithm \ref{algo:optimal_bookmaking} Computational Complexity)}
\label{appendix:complexity_analysis}

In this section, we analyze the computational complexity of \algorithmref{algo:optimal_bookmaking}.

\begin{remark}  \label{remark:esp_fft}
    All the elementary symmetric polynomials of a vector in $\Rdim{K}$ 
    can be computed in \( O(K \log K) \) 
    time using FFT-based polynomial multiplication techniques 
    \citep[][Thm.~7.1]{harvey2021integer,ben2021elliptic}.
    We refer to this method as the \algfont{FFT-ESP} algorithm.
\end{remark}

We first address the efficient computation of partial elementary symmetric polynomials, 
handled by \algorithmref{algo:partial_esps}.
\begin{algorithm2e}[htbp]
\caption{Partial Elementary Symmetric Polynomials}
\label{algo:partial_esps}
\SetKw{Initialization}{Initialization:}
\SetKw{output}{output}
\SetNoFillComment
\DontPrintSemicolon
\LinesNumbered
\KwIn{$v \in \Rdim{K}$}
\KwOut{$A = \left[ {a}_1 \cdots {a}_K  \right] \in \Rdim{K \times K}$ where $A_{k,m} = \esp{m-1}{v\minind{k}}$}
\Initialization{$A \gets \zerovec{}^{K \times K},\, s \gets \zerovec{K+1}$}

$\esp{0}{v}, \ldots, \esp{K}{v} \gets $ \algfont{FFT-ESP}$(v)$

${a}_1 \gets \mathbf{1}_K$

\For{$m = 1:K-1$}{

    $ {a}_{m+1} \gets \univec{\esp{m}{v}}{K} - v \odot {a}_m$
}

\output $A$
\end{algorithm2e}
\begin{lemma} \label{lemma:pesp}
    \algorithmref{algo:partial_esps}, hereafter referred to as \algfont{PESP}, runs in \( O(K^2) \) time and, 
    given a vector \( v \in \Rdim{K} \), returns a matrix \( A \in \Rdim{K \times K} \) such that  
    \[
        (A)_{k,m} = \esp{m-1}{v\minind{k}}
    \]
    for all \( k, m \in [K] \).
\end{lemma}

\begin{proof}[Proof of \lemmaref{lemma:pesp}]
Let $K \in \Nplus, k \in [K]$ and $v \in \Rdim{K}$.
By \lemmaref{lemma:elementary_symmetric_polynomial_recurrence_relation}, 
for every $m \in [K]$
\[
    \esp{m}{v} = v(k) \cdot \esp{m-1}{ v\minind{k} } + \esp{m}{ v\minind{k} }.
\]
Hence, for every $m \in [K-1]$,
\begin{equation}
    \label{eq:calc_of_pesp_by_esp}
    \esp{m}{ v\minind{k} } = \esp{m}{v} - v(k) \cdot \esp{m-1}{ v\minind{k} },
\end{equation}
with the base case $\esp{0}{ v\minind{k}} = 1$.
Thus, for every $k \in [K]$,
\[
    A_{k,1} = {a}_1(k) = 1 = \esp{0}{v\minind{k}},
\]
and by induction on $m-1$, for every $m \in [2:K]$,
\begin{align*}    
    A_{k,m}
    % &
    = \esp{m-1}{v} - v(k) \cdot {a}_{m-1}(k)
    % \\ &
    = \esp{m-1}{v} - v(k) \cdot \esp{m-2}{v\minind{k}}
    % \\&
    = \esp{m-1}{v\minind{k}}
\end{align*}
In terms of complexity, \algfont{FFT-ESP} executes once in \( O(K \log K) \) time 
(\remarkref{remark:esp_fft}), 
followed by \( K \) iterations where each of the \( K \) entries performs \( O(1) \) operations. 
This results in a total complexity of \( O(K^2) \).
\end{proof}

\begin{proof}[Proof of \remarkref{remark:algo_complexity}]
To analyze the per-time-step complexity, 
consider an arbitrary round $t \in [2,T]$ with associated state vector $s \in \Rdim{K}$, 
and let $H = T - t + 1$ denote the remaining horizon.
The operations executed at round $t$ are as follows, along with their per-step time complexity.
\begin{enumerate}
    \item \emph{State and Residual loss Vectors Update} (Lines \ref{line:update_the_state_vector} and \ref{line:opt_res_loss_vector_update}): 
    element-wise vector operation, runs in \(O(K)\) time.

    \item \emph{Opportunistic Loss update}  (Line \ref{line:update_the_loss}):
    \begin{enumerate}
        \item \emph{Computing the polynomial \( \biaseddenomfunction{H}{K} \) \eqref{eq:biased_denominator_function}}:
        This process consists of the following steps:

        \begin{itemize}
            \item Computing the binomial coefficients 
            \[ 
                \binom{K-n}{m-n}  \quad \text{for all} \quad 0 \leq m, n \leq K .
            \]
            These coefficients can be precomputed before the algorithm begins. Using Pascal’s triangle, they can be computed in \( O(K^2) \) time.

            \item Computing the elementary symmetric polynomials
            using \algfont{FFT-ESP} in \( O(K \log K) \) (\remarkref{remark:esp_fft}).

            \item Computing the falling factorials 
            \[ 
                \fallingfact{H}{0}, \ldots, \fallingfact{H}{K}.
            \]
            These are computable in \( O(K) \) time directly via \definitionref{def:falling_factorial}.            
        \end{itemize}

        Once all components are precomputed in \( O(K^2) \), the polynomial is obtained by iterating over all \( 0 \leq n \leq m \leq K \), requiring an additional \( O(K^2) \) operations.

        \item 
        \emph{Root Finding}:
        Since \(\biaseddenomfunction{H}{s}\) is a degree-\(K\) polynomial, 
        its largest root can be computed numerically to precision \(\varepsilon\) in \(O(K \log(1/\varepsilon))\) time
        using standard root-finding methods,
        such as Newton's Method or Laguerre’s method.
        By applying the upper bound from \theoremref{theorem:regret_factor}, 
        we can efficiently compute a good initial point in constant time, 
        where the number of required iterations is only \( O(\log \log(1/\varepsilon)) \).
    \end{enumerate}

    \item \emph{Optimal Odds Update} (Line \ref{line:optimal_odds_update}):  
    Using \algfont{PESP}, we compute all the necessary ESPs for the polynomials  
    \[
        \denomfunction{H-1}{K-1}(v\minind{1}),\, \ldots, \denomfunction{H-1}{K-1}(v\minind{K})
    \]
    in \( O(K^2) \). The falling factorials required for these computations are obtained in \( O(K) \).  
    Each polynomial, for \( k \in [K] \), involves \( K+1 \) iterations, each requiring \( O(1) \) operations,  
    resulting in an overall complexity of \( O(K^2) \). Finally, computing the quotient for each term in the sum  
    incurs an additional \( O(K) \) cost.
\end{enumerate}
Thus, the overall complexity per time step is \( O(K^2) \), 
leading to a total complexity of \( O(TK^2) \) over \( T \) time steps.
\end{proof}












\subsection{Proof of Remark \ref{remark:prev_algo_comparison}}
\label{appendix:prev_algo_comparison}
\citet{bhatt2025optimal} consider the binary case (\(K = 2\)) and design two algorithms for the bookmaker, 
depending on the gambler's behavior. 
Against a decisive gambler, they propose the \emph{Optimal Strategy For Decisive Gamblers} algorithm (\algfont{ODG}), 
which coincides with \algorithmref{algo:optimal_bookmaking}. 
Against a non-decisive gambler, who may place continuous bets \( q_t \in [0,1] \),
they construct a mixture of \algfont{ODG} strategies, 
based on the observed betting sequence.
In particular, let \( r_t^{\text{\algfont{ODG}}}(x^{t-1}) \) 
denote the odds produced by \algfont{ODG} algorithm for some input \( x^{t-1} \in \{0,1\}^t \). 
Their idea is to view \( q_t \in [0,1] \) as the expected value of a binary random variable \( X_t \sim \text{Ber}(q_t) \). 
The strategy for continuous bets \citep[Eq.~25]{bhatt2025optimal} is
\begin{equation} \label{eq:bhaat_et_al_strategy}
    \bar{r}_t(q^{t-1}) = \mathbb{E} \left[ r_t^{\text{\algfont{ODG}}}(X^{t-1}) \right],
\end{equation}
where the expected value is taken with respect to the sequence of independent random variables \( X_i \sim \text{Ber}(q_i) \).


As computing the odds according to \eqref{eq:bhaat_et_al_strategy} can take exponential time,
they propose to evaluate it via a Monte Carlo simulation 
and provide \emph{Monte Carlo Based Efficient Strategy} Algorithm (referred to as \algfont{MC}).
At each round \( t \), the algorithm runs \( N \) parallel simulations of \algfont{ODG},
and the strategy is computed as the average over these \( N \) independent runs.
The computational complexity of \algfont{MC} is \(\mathcal{O}(NT)\), 
where \(N\) denotes the number of samples per round and \(T\) is the total number of betting rounds.
The computational efficiency of \algfont{MC} hinges on the number of samples required to achieve a desired approximation accuracy. 
Specifically, to ensure an additive error tolerance of \(\varepsilon\) with probability at least \(1 - \delta\), 
the required number of samples must satisfy:
\[
    N \geq \frac{T}{2\varepsilon^2} \log \left( \frac{2T}{\delta} \right).
\]
Substituting this bound on \(N\) yields an overall complexity of
\(
    O \left( T^{3+2\alpha} \log \left( \frac{T}{\delta} \right) \right).
\)


\begin{proof}[Proof of \remarkref{remark:prev_algo_comparison}]
% By  \theoremref{theorem:optimal_bookmaking_algorithm}, \algfont{OOPT} is optimal opportunistic strategy.
We show there exist \(T \in \Nplus\), \(t \in \nset{T}\), and \(s \in \Rdim{2}\) 
for which \eqref{eq:bhaat_et_al_strategy} does not output the same odds as \algorithmref{algo:optimal_bookmaking}
(\algfont{OOPT}).
Let $T=4$.
At the first round, 
\[
    r_1^{\text{\algfont{OOPT}}} = \bar{r}_1 = (0.5, 0.5).
\]
Hence, after any gambler's action 
\(
    q_1 = \left( q_1(1),\, q_1(2) \right),
\)
both algorithms have the same state vector
\[
    s = \left( 2q_1(1) ,\, 2q_1(2) \right).
\]
It holds that 
\begin{align*}
    \bar{r}_2\left( \left(q_1(1)\right)  \right) 
    &= \mathbb{P}\left( \; (1) \; \mid \; \left(q_1(1)\right) \; \right) \cdot r_2^{\text{\algfont{ODG}}}\left((1)\right)
        + \mathbb{P}\left( \; (2) \; \mid \; \left(q_1(1)\right) \; \right) \cdot r_2^{\text{\algfont{ODG}}}\left((2)\right)
    \\ 
    &= q_1(1) \cdot \left(\frac{2}{3}, \frac{1}{3} \right) + q_1(2) \cdot \left(\frac{1}{3}, \frac{2}{3} \right) \\
    &= \frac{1}{3} \left( 2 \cdot q_1(1) + q_1(2),\; q_1(1) + 2 \cdot q_1(2) \right).
\end{align*}
At $t=2$, by \theoremref{theorem:optimal_bookmaking_algorithm}, 
\(
    \optimalloss{3}{2}(s) = \argmaxroot{\biaseddenomfunction{3}{s}}
\)
where 
\begin{equation*}
    \biaseddenomfunction{3}{s}(x) = x^{2} - \left(6 + 2q_1(1) + 2q_1(2) \right)x + \left( 6 + 6q_1(1) + 6q_1(2) + 4q_1(1) q_1(2) \right).
\end{equation*}
Choosing \(q_1 = (0.4, 0.6)\) gives
\(
    \biaseddenomfunction{3}{s}(x) = x^2 - 8x + 12.96,
\)
and the optimal loss is \(5.7435\). 
The residual loss is then
\[
    v \approx (5.7435 - 0.8, 5.7435 - 1.2) = (4.9435, 4.5435). 
\]
Using \eqref{eq:optimal_odd_thm}, we have that 
\[
    r_2^{\text{\algfont{OOPT}}} \approx (0.4635, 0.5364) \neq (0.4666, 0.5333) \approx \bar{r}_2\left( \left( q_1(1) \right) \right).
\]
\end{proof}









\subsection{Proof of Remark \ref{remark:approximate_root_finding} (The Effect of \teq{$\varepsilon$}-Approximate Root-Finding)}
\label{appendix:oracle_optimal_bookmaking}
In this section, 
we analyze a variant of \algorithmref{algo:optimal_bookmaking} that replaces exact root-finding with an $\varepsilon$-approximate oracle. 
The underlying principle of the algorithm is to obtain an upper approximation to the optimal opportunistic loss 
such that the resulting "residual loss vector" $v$ is still achievable.


Let $\varepsilon > 0$, and assume access to an oracle \(\mathbf{O}_\varepsilon\) that, 
given a univariate polynomial $\mathcal{P}$:
\begin{itemize}
    \item \emph{If $\mathcal{P}$ has real roots:}  returns a value $\rho^\varepsilon \in \Rfield$, such that  
    \begin{equation}
        \label{eq:return_of_the_oracle}
        \left|  \rho^{\varepsilon} - \rho \right| < \varepsilon,
    \end{equation}
    where $\rho$ is $\mathcal{P}$'s maximal real root.

    \item \emph{Otherwise:} returns $\infty$.
\end{itemize}
We present \algorithmref{algo:oracle_optimal_bookmaking}, 
where modified lines of \algorithmref{algo:optimal_bookmaking} are marked with $*$.


\begin{algorithm2e}
\caption{Opportunistic Bookmaking Algorithm with Maximal Real Root Oracle}
\label{algo:oracle_optimal_bookmaking}
\SetKw{Initialization}{Initialization:}
\SetKw{output}{output}
\SetNoFillComment
\DontPrintSemicolon
\LinesNotNumbered

\nlset{$*$} \KwIn{$K$, $T$, $\varepsilon$ (precision), $\mathbf{O}_\varepsilon$, $\seq{q}{T-1}$ (bets obtained sequentially)} 
\KwOut{$r_1,\dots,r_T$ (outputs $\seqelem{r}{t}$ after observing $\seq{q}{t-1}$)}
\nlset{$*$} \Initialization{$s \gets \univec{\varepsilon}{K}, \quad L \gets \mathbf{O}_{\varepsilon}(\biaseddenomfunction{T}{s})$}

\output $\seqelem{r}{1}\gets \univec{\frac{1}{K}}{K}$ 

\For{$t = 2:T$}{

    $s \gets s + \seqelem{q}{t-1} \oslash \seqelem{r}{t-1}$  
    \tcp*{update the state vector with additional $\univec{\varepsilon}{K}$} 

    \If
    {$\seqelem{q}{t-1} \not\in \stdbasis{K}$}
    {
    \nlset{$*$}  $s \gets s + \univec{\varepsilon}{K}$

    \nlset{$*$}  $L \gets \mathbf{O}_\varepsilon(\biaseddenomfunction{T-t+1}{s})$
        \tcp*{call the oracle instead of calculating $\argmaxroot{\biaseddenomfunction{T-t+1}{s}}$}
    }

    $v \gets \left( \univec{L}{K} - s \right)$

    \For{$k=1:K$}{
        $r(k) \gets  \denom{T-t}{K-1}{v\minind{k}}$
    }

    \output $r_t \gets r/ \| r\|_1$
}
\end{algorithm2e}


\begin{proof}[Proof of \remarkref{remark:approximate_root_finding}]
We show that for every non-decisive gambler action, 
the bookmaker’s loss exceeds the optimal opportunistic bookmaking loss by at most $2\varepsilon$.

Let $H \in \Nplus$ and $s \in \Rdim{K}$.
Denote by $L_{H,K}^{\varepsilon}(s)$ a fixed response of $\mathbf{O}_\varepsilon(\biaseddenomfunction{H}{s})$.
By \theoremref{theorem:optimal_bookmaking_algorithm}, 
$\optimalloss{H}{K}(s)$ is equal to the largest real root of the polynomial \(\biaseddenomfunction{H}{s}\);
thus, from \eqref{eq:return_of_the_oracle}, it follows that
\begin{equation}
    \label{eq:return_loss_of_oracle_root}
    \optimalloss{H}{K}(s) - \varepsilon < L_{H,K}^{\varepsilon}(s) < \optimalloss{H}{K}(s) + \varepsilon.
\end{equation}
By \definitionref{def:value_function} of the value function,
\begin{equation}
    \label{eq:return_potential_of_oracle_root}
    \pot{H}{H}{s} - \varepsilon < L_{H,K}^{\varepsilon}(s) < \pot{H}{H}{s} + \varepsilon.
\end{equation}
Observe a fixed value of 
\(
    L_{H,K}^{\varepsilon}(s + \univec{\varepsilon}{K}):
\)
By \eqref{eq:return_potential_of_oracle_root}, 
\begin{equation*}
    \potfunction{H}{K}(s + \univec{\varepsilon}{K}) - \varepsilon 
    < L_{H,K}^{\varepsilon}(s + \univec{\varepsilon}{K}) 
    < \potfunction{H}{K}(s + \univec{\varepsilon}{K}) + \varepsilon.
\end{equation*}
By uniform translation property of the value function (\lemmaref{lemma:uniform_translation_property}),
\begin{equation*}
    \left( \potfunction{H}{K}(s) + \varepsilon \right) - \varepsilon 
    < L_{H,K}^{\varepsilon}(s + \univec{\varepsilon}{K}) 
    < \left(\potfunction{H}{K}(s) + \varepsilon \right) + \varepsilon,
\end{equation*} 
i.e.,
\begin{equation*}
    \potfunction{H}{K}(s)  
    < L_{H,K}^{\varepsilon}(s + \univec{\varepsilon}{K}) 
    < \potfunction{H}{K}(s) + 2\varepsilon.
\end{equation*} 
By continuity and coordinate-wise strict monotonicity of the value functions 
(\lemmaref{lemma:continuity_of_the_value_function,lemma:cw_strict_m}), 
and since the value of $L_{H,K}^{\varepsilon}(s + \univec{\varepsilon}{K})$ is bounded,
there exists a vector $b \in \Rdim{K}$ such that $0 \prec b \prec \univec{2\varepsilon}{K}$ and 
\begin{equation}
    \label{eq:oracle_return_alternative_notation}
    L_{H,K}^{\varepsilon}(s + \univec{\varepsilon}{K}) = \optimalloss{H}{K}(s + b).
\end{equation}


Denote by $\mathbf{O}_0$ the oracle who returns the precise value of the maximal real root (if it exists).
By \eqref{eq:oracle_return_alternative_notation}, 
an equivalent interpretation of \algorithmref{algo:oracle_optimal_bookmaking} is as follows: 
\begin{itemize}
    \item 
    Before round $t \in [T]$ with some initial state $s_t$, 
    we sample a vector 
    \begin{equation}
        \label{eq:sample_b_t_oracle_equivalence}
        b_t \in \{b \in \Rplus{K} \; : \; b \prec \univec{2\varepsilon}{K} \}
    \end{equation}
    according to some unknown probability distribution.
    We interpret $b_t(k)$ as a given random tax that we are forced to pay, if outcome $k$ materializes.

    \item
    In general, the state $s_t$ accounts for some given loss when choosing a bookmaking action 
    (see the motivation for the OOBL in \sectionref{subsec:problem_opportunistic}).
    Thus, our effective state to consider is $s_t + b_t$.

    \item 
    After observing $b_t$, we have an access to the oracle $\mathbf{O}_0$.
    By \theoremref{theorem:optimal_bookmaking_algorithm}, the optimal strategy  
    is to query $\mathbf{O}_0$ with the polynomial $\biaseddenomfunction{T-t+1}{s_t + b_t}$.
\end{itemize}
A direct result of coordinate-wise strict monotonicity property (\lemmaref{lemma:cw_strict_m}),
is that the worst random tax $b_t$, as in \eqref{eq:sample_b_t_oracle_equivalence} is $\univec{2\varepsilon}{K}$ 
(formally, infinitesimally close to $\univec{2\varepsilon}{K}$).
By uniform translation property, 
we obtain that the bookmaker’s loss exceeds the optimal opportunistic bookmaking loss by at most $2\varepsilon$.

\end{proof}













