\subsection{Proofs for Appendix \ref{appendix:preliminaries} }
\label{appendix:technical_A}

\begin{proof}[Proof of \lemmaref{lemma:elementary_symmetric_polynomial_sum_identity}]
For $m=0$, the lemma holds trivially due to the fact that $\esp{0}{\cdot}=1$. 
For $0 < m \leq K$, by \definitionref{def:esp}, it holds that
    \begin{align*}
        \sum_{i=1}^{K} \esp{m}{x\minind{i} }  
        = \sum_{i=1}^{K} \sum_{\mathfrak{I} \in \binom{\nset{K} \setminus \{ i \}}{m}} \prod_{k \in \mathfrak{I}} \vecind{x}{k}.
    \end{align*}
    Every subset of indices \(\mathfrak{J} \in \binom{[K]}{m}\) appears in \( K - m \) different configurations of $i$ within the summation. This results from choosing any of the \( K - m \) indices that do not belong to \(\mathfrak{J}\) for the value of $i$.
\end{proof}


\begin{proof}[Proof of \lemmaref{lemma:elementary_symmetric_polynomial_with_shift}]
Substituting the vector \( \univec{t}{K} - x \) into the generating function for ESPs (see \remarkref{remark:esps_gen_func}), we obtain:
\begin{align}
    \sum_{n=0}^{K} \esp{n}{\univec{t}{K}-x} y^n 
    &= \prod_{k=1}^{K} \left(1 + \left(t - x(k)\right) y\right)    \label{eq:proof_elementary_symmetric_polynomial_with_shift}
    \\
    &=  \prod_{k=1}^{K} \left( (1 + t y) - x(k) y \right) \nonumber 
\end{align}
Expanding this product involves selecting for each \( k \) either the \( 1 + t y \) term or the \( -x(k) y \) term.
Specifically, all the terms in the product which involves \( i \) of the \( -x(k) y \) terms 
will contribute to the generating function the term
\begin{equation} \label{eq:appendix_proof_elementary_symmetric_polynomial_with_shift}
    (-1)^i \sigma_i(x) y^i  (1 + t y)^{K - i}.
\end{equation}
Thus,
\begin{align}
    \prod_{k=1}^{K} \left(1 + \left(t - x(k)\right) y\right) 
    &\stackrel{(a)}{=} \sum_{i=0}^{K} (-1)^i \sigma_i(x) y^i \cdot (1 + t y)^{K - i} \nonumber
    \\
    &\stackrel{(b)}{=}  \sum_{i=0}^{K} (-1)^i \sigma_i(x) y^i \sum_{j=0}^{K - i} \binom{K - i}{j} t^j y^j \nonumber
    \\
    &=  \sum_{i=0}^{K} \sum_{j=0}^{K - i} (-1)^i \sigma_i(x) \binom{K - i}{j} t^j y^{i + j} \nonumber
    \\
    &\stackrel{(c)}{=} 
    \sum_{n=0}^{K} \left( \sum_{i=0}^{n} (-1)^i \sigma_i(x) \binom{K - i}{n - i} t^{n - i} \right) y^n,
    \label{eq:proof_elementary_symmetric_polynomial_with_shift_last}
\end{align}
where
$(a)$ follows by \eqref{eq:appendix_proof_elementary_symmetric_polynomial_with_shift},
$(b)$ follows from the expansion of \( (1 + t y)^{K - i} \) using the binomial theorem,
and $(c)$ uses the variable substitution $n = i + j$.
By equating the coefficients of \( y^n \) on the LHS of \eqref{eq:proof_elementary_symmetric_polynomial_with_shift} 
with those in \eqref{eq:proof_elementary_symmetric_polynomial_with_shift_last}, we obtain:
\[
    \sigma_n(\univec{t}{K} - x) = \sum_{i=0}^{n} (-1)^i \sigma_i(x) \binom{K - i}{n - i} t^{n - i}
\] 
\end{proof}







\subsection{Proofs for Appendix \ref{appendix:the_adversarial_game_dynamics} }
\label{appendix:technical_B}


\begin{proof}[Proof of \lemmaref{lemma:uniform_translation_property}]
Let $s \in \Rdim{K}$ and $c \in \Rfield$. We prove by induction on $H$.
\begin{itemize}
    \item \emph{Base Case} (\(H=0\)):  
    It holds that 
    \begin{align*}
        \pot{0}{K}{s + \univec{c}{K}}
        \eqdef \;
        &\max_{k \in [K]} \left(s + \univec{c}{K} \right)(k) 
        \\
        = \;
        &\max_{k \in [K]} s(k) + c
        \\
        = \;
        &\pot{0}{K}{s} + c.
    \end{align*}
    \item \emph{Inductive step} (\( H \to H+1 \)):     
     \begin{align*}
        \pot{ H + 1}{K}{s + \univec{c}{K}}
        &\eqdef 
        \inf_{ r \in \simplex{K-1} } \; \max_{ q \in \simplex{K-1}} 
            \pot{ H }{K}{
                 s + \univec{c}{K} + q \oslash r 
             } 
        \\
        &\stackrel{(*)}{=} 
        \inf_{ r \in \simplex{K-1} } \; \max_{ q \in \simplex{K-1}} 
            \pot{ H }{K}{
                 s + q \oslash r 
             } + c
        \\
        &= 
        \pot{ H + 1}{K}{s} + c,
    \end{align*}
    where $(*)$ follows from the induction hypothesis.
\end{itemize}
\end{proof}




\begin{proof}[Proof of Lemma \ref{lemma:properties_of_corr}]
The correspondence $\corr_H$ is compact-valued by its definition in \eqref{eq:def_of_corr_H},
and is non-empty as for every \( s \in \mathbb{R}^K \), \( \frac{1}{K} \in \corr_H(s) \). 


A correspondence is continuous if it is both upper and lower hemicontinuous (see \definitionref{def:continuity_of_a_correspondence}).
From the continuity of the maximum and minimum functions on $\mathbb{R}^K$, 
the function $\omega_{H}$, defined in \eqref{eq:def_of_omega_H_s}, is continuous. 
Hence for any $\bar{s} \in \Rdim{K}$ and $\delta > 0$, 
there exists an open neighborhood \(U\) of \(\bar{s}\) such that for all $s \in U$,
\(
    |\omega_H(s) - \omega_H(\bar{s})| < \delta.
\)


Let \(\bar{s} \in \Rdim{K}\) and let \(V \subset \Delta^{K-1}\) be an open set with \(\corr_H(\bar{s}) \subset V.\)
Since every \(r \in \corr_H(\bar{s})\) is an interior point of \(V\), for each there exists \(\varepsilon_r > 0\) such that \(B(r,\varepsilon_r) \subset V\). 
By compactness of \(\corr_H(\bar{s})\), a finite subcover yields a uniform margin \(\delta > 0\) ensuring that if
\(
    |\omega_H(s)-\omega_H(\bar{s})|<\delta,
\)
then for every \(r \in \Delta^{K-1} \) and $ k \in [K]$,  if
\(
    r(k) \geq \omega_H(s) 
\)
then
$r \in V$.
By continuity of \(\omega_H\), 
there exists an open neighborhood \(U\) of \(\bar{s}\), such that for every $s \in U,$
$\corr_H(s)\subset V$,
and thus $\corr_H$ is upper hemicontinuous.



Let \(\bar{s} \in \Rdim{K}\) and suppose \(V \subset \Delta^{K-1}\) is open with
\(
\corr_H(\bar{s})\cap V\neq\emptyset.
\)
Choose \(\bar{r}\in \corr_H(\bar{s})\cap V\). Since \(V\) is open, there exists \(\varepsilon>0\) with \(B(\bar{r},\varepsilon)\subset V\). 
\begin{itemize}
    \item 
    \emph{If \(\bar{r}\) is an interior point of \(\corr_H(\bar{s})\): }
   For all \(k \in [K]\), \(\bar{r}(k) > \omega_H(\bar{s})\). 
   By the continuity of \(\omega_H\), 
   there exists a neighborhood \(U\) of \(\bar{s}\) such that for all \(s\in U\) and $k \in [K]$,
   $\omega_H(s) < \bar{r}(k)$.
   Hence, \(\bar{r}\in \corr_H(s)\cap V\).

   \item 
   \emph{If \(\bar{r}\) lies on the boundary of \(\corr_H(\bar{s})\):}  
   Then for some coordinate, \(\bar{r}(k)=\omega_H(\bar{s})\). Since \(\bar{r}\) is in \(V\), we can select \(r'\in B(\bar{r},\varepsilon)\) with \(r'(k)>\omega_H(\bar{s})\) for all \(k\). Again, by continuity of \(\omega_H\), for \(s\) in a neighborhood \(U\) of \(\bar{s}\) we have
   $\omega_H(s) < r'(k)$ for every $k \in [K]$,
   so that \(r'\in \corr_H(s)\cap V\).
\end{itemize}
In either case, there exists an open neighborhood \(U\) of \(\bar{s}\) such that 
\(\corr_H(s)\cap V\neq\emptyset\) for all \(s\in U\),
and thus $\corr_H$ is lower hemicontinuous.

\end{proof}





\begin{proof}[Proof of \lemmaref{lemma:nash_last_round}]
Let $s \in \Rdim{K}$. 
By \definitionref{def:value_function}, $\pot{0}{K}{s} \eqdef \max_{k \in \nset{K}} s(k)$ and hence a convex function.
By \lemmaref{lemma:value_function_if_convex},
\[
    \pot{1}{K}{s} = \min_{r \in \corr_1(s)} \max_{k \in [K]} s(k)+ \frac{1}{r(k)}.
\]
Assume, towards a contradiction, 
that there exists an optimal bookmaker action $r \in \corr_1(s)$ that does not satisfy 
\eqref{eq:nash_last_round};
that is, $r$ achieves the optimal loss \( \opt\ell  \), yet there exists an index \( i \in \nset{K} \) such that  
\begin{equation}
    \label{eq:proof_nash_last_round_2_cont_assumption}
    \vecind{s}{i} + \frac{1}{\vecind{r}{i}} = \opt\ell - \kappa  \quad \text{for some } \kappa > 0.
\end{equation}
Assume $K \geq 2$ (for the case \( K = 1 \), the statement is trivially false).
It holds that  
\[
    \frac{K}{K-1} \vecind{r}{i} \; , \; \frac{K \kappa (\vecind{r}{i}^2) }{(K-1)(1 + \kappa \vecind{r}{i})} > 0.
\]
Therefore, there exists \( \varepsilon \in \Rpplus{} \) such that  
\[
    0 < \varepsilon < \min \left\{ 
            \frac{K}{K-1} \vecind{r}{i} \; , \;
            \frac{K \kappa (\vecind{r}{i}^2) }{(K-1)(1 + \kappa \vecind{r}{i})}
        \right\}.
\]
We construct a new distribution \( \hat{r} \in \simplex{K-1} \) as follows:  
\[
    \vecind{\hat{r}}{k} = \begin{cases}
        \vecind{r}{k} - \frac{K-1}{K} \varepsilon & \text{if } k = i, \\
        \vecind{r}{k} + \frac{1}{K} \varepsilon & \text{if } k \neq i.
    \end{cases} 
\]
\( \hat{r} \) is indeed in \( \simplex{K-1} \) as it satisfies:
\begin{itemize}
    \item \emph{Sum Constraint}: 
    \[
        \sum_{k=1}^K \vecind{\hat{r}}{k} 
        = \vecind{r}{i} - \frac{K-1}{K} \varepsilon + \sum_{k \neq i} \left(\vecind{r}{k} + \frac{1}{K} \varepsilon\right)
        = 1.
    \]   
    \item \emph{Positivity Constraint}:  
    For \( k = i \), since \( \varepsilon < \frac{K}{K-1} \vecind{r}{i} \) we obtain:  
    \[
        \vecind{\hat{r}}{i} 
        = \vecind{r}{i} - \frac{K-1}{K} \varepsilon     
        > \vecind{r}{i} - \frac{K-1}{K} \frac{K}{K-1} \vecind{r}{i}
        = 0.
    \]
    For \( k \in \nset{K} \setminus \{i\} \):  
    \[
        \vecind{\hat{r}}{k} = \vecind{r}{k} + \frac{1}{K} \varepsilon > \vecind{r}{k} > 0.
    \]
\end{itemize}
We show that acting with \( \hat{r} \) produces a loss that is \(< \opt\ell \).
\begin{itemize}
    \item \emph{For \( k = i \)}:  
        \begin{align}
            \label{eq:nash_last_round_2_a}
            \frac{1}{\vecind{\hat{r}}{i}} - \frac{1}{\vecind{r}{i}}    
            = \frac{\vecind{r}{i} - \vecind{\hat{r}}{i}}{\vecind{r}{i} \vecind{\hat{r}}{i}}
            = \frac{\frac{K-1}{K} \varepsilon}{\vecind{r}{i} (\vecind{r}{i} - \frac{K-1}{K} \varepsilon)}.
        \end{align}
        From the definition of \( \varepsilon \), we have:
        \begin{align}
            \label{eq:nash_last_round_2_b}
            \varepsilon < \frac{\kappa \vecind{r}{i}^2 K}{(K-1)(1 + \kappa \vecind{r}{i})} 
            \quad \implies
            \frac{\frac{K-1}{K} \varepsilon}{\vecind{r}{i} \left( \vecind{r}{i} - \frac{K-1}{K} \varepsilon \right)} < \kappa.
        \end{align}


        Thus, by \equationref{eq:proof_nash_last_round_2_cont_assumption,eq:nash_last_round_2_a,eq:nash_last_round_2_b}
        \begin{align*}
            \vecind{s}{i} + \frac{1}{\vecind{\hat{r}}{i}} 
            = \opt\ell - \kappa + \frac{1}{\vecind{\hat{r}}{i}} - \frac{1}{\vecind{r}{i}}
            < \opt\ell.
        \end{align*}

    \item \emph{For \( k \in \nset{K} \setminus \{i\} \)}:
    \[
            \frac{1}{\vecind{r}{k}} > \frac{1}{\vecind{r}{k} + \frac{1}{K} \varepsilon} \implies
            \vecind{s}{k} + \frac{1}{\vecind{r}{k}} > \vecind{s}{k} + \frac{1}{\vecind{\hat{r}}{k}} 
    \]
    Hence,
    \[
        \opt\ell = \max_{k \in \nset{K} \setminus \{i\}}  \vecind{s}{k} + \frac{1}{\vecind{r}{k}}
            > \max_{k \in \nset{K} \setminus \{i\}} \vecind{s}{k} + \frac{1}{\vecind{\hat{r}}{k}} .
    \]
\end{itemize}
Combining both cases, we obtain:
\[
    \max_{k \in \nset{K}} \left( \vecind{s}{k} + \frac{1}{\vecind{\hat{r}}{k}} \right) < \opt\ell.
\]
It follows that $r$ is suboptimal, contradicting the optimality assumption.

It remains to show that the optimal bookmaking action is unique.
Let $\optr, \hat{r} \in \corr_{1}(s)$ be two vectors that satisfy \eqref{eq:nash_last_round},
i.e.,
\begin{equation*}
    s(k) + \frac{1}{\optr(k)} = s(k) + \frac{1}{\hat{r}(k)} = \pot{1}{K}{s} \quad \forall k \in [K]. 
\end{equation*}
As the function $x \mapsto \frac{1}{x}$ is strictly decreasing in $\Rplus{}$,
for every $k \in [K]$, $\hat{r}(k) = \optr(k)$, 
and thus the optimal bookmaking action $\optr$ is unique.
\end{proof}













\subsection{Proofs and Technical Details for Section \ref{sec:bpf} and Appendix \ref{appendix:value_vectors}}
\label{appendix:technical_C}

\begin{proof}[Proof of \lemmaref{lemma:last_gamblers_bet}]
    Let $k \in [K]$ be the index for which $q_H = \basis{k}$.
    When $K=1$, the claim is immediate.
    Suppose $K \geq 2$, and assume, towards a contradiction, that some 
    $j \in [K] \setminus \{k\}$ maximizes the RHS of \eqref{eq:conclusion_from_nash_and_value_function}.
    By \lemmaref{lemma:continuity_of_the_value_function} (see \appendixref{appendix:the_adversarial_game_dynamics}),
    any optimal bookmaker's action $r_H$ assigns a positive probability mass $r_H(i) > 0$ for every $i \in [K]$.
    Thus, for the betting sequence $(q_1, \ldots, q_{H-1}, \basis{j}) \in (\stdbasis{K})^H$, 
    the resulting loss would exceed $\pot{H}{K}{s}$, a contradiction to the bookmaker's optimality assumption. 
\end{proof}


\begin{proof}[Proof of \lemmaref{lemma:recurrence_relation_or_the_denom}]
By \lemmaref{lemma:elementary_symmetric_polynomial_recurrence_relation}, we have for \(m\ge1\) 
\[
v(k)\,\esp{m-1}{v\minind{k}} + \esp{m}{v\minind{k}} = \esp{m}{v}.
\]
In particular, with \(m\) replaced by \(K-m\) (noting that \(K-m\ge1\) for \(m\le K-1\) ) we obtain
\begin{align}\label{eq:proof_Drecurrence_ESPrecKM}
v(k)\,\esp{K-1-m}{v\minind{k}} = \esp{K-m}{v} - \esp{K-m}{v\minind{k}}.    
\end{align}
By \eqref{eq:proof_Drecurrence_ESPrecKM}, we have  
\begin{align}\label{eq:proof_Drec_1}
    \vecind{v}{k}\cdot\denom{H}{K-1}{v\minind{k}}&= \sum_{m=0}^{K-1} (-1)^m\,\fallingfact{H}{m}\Bigl(\esp{K-m}{v}-\esp{K-m}{v\minind{k}}\Bigr).
\end{align}
We combine the second summand of \eqref{eq:proof_Drec_1} and $H \cdot \denom{ H-1 }{K-1}{ v\minind{k} }$ as follows:
\begin{align}\label{eq:proof_Drec_2}
    &H \cdot \denom{ H-1 }{K-1}{ v\minind{k} } + \sum_{m=0}^{K-1} (-1)^m\,\fallingfact{H}{m}\esp{K-m}{v\minind{k}}
    \nonumber\\
    &\stackrel{(a)}= \sum_{m=0}^{K-1} (-1)^m\,\fallingfact{H}{m+1} \,
\esp{K-1-m}{v\minind{k}} + \sum_{m=0}^{K-1} (-1)^m\,\fallingfact{H}{m}\esp{K-m}{v\minind{k}}\nonumber\\
&\stackrel{(b)}= \sum_{m=1}^{K} (-1)^{m-1}\,\fallingfact{H}{m}\,\esp{K-m}{v\minind{k}} + \sum_{m=0}^{K-1} (-1)^m\,\fallingfact{H}{m}\esp{K-m}{v\minind{k}}\nonumber\\
&\stackrel{(c)}= (-1)^{K-1}\,\fallingfact{H}{K}\,\esp{0}{v\minind{k}} + \esp{K}{v\minind{k}}\nonumber\\
&= (-1)^{K-1}\,\fallingfact{H}{K}\,\esp{0}{v\minind{k}},
\end{align}
where $(a)$ follows from the identity $H\fallingfact{(H-1)}{m} = \fallingfact{H}{m+1}$, 
$(b)$ follows by re-indexing with \(m+1\), and $(c)$ follows by noting that the two sums are telescoping.
We can now combine \eqref{eq:proof_Drec_1} and \eqref{eq:proof_Drec_2} to complete the proof
\begin{align*}
&\vecind{v}{k} \cdot \denom{ H }{K-1}{ v\minind{k} } - H \cdot \denom{ H-1 }{K-1}{ v\minind{k} } \\
= \,&\sum_{m=0}^{K-1} (-1)^m\,\fallingfact{H}{m}\esp{K-m}{v} + (-1)^{K}\,\fallingfact{H}{K}\,\esp{0}{v\minind{k}}\nonumber\\
=\, &\sum_{m=0}^{K} (-1)^m\,\fallingfact{H}{m}\esp{K-m}{v}\nonumber\\
=\, &\denom{ H }{K}{ v },
\end{align*}
where we use the fact that $\esp{0}{v\minind{k}} = \esp{0}{v}=1$. 
\end{proof}




\begin{proof}[Proof of \lemmaref{lemma:main_lemma_in_conditions}, case $K=1$]
When \(K=1\), the only possible state is \(v=(v(1))\), 
and, by \definitionref{def:bpf}, \(v\in\vvset{H,1}\) if and only if \(v(1)=H\).  Moreover,
\[
  \denom{H}{1}{v} = v(1)-H =0,
  \qquad
  \denom{H-1}{0}{\cdot}=1.
\]
Thus the unique action \(r(1)=1\) satisfies
\[
  \frac{\denom{H-1}{0}{v\minind{1}}}{\denom{H-1}{1}{v}}
  \;=\;
  \frac{1}{H - (H-1)}
  \;=\;1
  \;=\;r(1),
\]
verifying \lemmaref{lemma:proof_of_bp_1}, and
\[
  v(1)
  \;=\;
  H
  \;=\;
  \frac{H \cdot \denom{H-1}{0}{\cdot}}{\denom{H}{0}{\cdot}}
  \;=\;
  \frac{\num{H}{0}{v\minind{1}}}{\denom{H}{0}{v\minind{1}}},
\]
verifying \lemmaref{lemma:proof_of_bp_2}.  
Since \(\denom{H}{0}{v\minind{1}}=1>0\), \lemmaref{lemma:proof_of_bp_3} holds.  
\end{proof}

\begin{proof}[Proof of \lemmaref{lemma:der_of_denom}] Let $H,K \in \Nplus$.
    \begin{enumerate}
        \item 
        By \eqref{eq:main_results_def_of_denom_poly}, \(\denom{H}{K}{v}\) is a finite sum of elementary symmetric polynomials
        (each of which is a polynomial in \(v\)).  
        Hence \(\denomfunction{H}{K}\) is itself a multivariate polynomial, and therefore \(C^\infty\) on \(\Rdim{K}\).

  \item We prove by induction on $m$.

      $\bullet$ \; \emph{Base case} ($m=1$):
      Let $k \in [K]$ be some index. 
      By \lemmaref{lemma:recurrence_relation_or_the_denom}, 
      \begin{align*}
        \frac{\partial}{\partial v(k)} \denom{H}{K}{v} 
        &=
        \frac{\partial}{\partial v(k)} \left(
            \vecind{v}{k} \cdot \denom{ H }{K-1}{ v\minind{k} } - H \cdot \denom{ H-1 }{K-1}{v\minind{k}} 
            \right)
        \\
        &=
        \denom{H}{K-1}{v^{\setminus k}}
      \end{align*}

      $\bullet$ \; \emph{Inductive step} ($m \to m+1$):
      Let $m \in [K-1]$. Fix any subset of indices \(\mathfrak I=\{i_1,\dots,i_{m}\} \subset [K]\) of size $m$, and $k \in [K]\setminus\mathfrak{I}$.
      It holds that 
      \begin{align*}
        \frac{ \partial^m  \denomfunction{H}{K}}{\partial^m v_{\mathfrak{I}\cup \{ k \}} } (v)
        &=
        \frac{ \partial }{\partial v(k) } 
        \frac{ \partial^m  \denomfunction{H}{K}}{\partial^m v_{\mathfrak{I}} } (v)
        \\
        &\stackrel{(a)}{=} 
        \frac{ \partial }{\partial v(k) } \denom{H}{K-m}{v\minind{\mathfrak{I}}}
        \\
        &\stackrel{(b)}{=} 
        \frac{ \partial }{\partial v(k) } \left(
            v(k) \cdot  \denom{H}{K-(m+1)}{v\minind{\mathfrak{I}\cup \{k\}}} - H \cdot \denom{H-1}{K-(m+1)}{v\minind{\mathfrak{I}\cup \{k\}}}
            \right)
        \\
        &= 
         \denom{H}{K-(m+1)}{v\minind{\mathfrak{I}\cup \{k\}}}
      \end{align*}
      where $(a)$ is implied by the induction hypothesis, 
      and $(b)$ follows from \lemmaref{lemma:recurrence_relation_or_the_denom}. 



  \item 
  Let $k \in [K]$ and $m > 1$. 
  By \lemmaref{lemma:partial_derivatives_of_denom_2} it holds that 
   \begin{equation*}
       \frac{\partial^m}{\partial v(k)^m} \denom{H}{K}{v} 
       = 
       \frac{\partial^{m-1}}{\partial v(k)^{m-1}} \denom{H}{K-1}{v\minind{k}}
       =
       0.
   \end{equation*}
  \end{enumerate}
\end{proof}



\begin{proof}[Proof of \lemmaref{lemma:lower_bound_for_value_vectors}]
    Let \( \seq{r}{H} \) be any sequence of actions chosen by the bookmaker \( \bm^{H} \). 
    Then, if the gambler bets on a single outcome $k \in [K]$ in each of the remaining $H$ rounds, 
    the total payout for outcome $k$ will be 
    \begin{equation*}  
        \sum_{h=1}^{H} \frac{1}{\vecind{\seqelem{r}{h}}{k}}  
        \geq \sum_{h=1}^{H} 1  
        = H.  
    \end{equation*}  
    In case \( K = 1 \), we have \( r_h(1) = 1 \) for all \( h \), and the inequality becomes an equality.
    Otherwise, setting $ r_h(k) = 1$ at any $h$ would cause the remaining components of the vector to become infinite.
\end{proof}  






\subsubsection{Simplification of Equations \teq{\eqref{eq:proof_of_bp_inductive_step_part_2_def_A}}
and \teq{\eqref{eq:proof_of_bp_inductive_step_part_2_def_B}}}
\label{appendix:proof_of_bp_inductive_step_part_2_simplification}

For any $H \geq 1$ and $K \geq 2$, it holds that
\begin{align} 
    \sum_{\indneq{i}{\nset{K}}{k}} \denom{H}{K-2}{v\minind{\{i,k\}}} 
    &\stackrel{(a)}{=}  \sum_{\indneq{i}{\nset{K}}{k}}
        \sum_{m=0}^{K-2} (-1)^{m} \cdot \fallingfact{H}{m} \cdot \esp{K - 2 - m}{v\minind{\{i,k\}}} 
    \nonumber \\
    &=  \sum_{\indneq{i}{\nset{K}}{k}}
        \sum_{m=0}^{K-2} (-1)^{(m+1)-1} \cdot \fallingfact{H}{(m+1)-1} \cdot \esp{(K - 1) - (m + 1)}{v\minind{\{i,k\}}} 
    \nonumber \\
    &\stackrel{(b)}{=} 
    \sum_{\indneq{i}{\nset{K}}{k}}
        \sum_{n=1}^{K-1} (-1)^{n-1} \cdot \fallingfact{H}{n-1} \cdot \esp{(K - 1) - n}{v\minind{\{i,k\}}} 
    \nonumber  \\
    &=  
     \sum_{n=1}^{K-1} (-1)^{n-1} \cdot \fallingfact{H}{n-1} \cdot 
        \sum_{\indneq{i}{\nset{K}}{k}} \esp{(K - 1) - n}{v\minind{\{i,k\}}} 
    \nonumber \\
    &\stackrel{(c)}{=} 
     \sum_{n=1}^{K-1} (-1)^{n-1} \cdot n \cdot \fallingfact{H}{n-1} \cdot \esp{(K - 1) - n}{v\minind{k}},
    \label{eq:simplification_of_A_and_B_expansion_of_sum}
\end{align}
where: 
$(a)$ follows from the expression of $\denom{H}{K}{v}$ in \eqref{eq:def_of_ppoly_explicit};
$(b)$ follows by reindexing the summation via $n=m+1$;
and $(c)$ follows from \lemmaref{lemma:elementary_symmetric_polynomial_sum_identity}.
We obtain
\begin{align}
    \mathtt{B} \;
    &\stackrel{(a)}{\eqdef}
    \denom{H}{K-1}{v\minind{k}} 
        -  \sum_{\indneq{i}{\nset{K}}{k}} \denom{H}{K-2}{v\minind{\{i,k\}}}
    \nonumber
    \\ 
    &\stackrel{(b)}{=} 
     \sum_{m=0}^{K-1} (-1)^{m} \cdot \fallingfact{H}{m}  \cdot \esp{(K - 1) - m}{v\minind{k}}  
        + \sum_{m=0}^{K-1} (-1)^{m} \cdot m \cdot \fallingfact{H}{m-1} \cdot \esp{(K-1) - m}{v\minind{k}}
    \nonumber \\ 
    &=
     \sum_{m=0}^{K-1} (-1)^{m} \cdot \esp{(K - 1) - m}{v\minind{k}} \cdot 
        \left(  \fallingfact{H}{m} + m \cdot \fallingfact{H}{m-1}  \right)
    \nonumber \\ 
    &\stackrel{(c)}{=}
    \sum_{m=0}^{K-1} (-1)^{m} \cdot \fallingfact{(H+1)}{m} \cdot \esp{(K - 1) - m}{v\minind{k}}
    \nonumber \\ 
    &= 
    \denom{H+1}{K-1}{v\minind{k}},
\end{align}
where:
$(a)$ follows from our definition of $\mathtt{B}$ in \eqref{eq:proof_of_bp_inductive_step_part_2_def_B};
$(b)$ follows from the expression of $\denom{H}{K}{v}$ in \eqref{eq:def_of_ppoly_explicit} and a substitution of  \eqref{eq:simplification_of_A_and_B_expansion_of_sum};
and $(c)$ follows from the identity $\fallingfact{T}{m} + m \cdot \fallingfact{T}{m-1} = \fallingfact{(T+1)}{m}$
in \lemmaref{lemma:falling_factorial_identities_2}.

Similarly to the derivation of \eqref{eq:simplification_of_A_and_B_expansion_of_sum}, 
by the definition of $\num{H}{K}{v}$ in \eqref{eq:def_of_num_poly},
it holds that
\begin{equation} \label{eq:simplification_of_A_and_B_expansion_of_sum_similarly}
    \sum_{\indneq{i}{\nset{K}}{k}} \num{H}{K-2}{v\minind{\{i,k\}}} 
    = \sum_{n=0}^{K-1} (-1)^{n-1} \cdot n \cdot \fallingfact{H}{n} \cdot \esp{(K - 1) - n}{v\minind{k}}.
\end{equation}
It follows that
\begin{align*}
    \mathtt{A}  
    &\stackrel{(a)}{\eqdef} 
    \denom{H}{K-1}{v\minind{k}}
        + \num{H}{K-1}{v\minind{k}}
        - \sum_{\indneq{i}{\nset{K}}{k}} \num{H}{K-2}{v\minind{\{i,k\}}}
    \\ 
    &\stackrel{(b)}{=}   
    \sum_{m=0}^{K-1} (-1)^{m} \cdot \fallingfact{H}{m} \cdot \esp{(K - 1) - m}{v\minind{k}} 
        + H \cdot \sum_{m=0}^{K-1} (-1)^{m} \cdot \fallingfact{(H-1)}{m} \cdot \esp{(K - 1) - m}{v\minind{k}}
        \\ &\qquad + \sum_{m=0}^{K-1} (-1)^{m} \cdot m \cdot \fallingfact{H}{m} \cdot \esp{(K-1) - m}{v\minind{k}}
    \\ 
     &\stackrel{(c)}{=}   
    \sum_{m=0}^{K-1} (-1)^{m} \cdot \esp{(K - 1) - m}{v\minind{k}}
        \left(
            (m+1) \cdot \fallingfact{H}{m} + \fallingfact{H}{m+1}
        \right)
    \\
    &\stackrel{(d)}{=}
    \sum_{m=0}^{K-1} (-1)^{m} \cdot \fallingfact{(H+1)}{m+1} \cdot \esp{(K - 1) - m}{v\minind{k}}
    \\ 
    &= 
    \num{H+1}{K-1}{v\minind{k}},
\end{align*}
where the steps are justified as follows: 
\begin{enumerate}[label={$(\alph*)$}]
    \item 
    Follows from our definition of $\mathtt{A}$ in \eqref{eq:proof_of_bp_inductive_step_part_2_def_A}.
    \item 
    Follows from the expression of $\denom{H}{K}{v}$ in \eqref{eq:def_of_ppoly_explicit},
    the definition of $\num{H}{K}{v}$ in \eqref{eq:def_of_num_poly},
    and a substitution of \eqref{eq:simplification_of_A_and_B_expansion_of_sum_similarly}.
    \item 
    Follows from the identity $H \cdot \fallingfact{(H-1)}{m} = \fallingfact{H}{m+1}$.
    \item 
    Follows from the identity  $\fallingfact{T}{m} + m \cdot \fallingfact{T}{m-1} = \fallingfact{(T+1)}{m}$\, in \lemmaref{lemma:falling_factorial_identities_2}.
\end{enumerate}



\subsubsection{Proof of Remark \ref{remark:validity_of_r} } \label{appendix:validity_of_r}

\begin{lemma}\label{lemma:validity_of_r_sum_to_1}
    Let $H,K \in \Nplus$. If $v \in \vvset{H,K}$ then
    \begin{equation*}   
        \sum_{k=1}^{K} \denom{H-1}{K-1}{v\minind{k}}  = \denom{H-1}{K}{v}
    \end{equation*}
\end{lemma}
The lemma must hold by construction:
for $H=1$, $v$ was defined to satisfy condition \ref{base_case_condition_1};
for $H>1$, it satisfy condition \ref{condition_induction_1}.
For the sake of completeness, we provide an explicit proof.

\begin{proof}[Proof of \lemmaref{lemma:validity_of_r_sum_to_1}]
Let $H,K \in \Nplus$ and $v \in \vvset{H,K}$.
It holds that
\begin{align*}
    \sum_{k=1}^{K} \denom{H-1}{K-1}{v\minind{k}} 
    &= 
    \sum_{k=1}^{K} \sum_{m=0}^{K-1} (-1)^{m} \fallingfact{(H-1)}{m} \esp{(K-1)-m}{v\minind{k}} 
    \\
    &=
    \sum_{m=0}^{K-1} (-1)^{m} \fallingfact{(H-1)}{m} \sum_{k=1}^{K} \esp{K-(m+1)}{v\minind{k}} 
    \\
    &\stackrel{(a)}{=}
    \sum_{m=0}^{K-1} (-1)^{m} \fallingfact{(H-1)}{m} \cdot (m+1) \cdot  \esp{K-(m+1)}{v} 
    \\
    &\stackrel{(b)}{=}
    \sum_{n=1}^{K} (-1)^{n-1} \fallingfact{(H-1)}{n-1} \cdot (n) \cdot \esp{K-n}{v}
    \\
    &\stackrel{(c)}{=}
    \sum_{n=1}^{K} (-1)^{n-1} \left(  \fallingfact{H}{n} - \fallingfact{(H-1)}{n} \right) \cdot \esp{K-n}{v} 
    \\
    &=
    - \left( {\sum_{n=1}^{K} (-1)^{n}  \fallingfact{H}{n} \cdot \esp{K-n}{v}} \right)
    + \left( {\sum_{n=1}^{K} (-1)^n  \fallingfact{(H-1)}{n} \esp{K-n}{v}} \right)
    \\
    &=
    - \left( \denom{H}{K}{v} - \esp{K}{v} \right)
    + \left( \denom{H-1}{K}{v} - \esp{K}{v} \right)
    \\
    &= 
    - \denom{H}{K}{v} + \denom{H-1}{K}{v}
    \\
    &\stackrel{(d)}{=}
    \denom{H-1}{K}{v}
\end{align*}
where the steps are justified as follows:  
\begin{enumerate}[label={$(\alph*)$}]
\item 
Follows from \lemmaref{lemma:elementary_symmetric_polynomial_sum_identity}.
\item 
Follows from the substitution $n=m+1$.
\item 
Follows from the identity $n \cdot \fallingfact{(H-1)}{n-1} + \fallingfact{(H-1)}{n} = \fallingfact{H}{n}$ stated in \lemmaref{lemma:falling_factorial_identities_2}.
\item 
By \lemmaref{lemma:proof_of_bp_2},  any $v \in \vvset{H,K}$ satisfies $\denom{H}{K}{v} = 0$.
\end{enumerate}
\end{proof}



\begin{proof}[Proof of \remarkref{remark:validity_of_r}]
Let $H,K \in \Nplus$ and $v \in \vvset{H,K}$.
We prove the vector $r$, given by
\begin{equation} \tag{\ref{eq:optimal_odd_thm}}    
    r(k) = \frac{\denom{H-1}{K-1}{v\minind{k}}}{\denom{H-1}{K}{v}}
\end{equation}
for every $k \in [K]$, is a probability distribution  with non-zero elements.
\begin{itemize}
    \item 
    \emph{Sum Constraint:}
    Holds by \lemmaref{lemma:validity_of_r_sum_to_1}.

    \item 
    \emph{Positivity Constraint:} 
    We distinguish two cases based on the value of $H$.
    \begin{itemize}
        \item 
        \emph{Case $H=1$:} 
        For every $k \in [K]$
        \begin{equation} \tag{\ref{eq:proof_of_bpe_r_equation}}
            \vecind{r}{k} 
            = \frac{1}{\vecind{v}{k}}.
        \end{equation}
        By \lemmaref{lemma:lower_bound_for_value_vectors}, $v \succeq \mathbf{1}_K$; 
        thus, $r$ satisfies the positivity constraint.

        \item 
        \emph{Case $H>1$:}
        For every $k \in [K]$ the vector $\prescript{k}{}{v} \eqdef v - \basis{k}/r(k)$
        must be in $\vvset{H-1,K}$. 
        By the proof of \lemmaref{lemma:proof_of_bp_3} (see \lemmaref{lemma:derivation_of_proof_of_bp_3}) for every $m \in [K]$ and $\mathfrak{I} \in \binom{[K]}{m}$, 
        \(
            \denom{H-1}{K-m}{\prescript{k}{}{v}\minind{\mathfrak{J}}} > 0.
        \)
        Choosing $\mathfrak{I}=\{k\}$ gives 
        \[
            \denom{H-1}{K-1}{v\minind{k}} 
            = \denom{H-1}{K-1}{\prescript{k}{}{v}\minind{k}}  
            > 0.
        \]
        Thus, for every $k \in [K]$, the numerator in \eqref{eq:optimal_odd_thm} is positive. 
        By \lemmaref{lemma:validity_of_r_sum_to_1}, 
        the denominator is a sum of positive numbers and hence positive.
        Thus, $r$ satisfies the positivity constraint.
    \end{itemize}
\end{itemize}

\end{proof}  





\subsection{Technical Details for Appendix \ref{appendix:main_results} }
\label{appendix:technical_D}


\subsubsection{Derivation of the Explicit Form of \teq{$\hatppolyfunction{T}{K}$} in \teq{\eqref{eq:expansion_of_hatppoly}}}
\label{appendix:derivation_of_the_explicit_form_of_tilde_P}
\begin{align*}
    \hatppoly{T}{K}{x} 
    &\stackrel{(a)}{\eqdef}
    \mathcal{P}_{T,K}(x+T) 
    \\ 
    &= 
    \sum_{m=0}^{K} (-1)^m \binom{K}{K-m} \,\fallingfact{T}{m}\, (x+T)^{\,K-m}
    \\ 
    &\stackrel{(b)}{=} 
        \sum_{n=0}^{K} (-1)^{K-n} \binom{K}{n}\,\fallingfact{T}{K-n}\,(x+T)^{n}.
    \\ 
    &\stackrel{(c)}{=} 
    \sum_{n=0}^{K} (-1)^{K-n} \binom{K}{n}\,\fallingfact{T}{K-n}\, \sum_{m=0}^{n} \binom{n}{m} x^{m} T^{n-m}
    \\
    &=
    \sum_{n=0}^{K} \sum_{m=0}^{n} 
         x^m (-1)^{K-n} \binom{K}{n} \binom{n}{m}\,\fallingfact{T}{K-n} \,T^{n-m} 
   \\ 
   &\stackrel{(d)}{=}  
   \sum_{n=0}^{K} \sum_{m=0}^{n} 
     x^m  \binom{K}{m} (-1)^{K-n} \binom{K-m}{K-n}\,\fallingfact{T}{K-n} \,T^{n-m} 
   \\ 
   &= 
    \sum_{m=0}^{K} x^{m}\,\binom{K}{m}\left(\sum_{n=m}^{K} (-1)^{K-n} \binom{K-m}{K-n}\, T^{n-m}\,\fallingfact{T}{K-n}\right)
    \\ 
    &\stackrel{(e)}{=}     
    \sum_{m=0}^{K} x^{m}\,\binom{K}{m}\left(\sum_{d=0}^{K-m} (-1)^{d} \binom{K-m}{d}\, T^{K-m-d}\,\fallingfact{T}{d}\right)
    \\ 
    &\stackrel{(f)}{=} 
    \sum_{m=0}^{K} x^{m}\,\binom{K}{m}\left(\sum_{d=0}^{K-m} \sum_{i=0}^{d} (-1)^{d} \binom{K-m}{d}\, \stirling{d}{i}\, T^{K-(m+d-i)}\right)
    \\
    &\stackrel{(g)}{=} 
    \sum_{n=0}^{K} x^{K-n}\,\binom{K}{n}\left(\sum_{d=0}^{n} \sum_{i=0}^{d} (-1)^{d} \binom{m}{d}\, \stirling{d}{i}\, T^{n-(d-i)}\right),
\end{align*}
where the steps are justified as follows: 
\begin{enumerate}[label={$(\alph*)$}]
\item 
By definition of $\hatppolyfunction{T}{K}$ in \eqref{eq:expansion_of_hatppoly}.
\item 
Substitution  $n=K-m$.
\item 
From the binomial expansion
\(
    (x + T)^n \;=\; \sum_{m=0}^n \binom{n}{m}\,x^m\,T^{\,n-m}.
\)
\item 
By the identity
\(
    \binom{K}{n} \binom{n}{m} = \binom{K}{m} \binom{K-m}{n-m}.
\)
\item 
Substituting $d=K-n$.
\item 
By \lemmaref{lemma:falling_factorial_expansion}, 
which expresses the falling factorial in terms of Stirling numbers of the first kind.
\item 
Substituting $n=K-m$.
\end{enumerate}



\subsubsection{Derivation of the Explicit Form of \teq{$\betapolyfunction{T}{K}$} in 
\teq{\eqref{eq:expnasion_of_betapoly}}}
\label{appendix:derivation_of_the_explicit_form_of_betapoly}

\begin{align*}
    \betapoly{T}{K}{x} 
    &\stackrel{(a)}{=}
    \hatppoly{T}{K}{\sqrt{T} x}
    \\
    &\stackrel{(b)}{=} 
        \sum_{m=0}^{K} T^{\frac{K-m}{2}} x^{K-m} \,\binom{K}{m}\left(\sum_{d=0}^{m} \sum_{i=0}^{d} (-1)^{d} \binom{m}{d}\, \stirling{d}{i}\, T^{m-(d-i)}\right)
    \\
    &=
    \sum_{m=0}^{K} x^{K-m} \,\binom{K}{m} \, T^{\frac{K}{2}}
        \left(\sum_{d=0}^{m} \sum_{i=0}^{d} (-1)^{d} \binom{m}{d}\, \stirling{d}{i}\, T^{\frac{m}{2} -(d-i)}\right),
\end{align*}
where $(a)$ follows from our definition of $\betapolyfunction{T}{K}$ in \eqref{eq:expnasion_of_betapoly}, 
and in $(b)$ we substitute \eqref{eq:expansion_of_hatppoly}.
Denote
\begin{equation*}
    \widetilde{c}_{T,m} \eqdef \sum_{d=0}^{m} \sum_{i=0}^{d} (-1)^{d} \binom{m}{d}\, \stirling{d}{i}\, T^{\frac{m}{2}-(d-i)}.
\end{equation*}
It holds that 
\begin{align*}
    \widetilde{c}_{T,m}
    &= \sum_{d=0}^{m} \sum_{n=0}^{d} (-1)^{d} \binom{m}{d}\, \stirling{d}{d-n}\, T^{\frac{m}{2} -n }
    \\ 
    &=
    \sum_{n=0}^{m} \sum_{d=n}^{m} (-1)^{d} \binom{m}{d}\, \stirling{d}{d-n}\,T^{\frac{m}{2} -n }
    \\ 
    &= 
    \sum_{n=0}^{m} T^{\frac{m}{2} - n} \sum_{d=0}^{m} (-1)^{d} \binom{m}{d}\, \stirling{d}{d-n}  ,
\end{align*}
where the first equality follows by re-indexing with $n=d-i$.







