\subsection{The Schl\"{a}fli function and reduction formula}
%
Following the Kellerhals'-Schl\"{a}fli's method (see \cite{K91}), we consider Schl\"{a}fli function, which plays a principal role in volume computations.
We start with Schl\"{a}fli function on spherical space. A spherical orthoscheme $R$ of dimension $n$ is represented by a linear elliptic scheme $\Sigma$ (Coxeter graph) of order $n+1$. The Schl\"{a}fli normalized volume function for $R$ is formulated by
\begin{equation*}
    f_n\left(\Sigma \right):=c_n\cdot \mathrm{vol}\left(R \right), \notag
\end{equation*}
with $\displaystyle c_n=\frac{2^{n+1}}{\mathrm{vol}\left(\mathbb{S}^n\right)}=\frac{2^n}{\pi^{\left(\frac{n+1}{2} \right)}}\Gamma\left( \frac{n+1}{2}\right)$, and $f_0:=1$.\\
As it stated in \cite{K91}, that function was generalized for complete orthoscheme in hyperbolic space. Let $\Sigma_{d}$ be Coxeter graph of a complete orthoscheme $R_d$ of degree $d, 0\leq d \leq 2$ in $\mathbb{H}^n$. 
The Schl\"{a}fli's function $F$ for complete orthoscheme 
$R_d \subset \mathbb{H}^n$ with graph $\Sigma_d$ is defined by
\begin{equation}
    F_n\left(\Sigma_d\right):=i^{n}\cdot c_n\cdot\mathrm{vol}_n\left(R_d \right), \tag{4.2}
\end{equation}
where $F_0:=1$, $i^2=-1$, and 
\begin{equation*}
    c_n=\frac{2^n}{\pi^{\left(\frac{n+1}{2} \right)}}\Gamma\left( \frac{n+1}{2}\right). \tag{4.3}
\end{equation*}
Furthermore, the following Schl\"{a}fli reduction formula is the core in our computation.
%
\begin{theorem}[Schl\"{a}fli reduction formula \cite{K91}]\label{thm:reduction_schlafli}
Denote by $R_d \subset \mathbb{H}^{2n}$, $0\leq d \leq 2$, $n \geq 1$, a $2n$-dimensional orthoscheme of degree $d$ with scheme $\Sigma_{d}$. Then
\begin{equation}
F_{2n}\left( \Sigma_{d} \right)=\sum_{k=1}^{n}\frac{(-1)^k}{k+1}\begin{pmatrix}2k \\ k \end{pmatrix}\sum_{\sigma}f_{2n-(2k+1)}\left(\sigma \right), \tag{4.4}
\end{equation}
where $\sigma$ runs through all elliptic subschemes of order $2(n-k)$ of $\Sigma_d$ all of whose components are even order.
\end{theorem}
%
According to Theorem~\ref{thm:reduction_schlafli}, and our orthoscheme, we set $n=2$ (having $2n=4$ dimensional) and $d=1$ (simply truncated orthoscheme). 
\begin{equation*}
F_4\left(\Sigma_1\right)=\sum_{\sigma_4}f_3(\sigma_4)-\frac{1}{2}\begin{pmatrix} 2 \\ 1 \end{pmatrix}\sum_{\sigma_2}f_1(\sigma_2)+\frac{1}{3}\begin{pmatrix} 4 \\ 
2 \end{pmatrix}\sum_{\sigma_0}f_{-1}(\sigma_0),
\end{equation*}
where $\sigma_4,~\sigma_2,~\sigma_0$ are subschemes of order $4,~2,~0$ respectively.\\
We compute, $F_4\left(\Sigma_1\right)=\frac{2}{15}-\frac{2}{3p}$. On the other hand $F_4\left(\Sigma_1\right)=(-1)^{4} c_4Vol_{4}(R_1)$, 
where $c_4=\frac{12}{\pi^2}$. Thus, we obtain the following 
%
\begin{lemma} 
The volume $Vol_4(R_1)$ of the orthoscheme $R_1$ related to the Coxeter graph $\Sigma_1$ (see Fig.~\ref{Coxeter_graph}) is
\begin{equation}
Vol_4(R_1)=\frac{F_4(\Sigma_1)}{c_4}=\frac{\pi^2}{12}\left(\frac{2}{15}-\frac{2}{3p} \right). \tag{4.5}
\end{equation}
\end{lemma} 
