\subsection{Volume of hyperball part}
%
The volume of hyperball part with base $\mathcal{A}_3$ on a polar hyperplane, and height $h$ in $\mathbb{H}^4$ is given by formula (\ref{Eq:2.2}) {here, we set~$k=\sqrt{\frac{-1}{K}}=1$.

{\bf The maximum possible height} $h(p)$ of the hyperballs belonging to the simplex $\mathcal{S}(B_1,B_2,B_3,B_4,B_5)$ with base planes $\beta_i$ are exactly the half of the distance between any pair of polar hyperplane, precisely
\begin{equation}\label{Eq:4.9}
\begin{aligned}
h(p)&=\frac{1}{2}d(\beta_i,\beta_j)=\frac{1}{2}{\mathrm{arccosh}}{\left(-\frac{\langle \boldsymbol{b}_i, \boldsymbol{b}_j \rangle}{\sqrt{\langle \boldsymbol{b}_i, \boldsymbol{b}_i 
\rangle \langle \boldsymbol{b}_j, \boldsymbol{b}_j \rangle}}\right)}\\&=\frac{1}{2}{\mathrm{arccosh}}{\left(\frac{s^2+4}{4s^2-4}\right)}=\frac{1}{2}{\mathrm{arccosh}}
{\left(\frac{\cos{\left(\frac{2\pi}{p} \right)}}{3\cos{\left(\frac{2\pi}{p}\right)}-1}\right)}.
\end{aligned} \tag{4.9}
\end{equation}
%
The base $\mathcal{A}_3$ lies on $\beta_i$, can be obtained by considering the lines connecting the vertices of orthoschemes $P_0P_1P_2P_3$ to the ultra ideal point $B_1$. These lines intersect the polar hyperplane $\beta_1$ at namely $Q_0$, $Q_1$, $Q_2$, $Q_3$ respectively. These are $Q_0:=\overline{B_1P_0}\cap\beta_1$, $Q_1:=\overline{B_1P_1}\cap\beta_1$, $Q_2:=\overline{B_1P_2}\cap\beta_1$, $Q_3:=\overline{B_1P_3}\cap\beta_1$.
Based on some direct computations we obtain the Coxeter Schl\"{a}fli matrix of polyhedron $\mathcal{A}_3$ in $\mathbb{H}^3$ as follows
\begin{equation}
G_{\mathcal{A}_3}=\begin{pmatrix}
1& -\cos{\left(\frac{\pi}{p}\right)}& 0 & 0 \\ -\cos{\left(\frac{\pi}{p}\right)} & 1 & -\frac{1}{2} & 0 \\
0 & -\frac{1}{2} & 1 & -\frac{1}{2} \\
0 & 0 & -\frac{1}{2} & 1
\end{pmatrix}. \tag{4.10}
\end{equation}
Thus, the polyhedron $\mathcal{A}_3$ is a 3-orthoscheme. 
The volume of $\mathcal{A}_3$ can be directly computed by the Kellerhals formula \cite{K98}:
%
\begin{theorem}\label{Vol_Kellerhals} The volume of a three-dimensional hyperbolic
complete ortho\-scheme (e.g., without Lambert cube cases, where $a_0, a_3$ intersect each other) $\mathcal{R}$
is expressed with the essential angles $\alpha^{01},\alpha^{12},\alpha^{23}, (0 \le \alpha^{ij} \le \frac{\pi}{2})$ in the following:
\begin{align*}
&Vol_3(\mathcal{R})=\frac{1}{4} \{ \mathcal{L}(\alpha^{01}+\theta)-
\mathcal{L}(\alpha^{01}-\theta)+\mathcal{L}(\frac{\pi}{2}+\alpha^{12}-\theta)+ \notag \\
&+\mathcal{L}(\frac{\pi}{2}-\alpha^{12}-\theta)+\mathcal{L}(\alpha^{23}+\theta)-
\mathcal{L}(\alpha^{23}-\theta)+2\mathcal{L}(\frac{\pi}{2}-\theta) \}, 
\end{align*}
where $\theta \in [0,\frac{\pi}{2})$ is defined by the following formula:
$$
\tan(\theta)=\frac{\sqrt{ \cos^2{\alpha^{12}}-\sin^2{\alpha^{01}} \sin^2{\alpha^{23}
}}} {\cos{\alpha^{01}}\cos{\alpha^{23}}}
$$
and, where $\mathcal{L}(x):=-\int\limits_0^x \log \vert {2\sin{t}} \vert dt$ \ denotes the
Lobachevsky function.
\end{theorem}
%
As a consequence, applying this for $Q_0Q_1Q_2Q_3$ orthoscheme we obtain the explicit expression
%
\begin{equation}\label{Vol_A3}
\begin{aligned}
Vol_3(\mathcal{A}_3)=&\frac{1}{4} \{ \mathcal{L}(\frac{\pi}{p}+\theta)-
\mathcal{L}(\frac{\pi}{p}-\theta)+\mathcal{L}(\frac{\pi}{2}+\frac{\pi}{3}-\theta)+ \notag \\
&+\mathcal{L}(\frac{\pi}{2}-\frac{\pi}{3}-\theta)+\mathcal{L}(\frac{\pi}{3}+\theta)-
\mathcal{L}(\frac{\pi}{3}-\theta)+2\mathcal{L}(\frac{\pi}{2}-\theta) \},\\
&\text{where, } \theta:=\theta(p)=\arctan{\left(\frac{\sqrt{1-3\sin^2{\left( \frac{\pi}{p}\right)}}}{\cos{\left(\frac{\pi}{p} \right)}} \right)}.
\end{aligned} \tag{4.11}
\end{equation}
In essence, the volume of base $\mathcal{A}_3$ is completely depend on the parameter $p$. It is then reasonable to write $Vol_3(\mathcal{A}_3):=Vol_3\left(\mathcal{A}_3(p)\right)$.
%
\subsection{The local density of hyperball packings related to simplex $\mathcal{S}(B_1,B_2,B_3,B_4,B_5)$ }
%
The density of hyperball packing in a regular truncated simplex $\mathcal{S}(B_1,B_2,B_3,B_4,B_5)$ } can be defined as a comparison between the volume sum of hyperball parts lying in the simplex and the volume of the truncated simplex. It is clear, that it is equal to the ratio of the volume of the hybeball part contained by the $R_1$ orthoscheme to the volume of the $R_1$ orthoscheme.
%
\begin{definition}\label{def:density}
 The local density $\delta(p)$ of the congruent hyperball packings related to the regular truncated simplices is 
 \begin{equation}
\delta{(p)}=\frac{Vol_4(\mathcal{H}^{h^+(p)}_4(\mathcal{A}_3(p)))}{Vol_4\left(R_1(p) \right)}, \notag
\end{equation}
\begin{center}
where $\displaystyle \frac{\pi}{\arccos{\left( \sqrt{\frac{2}{3}}\right)}} < p < \frac{\pi}{\arccos{\left( \sqrt{\frac{3}{4}}\right)}}$.
\end{center}
\end{definition}
%
Using Definition \ref{def:density} and formulas (\ref{Eq:4.9}), (\ref{Vol_A3})  and Lemma \ref{Lemma:p_value} we obtain the following 
%
\begin{theorem}\label{thm:local_density}
The locally optimal congruent hyperball packing density related to the regular truncated simplices for a given possible parameter $p$ is: 
\begin{equation}
\delta{(p)}=\frac{\frac{1}{8}Vol_3(\mathcal{A}_3(p))\cdot k \cdot \left[\frac{2}{3}\sinh{\left(\frac{3h(p)}{k}\right)}+
6\sinh{\left(\frac{h(p)}{k} \right)}\right]}{\frac{\pi^2}{12}\left(\frac{2}{15}-\frac{2}{3p}\right)} \notag
\end{equation}
where $\displaystyle h(p)=\frac{1}{2}{\mathrm{arccosh}}{\left(\frac{\cos{\left(\frac{2\pi}{p} \right)}}{\left\lvert 3\cos{\left(\frac{2\pi}{p}\right)}-1\right\rvert}\right)}$ and $\frac{\pi}{\arccos{\left( \sqrt{\frac{2}{3}}\right)}} < p < \frac{\pi}{\arccos{\left( \sqrt{\frac{3}{4}}\right)}}$. Here we set the constant curvature $k=\sqrt{\frac{-1}{K}}=1$. \quad \quad $\square$
\end{theorem} 

To determine the densest possible hyperball arrangement for regular truncated 4-dimensional simplices, we need to examine the density function defined in Theorem \ref{thm:local_density}, which depends on the variable $p$. 

