\subsection{Matrix-Free HOSFEM Kernels}
For simplicity, we define $N_1 = N + 1$. Taking the Helmholtz/Poisson equation as an example, we introduce the fundamental principles of the matrix-free method. The Helmholtz equation is defined as:
\begin{equation}
  \label{Helmholtz_equation}
  - \nabla \cdot (\lambda_0(\bm{x}) \nabla \bm{u}(\bm{x})) + \lambda_1(\bm{x}) \bm{u}(\bm{x}) = \bm{f}(\bm{x}), \quad\bm{x} \in \Omega \subset \mathbb{R}^3,
\end{equation}
where: 1) $\bm{u}$ is the unknown scalar ($d = 1$) or vector ($d = 3$) field. 2) $\bm{f}$ is the source term. 3) $\lambda_0(\bm{x})$ and $\lambda_1(\bm{x})$ are given scalar fields. It reduces to the Poisson equation when $\lambda_0(\bm{x}) \equiv 1$ and $\lambda_1(\bm{x}) \equiv 0$. After HOSFEM discretization, the linear system is $\mathbf{A}\mathbf{u} = \mathbf{b}$, where
\begin{equation}
  \mathbf{A} = \mathbf{Q}^\mathrm{T}
  \begin{bmatrix}
    \mathbf{A}^{(0)} &                  &        &                      \\
                     & \mathbf{A}^{(1)} &        &                      \\
                     &                  & \ddots &                      \\
                     &                  &        & \mathbf{A}^{(E - 1)}
  \end{bmatrix}
  \mathbf{Q}.
\end{equation}
Here, for each element $e$, the local $N_1^3 \times N_1^3$ matrix is given by:
{\small
\begin{equation}
  \label{local_matrix_structure}
  \mathbf{A}^{(e)} = \mathbf{D}^\mathrm{T}
  \begin{bmatrix}
      \mathbf{\Lambda}_0^{(e)} &                      &                      \\
                           & \mathbf{\Lambda}_0^{(e)} &                      \\
                           &                      & \mathbf{\Lambda}_0^{(e)}
    \end{bmatrix}
    \begin{bmatrix}
      \mathbf{G}_{00}^{(e)} & \mathbf{G}_{01}^{(e)} & \mathbf{G}_{02}^{(e)} \\
      \mathbf{G}_{01}^{(e)} & \mathbf{G}_{11}^{(e)} & \mathbf{G}_{12}^{(e)} \\
      \mathbf{G}_{02}^{(e)} & \mathbf{G}_{12}^{(e)} & \mathbf{G}_{22}^{(e)}
    \end{bmatrix}
  \mathbf{D} + \mathbf{\Lambda}_1^{(e)} \mathbf{G}_\mathrm{wj}^{(e)},
\end{equation}
}
where:
\begin{itemize}
  \setlength{\itemsep}{0pt}
  \setlength{\parsep}{0pt}
  \setlength{\parskip}{0pt}
  \item $\mathbf{\Lambda}_0^{(e)}$ and $\mathbf{\Lambda}_1^{(e)}$ are diagonal matrices of size $N_1^3 \times N_1^3$, with their diagonal elements representing the values of $\lambda_0(\bm{x})$ and $\lambda_1(\bm{x})$ at each node in element $e$.
  \item All geometric factors of element $e$ form 7 diagonal matrices of size $N_1^3 \times N_1^3$: $\mathbf{G}_{00}^{(e)}$, $\mathbf{G}_{01}^{(e)}$, $\mathbf{G}_{02}^{(e)}$, $\mathbf{G}_{11}^{(e)}$, $\mathbf{G}_{12}^{(e)}$, $\mathbf{G}_{22}^{(e)}$, $\mathbf{G}_\mathrm{wj}^{(e)}$.
  \item $\mathbf{D}$ is the discrete form of the gradient $\nabla$, defined as
  \begin{equation}
    \mathbf{D} :=
    \begin{bmatrix}
      \mathbf{D}_r \\
      \mathbf{D}_s \\
      \mathbf{D}_t
    \end{bmatrix} :=
    \begin{bmatrix}
      \mathbf{I} \otimes \mathbf{I} \otimes \hat{\mathbf{D}}_N \\
      \mathbf{I} \otimes \hat{\mathbf{D}}_N \otimes \mathbf{I} \\
      \hat{\mathbf{D}}_N \otimes \mathbf{I} \otimes \mathbf{I}
    \end{bmatrix},
  \end{equation}
  where $\mathbf{I}$ is the identity matrix of size $N_1 \times N_1$ and $\otimes$ denotes the tensor-product operation. $\mathbf{D}$ has size $3N_1^3 \times N_1^3$.
\end{itemize}
$\mathbf{A}$ is of size $\mathcal{N} \times \mathcal{N}$. Matrix-based methods, such as those used in HPCG, store $\mathbf{A}$ in a sparse format and compute $\mathbf{Y} = \mathbf{A} \mathbf{X}$ through sparse matrix-vector multiplication (SpMV). In contrast, HOSFEM does not store $\mathbf{A}$ or even $\mathbf{A}^{(e)}$, but rather utilizes Algorithm \ref{matrix_free_matrix_vector_algo}. Although the gather-scatter kernel performs the multiplication of $\mathbf{Q}$ (or $\mathbf{Q}^\mathrm{T}$) and the vector, in practice, $\mathbf{Q}$ and $\mathbf{Q}^\mathrm{T}$ are never explicitly constructed. Instead, their actions are implemented within the communication library gslib.
\begin{algorithm}
  \fontsize{7.8}{7.8}\selectfont
  % \DontPrintSemicolon
	\caption{Matrix-free method for $\mathbf{Y} = \mathbf{A}\mathbf{X}$}
  \label{matrix_free_matrix_vector_algo}
  \SetKwInOut{Input}{\textbf{Input}}
  \SetKwInOut{Output}{\textbf{Output}}
  \SetKwInOut{Init}{\textbf{Init}}
  \SetKw{KwDStep}{\textbf{step}}
  \SetKw{KwDAnd}{\textbf{and}}
  \SetKw{KwDIn}{\textbf{in}}
  \Input{$\mathbf{\Lambda}_0^{(e)}$, $\mathbf{\Lambda}_1^{(e)}$, $\mathbf{G}_{00}^{(e)}$, ..., $\mathbf{G}_{22}^{(e)}$, $\mathbf{G}_\mathrm{wj}^{(e)}$, $\hat{\mathbf{D}}_N$: sub-blocks in Eq. \eqref{local_matrix_structure}.
    $\quad\quad\quad\quad\quad\quad$$\mathbf{X}$: $\mathcal{N} \times d$ matrix ($d$ vectors).
    $\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad\quad$$\mathbf{Q}$: global-to-local matrix.
  }
  \Output{$\mathbf{Y}$: $\mathcal{N} \times d$ matrix.
  }
  $\{\mathbf{X}^{(e)}\} \leftarrow \mathrm{scatter}(\mathbf{Q}, \mathbf{X})$\tcp*[r]{\color{gray}global-to-local, $\mathbf{X}^{(e)}$: $N_1^3 \times d$ \\ $\{\mathbf{X}^{(e)}\}$: shorthand for set $\{\mathbf{X}^{(e)} | 0 \leq e < E\}$}
  $\{\mathbf{Y}^{(e)}\} \leftarrow \mathrm{axhelm}(\{\mathbf{\Lambda}_0^{(e)}, \mathbf{\Lambda}_1^{(e)}, \mathbf{G}_{00}^{(e)}, ..., \mathbf{G}_{22}^{(e)}, \mathbf{G}_\mathrm{wj}^{(e)}, \mathbf{X}^{(e)}\}, \hat{\mathbf{D}}_N)$\;
  $\mathbf{Y} \leftarrow \mathrm{gather}(\mathbf{Q}^\mathrm{T}, \{\mathbf{Y}^{(e)}\})$\tcp*[r]{\color{gray}local-to-global, $\mathbf{Y}^{(e)}$: $N_1^3 \times d$}
\end{algorithm}

